INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (13, 5, 'Dimethyl ether: A review of technologies and production challenges', '["Zoha Azizi","Mohsen Rezaeimanesh","Tahere Tohidian","Mohammad Reza Rahimpour"]', 2014, 'Chemical Engineering and Processing: Process Intensification', '10.1016/j.cep.2014.06.007', NULL, NULL, '[]', 'Finished', '[]', '', NULL, NULL, NULL, NULL, NULL, '2025-11-02T15:51:41.552Z', '2025-11-02T15:52:27.162Z', NULL, 4, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (483, 2, 'Multi-scale modeling and optimization of CO₂ hydrogenation to light olefins via deep learning and optimization algorithms', '[]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109233', NULL, NULL, '[]', 'To Read', '[]', '<div><ul data-path-to-node="4,1,1"><li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p></li><li><p data-path-to-node="7,1,1,0,0"><span class="citation-37 interactive-span-hovered"></span></p><p data-path-to-node="7,1,1,0,1"><span data-path-to-node="7,1,1,0,1,0"><b><span class="citation-37 interactive-span-hovered">&nbsp;- Destekleyici:</span></b><span class="citation-37 interactive-span-hovered"> Makale, RL algoritmalarının (özellikle TD3 ve PPO) karmaşık kimyasal reaksiyon sistemlerini optimize etmede başarılı olduğunu kanıtlamaktadır</span></span><span data-path-to-node="7,1,1,0,1,1"><span class="citation-37 citation-end-37 interactive-span-hovered"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="11"></sup></span></span><span data-path-to-node="7,1,1,0,1,2">. Referans projenizdeki "RL ajanlarının dinamik koşullara adapte olabilme" hipotezini destekler niteliktedir.</span></p></li><li><p><br></p></li></ul><span data-path-to-node="7,1,1,1,0,0"><b>- Destekleyici:</b> Klasik yöntem (IP) ile RL''in karşılaştırılması, sizin PID vs RL karşılaştırmanız için metodolojik bir dayanak oluşturur. </span><span data-path-to-node="7,1,1,1,0,1"><span class="citation-36"></span></span><span data-path-to-node="7,1,1,1,0,2"><span class="citation-36">Makale, klasik yöntemin "statik" başarısına karşı RL''in "dinamik" ve "belirsizlik altındaki" başarısını vurgular</span></span><span data-path-to-node="7,1,1,1,0,3"><span class="citation-36 citation-end-36"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="12"></sup></span></span><span data-path-to-node="7,1,1,1,0,4">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><b>- Alternatif Bakış:</b> Sizin projenizde kullanmayı planladığınız <b>SAC (Soft Actor-Critic)</b> algoritması bu makalede yoktur; ancak makalede en başarılı olan <b>TD3</b>, SAC ile benzer bir "off-policy" ve "actor-critic" yapıdadır. Bu durum, SAC seçiminizin doğruluğuna dair dolaylı bir işarettir.</div><div><br></div><div><br></div><div><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><span class="citation-35"></span></p><p data-path-to-node="7,2,1,0,1"><span data-path-to-node="7,2,1,0,1,0"><b><span class="citation-35">- Algoritma Seçimi:</span></b><span class="citation-35"> Makalede DDPG''nin kararsız olduğu ve başlangıçta performans düşüklüğü yaşadığı belirtilmiştir</span></span><span data-path-to-node="7,2,1,0,1,1"><span class="citation-35 citation-end-35"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="13"></sup></span></span><span data-path-to-node="7,2,1,0,1,2">. Sizin projenizde SAC kullanmanız (veya TD3''ü alternatif B planı olarak düşünmeniz) bu bulguyla örtüşüyor. DDPG yerine daha modern algoritmaların (TD3/SAC/PPO) seçilmesi gerektiğini kanıtlıyor.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><br></p></li></ol><span data-path-to-node="7,2,1,1,1,0"><b><span class="citation-34">- Simülasyon-Gerçeklik Uyuşmazlığı (Sim-to-Real):</span></b><span class="citation-34"> Makale, simülasyon ile gerçek (veya karmaşık model) arasındaki farkı kapatmak için </span><b><span class="citation-34">"Domain Randomization" (Alan Rastgeleleştirme)</span></b><span class="citation-34"> tekniğini kullanmıştır</span></span><span data-path-to-node="7,2,1,1,1,1"><span class="citation-34 citation-end-34"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="14"></sup></span></span><span data-path-to-node="7,2,1,1,1,2">. Sizin projenizde de gürültü ve bozulma senaryolarında bu terimi ve yöntemi metodolojinize ekleyebilirsiniz.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><span data-path-to-node="7,2,1,2,1,0"><b><span class="citation-33">- Vekil Model (Surrogate Model) Fikri:</span></b><span class="citation-33"> Eğer CSTR simülasyonunuz (IP1 aşaması) eğitim sırasında çok yavaş kalırsa, bu makaledeki gibi bir RNN (LSTM) vekil modeli eğiterek RL ajanını onun üzerinde hızla eğitebileceğinizi B Planı olarak not edebilirsiniz</span></span><span data-path-to-node="7,2,1,2,1,1"><span class="citation-33 citation-end-33"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="15"></sup></span></span><span data-path-to-node="7,2,1,2,1,2">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><br></div><div><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><span class="citation-32"></span></p><p data-path-to-node="7,3,1,0,1"><span data-path-to-node="7,3,1,0,1,0"><b><span class="citation-32">- Güvenlik (Safety):</span></b><span class="citation-32"> Bu makale ödül fonksiyonunu "Verim Maksimizasyonu" üzerine kurmuştur</span></span><span data-path-to-node="7,3,1,0,1,1"><span class="citation-32 citation-end-32"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="16"></sup></span></span><span data-path-to-node="7,3,1,0,1,2">. Sizin projenizdeki "Fizik Tabanlı Güvenlik Ödülü" (termal kaçak önleme) bu makalede eksiktir. Bu durum, projenizin <b>özgün değerini</b> artıran bir farktır.</span></p></li></ul><br></div><div>-<b>&nbsp;Sistem:</b> CSTR''lerin kararlılık sorunları (çoklu durağan hal) sabit yataklı reaktörlerden farklıdır. Sizin probleminiz kontrol teorisi açısından daha kaotik olabilir.</div>', '<span data-path-to-node="4,0,1,0"><b><span class="citation-17">Amaç:</span></b><span class="citation-17"> Çalışma, </span><span class="math-inline" data-math="CO_2"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span style="margin-right: 0.0715em;" class="mord mathnormal"><span class="citation-17">C</span></span><span class="mord"><span style="margin-right: 0.0278em;" class="mord mathnormal"><span class="citation-17">O</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.0278em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="citation-17">2</span></span></span></span></span><span class="vlist-s"><span class="citation-17">​</span></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span><span class="citation-17">''in hafif olefinlere hidrojenasyonu sürecini optimize etmek için derin öğrenme (DL) tabanlı vekil modeller ile gelişmiş optimizasyon algoritmalarını (Interior-Point ve RL) entegre etmeyi amaçlamaktadır</span></span><span data-path-to-node="4,0,1,1"><span class="citation-17 citation-end-17"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="4,0,1,2">. </span><span data-path-to-node="4,0,1,3"><span class="citation-16"></span></span><span data-path-to-node="4,0,1,4"><span class="citation-16">Geleneksel yöntemlerin hesaplama yükünü azaltmak ve dinamik koşullar altında reaktör performansını (propilen verimini) maksimize etmek hedeflenmiştir</span></span><span data-path-to-node="4,0,1,5"><span class="citation-16 citation-end-16"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="4,0,1,6">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><span class="citation-15"></span></p><p data-path-to-node="4,1,1,0,1"><span data-path-to-node="4,1,1,0,1,0"><b><span class="citation-15">Sistem:</span></b><span class="citation-15"> Bir boyutlu (1D) sabit yataklı (fixed-bed) reaktör modeli (plug-flow) kullanılmıştır</span></span><span data-path-to-node="4,1,1,0,1,1"><span class="citation-15 citation-end-15"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="3"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="3"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="3"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="3"></sup></span></span><span data-path-to-node="4,1,1,0,1,2">. (Not: Referans projedeki CSTR''den farklıdır).</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><span data-path-to-node="4,1,1,1,1,0"><b><span class="citation-14">Yapay Zeka Modelleri:</span></b><span class="citation-14"> Prosesi simüle etmek için FNN, CNN ve RNN (LSTM) mimarileri kıyaslanmış, RNN en iyi vekil model olarak seçilmiştir</span></span><span data-path-to-node="4,1,1,1,1,1"><span class="citation-14 citation-end-14"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="4"></sup></span></span><span data-path-to-node="4,1,1,1,1,2">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><p data-path-to-node="4,1,1,2,0"><b>Kontrol/Optimizasyon Algoritmaları:</b></p><ol start="1" data-path-to-node="4,1,1,2,1"><li><p data-path-to-node="4,1,1,2,1,0,0"><span class="citation-13"></span></p><p data-path-to-node="4,1,1,2,1,0,1"><span data-path-to-node="4,1,1,2,1,0,1,0"><b><span class="citation-13">Klasik:</span></b><span class="citation-13"> Interior-Point (IP) yöntemi (Statik optimizasyon için)</span></span><span data-path-to-node="4,1,1,2,1,0,1,1"><span class="citation-13 citation-end-13"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="5"></sup></span></span><span data-path-to-node="4,1,1,2,1,0,1,2">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><br></p></li></ol><br><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0"><span class="citation-11"></span></p><p data-path-to-node="4,2,1,0,1"><span data-path-to-node="4,2,1,0,1,0"><b><span class="citation-11">Optimizasyon Başarısı:</span></b><span class="citation-11"> IP yöntemi ile statik optimizasyonda %37,66 verim elde edilmiştir</span></span><span data-path-to-node="4,2,1,0,1,1"><span class="citation-11 citation-end-11"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="7"></sup></span></span><span data-path-to-node="4,2,1,0,1,2">. </span><span data-path-to-node="4,2,1,0,1,3"><span class="citation-10"></span></span><span data-path-to-node="4,2,1,0,1,4"><span class="citation-10">Dinamik RL optimizasyonunda ise TD3 algoritması en yüksek ödül değerine (%34,02 verim karşılığı) ulaşmıştır</span></span><span data-path-to-node="4,2,1,0,1,5"><span class="citation-10 citation-end-10"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="8"></sup></span></span><span data-path-to-node="4,2,1,0,1,6">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><span data-path-to-node="4,2,1,1,1,0"><b><span class="citation-9">Algoritma Performansı:</span></b><span class="citation-9"> PPO en kararlı ve hızlı öğrenen algoritma olurken, TD3 en yüksek performansı sağlamış, DDPG ise kararsızlık göstermiştir</span></span><span data-path-to-node="4,2,1,1,1,1"><span class="citation-9 citation-end-9"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="9"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="9"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="9"></sup></span></span><span data-path-to-node="4,2,1,1,1,2">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><span data-path-to-node="4,2,1,2,1,0"><b><span class="citation-8">Hız:</span></b><span class="citation-8"> RNN tabanlı eğitim ortamı, ilk prensip modele göre eğitimi yaklaşık %56 oranında hızlandırmıştır (18 dk yerine 8 dk)</span></span><span data-path-to-node="4,2,1,2,1,1"><span class="citation-8 citation-end-8"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="10"></sup></span></span><span data-path-to-node="4,2,1,2,1,2">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><br></div><p><br></p></li></ul></div><p><br></p></li></ul><br></div>', NULL, NULL, NULL, NULL, '2025-11-22T22:10:24.294Z', '2025-11-30T15:43:01.744Z', 'client_1763443786605_6w2tm45ddct', 13, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (484, 2, 'On ReLU neural networks as piecewise linear surrogate models', '["Amirhossein Hosseini","Martin Guay","Xiang Li"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109208', NULL, NULL, '["Temel Teori","ReLU Activation","CPWL (Continuous Piecewise Linear)","Network Efficiency","Dead Neurons","Neural Network Theory","Surrogate Modeling","Mathematical Optimization"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Teorik Eleştiri (Nötr/Karşıt):</b> Projenizde kullanacağınız SAC (Soft Actor-Critic) algoritması, Actor ve Critic ağlarında büyük ihtimalle <b>ReLU</b> aktivasyon fonksiyonu kullanacaktır. Bu makale, ReLU ağlarının gereksiz "ölü bölgeler" (redundancy) yarattığını ve matematiksel olarak verimsiz olabileceğini savunmaktadır. Bu, ağınızın neden bazen yavaş öğrendiğini veya bazı durumlarda takılı kaldığını açıklayan teorik bir bilgi olabilir.</p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Metodolojik Fark:</b> Makale, sinir ağını bir optimizasyon probleminin içine (constraint olarak) gömmeyi hedefler. Sizin projenizde ise sinir ağı, ajanın kendisidir (policy function).</p></li></ul><div><br></div></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar:</b></p><ol start="1" data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>- Ağ Mimarisi Seçimi:</b> RL ajanınızı tasarlarken (İP 2.3), sinir ağı katman sayısını (derinlik) ve nöron sayısını (genişlik) belirleyeceksiniz. Bu makale, "daha büyük ağ her zaman daha iyi değildir, gereksiz (redundant) bölgeler yaratır" diyerek sizi <b>aşırı büyük ağlar kurmaktan kaçınmaya</b> teşvik eder.</p></li><li><p data-path-to-node="7,2,1,1,0"><b>- Aktivasyon Fonksiyonu Alternatifleri:</b> Eğer ReLU tabanlı SAC ajanınız eğitimde kararsızlık (instability) yaşarsa, bu makaleyi referans göstererek "ReLU''nun yarattığı yozlaşma (degeneracy) sorunları nedeniyle Leaky-ReLU veya Tanh gibi alternatifler denendi" şeklinde bir tartışma zemini oluşturabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,2,0"><b>- Vekil Model (Opsiyonel):</b> Eğer simülasyonunuz (Python/SciPy) RL eğitimi için çok yavaş kalırsa, bu makaledeki gibi bir "Vekil Model" (Surrogate Model) oluşturarak eğitimi hızlandırma fikrini B Planı olarak düşünebilirsiniz.</p></li></ol></li><div><br></div><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Dinamik vs Statik:</b> Makale statik veri setleri (regresyon) üzerinedir. Sizin projeniz zaman serisi ve dinamik sistem kontrolü (CSTR diferansiyel denklemleri) üzerinedir.</p></li><li><p data-path-to-node="7,3,1,1,0"><b>- Güvenlik:</b> Makalede fiziksel kısıtlar veya güvenlik (safety) analizi yoktur; sadece matematiksel temsil verimliliği vardır.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Makale, karmaşık doğrusal olmayan ilişkileri temsil etmek için kullanılan ReLU (Rectified Linear Unit) aktivasyon fonksiyonlu sinir ağlarının (ReLU-NN), <b>Sürekli Parçalı Doğrusal (CPWL)</b> modeller olarak nasıl davrandığını incelemektedir. ReLU ağlarının oluşturduğu doğrusal bölgelerin (linear regions) yapısını analiz ederek; <b>fazlalık (redundancy)</b>, <b>yozlaşma (degeneracy)</b> ve <b>düşük verimlilik</b> gibi yapısal sorunlarını ortaya koymayı ve buna alternatif olarak <b>DC-CPWL</b> (Difference-of-Convex) yöntemini önermeyi amaçlar.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Teorik Analiz:</b> Küçük ölçekli ReLU ağlarının aktivasyon desenleri (activation patterns) ve doğrusal bölgeleri için kesin matematiksel ifadeler türetilmiştir.</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Karşılaştırma:</b> Sığ (shallow) ve Derin (deep) ReLU ağları ile DC-CPWL modelleri karşılaştırılmıştır.</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Vaka Çalışmaları:</b> Gaz iletim kompresörü, damıtma kolonu, gaz türbini ve DME-DEE kimyasal üretim tesisi verileri üzerinde vekil (surrogate) modelleme yapılmıştır.</p></li></ul><div><br></div></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- ReLU ağları, veri setini açıklamak için gerekenden çok daha fazla (veya boş/etkisiz) aktivasyon deseni oluşturarak <b>düşük verimlilik</b> sergilemektedir (Örneğin bir vaka çalışmasında verimlilik %0.0078 bulunmuştur).</p></li><li><p data-path-to-node="4,2,1,1,0">- DC-CPWL yöntemi, ReLU ağlarına göre daha az parametre ile daha verimli ve matematiksel optimizasyon (MILP/MIQP) için daha uygun modeller sunmaktadır.</p></li></ul></li>', 4, 'papers/2/484/On_ReLU_neural_networks_as_piecewise_linear_surrogate_models.pdf', NULL, NULL, '2025-11-22T22:10:25.107Z', '2026-02-05T17:17:27.347Z', 'client_1764520808415_rtrnhcg8a37', 11, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (485, 2, 'Optimal control of scheduling and production for a multienzymatic system in continuous reactors', '["Pablo Silva","Felipe Scott","Sai Darshan Adloor","Vassilios S. Vassiliadis","Andrés Illanes","Lorena Wilson","Raúl Conejeros"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109209', NULL, NULL, '["Rakip Yaklaşım","Alternatif Yöntem","Enzyme Deactivation","Bang-Bang Control","Mixed-Integer Optimal Control (MIOCP)","Catalyst Lifetime","Optimal Control","Chemical Reactor Scheduling","CSTR Optimization"]', 'To Read', '[]', '<li><p data-path-to-node="6,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0"><b>- Karşıt/Alternatif (Rakip Yöntem):</b> Bu makale, sizin projenizdeki RL ajanının yapmaya çalıştığı işi (optimal kontrolü), yapay zeka kullanmadan, <b>türev tabanlı matematiksel optimizasyonla</b> yapan bir yaklaşımdır. Tezinizde "RL dışındaki gelişmiş yöntemler nelerdir?" sorusuna verilecek en güzel cevaptır.</p></li><li><p data-path-to-node="6,1,1,1,0"><b>- Destekleyici (Model Davranışı):</b> Makale, katalizör aktivitesi düştükçe sıcaklığın artırılması gerektiğini gösteriyor. Sizin RL ajanınızın da benzer bir "telafi edici davranış" (compensatory behavior) öğrenip öğrenmediğini kontrol etmek için bu bilgiyi <b>kıyaslama zemini</b> olarak kullanabilirsiniz.</p></li></ul><div><br></div></li><li><p data-path-to-node="6,2,0"><b>Proje İçin Kritik Çıkarımlar:</b></p><ol start="1" data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0"><b>- "Bang-Bang" Kontrol:</b> Makale, optimal çözümün genellikle uç noktalarda (tam açık/tam kapalı veya değiştir/değiştirme) olduğunu bulmuştur. Sizin RL ajanınızın aksiyon uzayını (Action Space) tasarlarken, sürekli (continuous) aksiyonlar yerine ayrık (discrete) aksiyonların bazı durumlarda (özellikle vanalar veya on/off kararları için) daha verimli olabileceğine dair bir ipucu verir.</p></li><li><p data-path-to-node="6,2,1,1,0"><b>- Deaktivasyon Modellemesi:</b> Sizin projenizde "Termal Kaçak" riski var. Bu makalede ise "Enzim Deaktivasyonu" (katalizörün ölmesi) riski var. Her ikisi de sistemin zamanla performansını düşüren dinamiklerdir. RL ajanının ödül fonksiyonuna, reaktörün "sağlığını" korumaya yönelik terimler eklerken bu makaledeki yaklaşımı (katalizör ömrünü uzatma stratejisi) ilham alabilirsiniz.</p></li><li><p data-path-to-node="6,2,1,2,0"><b>- CSTR vs PBR:</b> Sizin projeniz CSTR odaklı. Bu makale, CSTR''nin PBR''ye göre bazı dezavantajlarını (daha sık bakım/değişim gerektirmesi gibi) vurguluyor. Tartışma bölümünde, "Neden CSTR seçildi?" veya "RL, CSTR''nin bu dezavantajlarını kapatabilir mi?" gibi soruları tartışırken bu makaleye atıf yapabilirsiniz.</p></li></ol><div><br></div></li><li><p data-path-to-node="6,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="6,3,1"><li><p data-path-to-node="6,3,1,0,0"><b>- Güvenlik:</b> Makale tamamen kâr maksimizasyonuna odaklanmış, patlama/taşma gibi güvenlik sınırlarını (safety constraints) sizin projenizdeki kadar merkeze almamıştır.</p></li><li><p data-path-to-node="6,3,1,1,0"><b>- Yöntem:</b> RL (Model-free) yerine Model-based Optimal Control kullanılmıştır. Bu, sistemin modelinin mükemmel bilindiği varsayımına dayanır. Sizin projenizdeki RL ise model belirsizliklerine karşı daha dirençli olabilir.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Çalışma, laktozdan fruktoz üretimi yapan çoklu enzim sistemleri (multi-enzymatic) için sürekli reaktörlerde (CSTR ve PBR) ekonomik kârı maksimize etmeyi hedefler. Temel odak, biyokatalizörlerin zamanla aktivite kaybetmesi (deaktivasyon) sorununa karşı en uygun "katalizör değiştirme zamanlamasını" ve "işletim koşullarını" (sıcaklık, akış hızı) belirlemektir.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Sistem:</b> Sürekli Karıştırmalı Tank Reaktör (CSTR) ve Dolgulu Yatak Reaktör (PBR).</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Yöntem:</b> Problemi bir "Çok Aşamalı Karışık Tam Sayılı Optimal Kontrol Problemi" (MSMIOCP) olarak formüle etmişler, ancak tamsayı değişkenleri gevşeterek (relaxation) Doğrusal Olmayan Programlama (NLP) teknikleriyle çözmüşlerdir.</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Model:</b> Enzim deaktivasyonu için iki aşamalı seri mekanizma ve Michaelis-Menten kinetiği kullanılmıştır.</p></li></ul><div><br></div></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0"><b>- Kontrol Politikası:</b> Katalizör değişimi için "Bang-bang" (ya hep ya hiç) tipi bir kontrol politikası optimal bulunmuştur.</p></li><li><p data-path-to-node="4,2,1,1,0"><b>- Reaktör Kıyaslaması:</b> PBR, CSTR''ye göre daha yüksek talep karşılama kapasitesi ve verimlilik sunmuştur. CSTR''de 16 haftada 3 kez katalizör değişimi gerekirken, PBR''de sadece 1 kez gerekmiştir.</p></li><li><p data-path-to-node="4,2,1,2,0"><b>&nbsp;- Sıcaklık Kontrolü:</b> Enzim aktivitesi düştükçe, reaksiyon hızını korumak için sıcaklığın kademeli olarak artırılması gerektiği (klasik bir kimya mühendisliği prensibi) matematiksel olarak doğrulanmıştır.</p></li></ul></li>', 5, NULL, NULL, NULL, '2025-11-22T22:10:25.910Z', '2025-11-30T15:48:40.038Z', 'client_1763443786605_6w2tm45ddct', 9, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (486, 2, 'Accelerating process synthesis with reinforcement learning: Transfer learning from multi-fidelity simulations and variational autoencoders', '["Qinghe Gao","Haoyu Yang","Maximilian F. Theisen","Artur M. Schweidtmann"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109192', NULL, NULL, '["Metodolojik İyileştirme","Negative Transfer","Surrogate Modeling","Shortcut Models","PPO","Training Acceleration","Reinforcement Learning Optimization","Transfer Learning","Process Systems Engineering"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Destekleyici (Yöntem):</b> Makale, RL ajanlarının karmaşık simülasyonlarda (sizin CSTR modeliniz gibi) eğitilmesinin zor ve yavaş olduğunu kabul eder. Buna çözüm olarak "önce basit modelde öğren, sonra zor modele geç" stratejisini kanıtlarla destekler.</p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Uyarıcı (Negatif Transfer):</b> Sizin projenizde RL ajanını eğitirken "ödül fonksiyonunu" değiştirirseniz veya model parametrelerini çok oynarsanız, ajanın kafasının karışabileceği (performans düşüşü) konusunda sizi uyarır.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>- Eğitim Hızlandırma Stratejisi (Curriculum Learning):</b> Eğer CSTR simülasyonunuz (İP1 aşaması) RL eğitimi sırasında çok yavaş çalışırsa, bu makaledeki T1 stratejisini uygulayabilirsiniz: Önce CSTR''nin çok basitleştirilmiş (belki lineerleştirilmiş veya düşük çözünürlüklü) bir versiyonunda ajanı eğitin, sonra bu "bilgili" ajanı asıl non-lineer modelinize transfer edin. Bu, "Risk Yönetimi" tablonuzdaki B planlarından biri olabilir.</p></li><li><p data-path-to-node="7,2,1,1,0"><b>- Vekil Modeller (Surrogate Models):</b> Makale, titiz simülatörler yerine "shortcut" modeller kullanmanın eğitim başında faydalı olduğunu gösteriyor. Siz de CSTR''nin termal dinamiklerini temsil eden basit bir Python fonksiyonunu "vekil" olarak kullanıp ilk 10.000 adımı burada atabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,2,0"><b>- Ajan Mimarisi:</b> Makale, ajanın "karar verme" (Actor) ve "değer biçme" (Critic) katmanlarının hangilerinin transfer edilmesi gerektiğini tartışır. Sizin projenizde Actor ağını transfer edip, Critic ağını sıfırlamak (veya tam tersi) gibi ince ayar teknikleri için bir referans noktasıdır.</p></li></ol><div><br></div></li><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Kontrol vs Tasarım:</b> Makalede ajan bir "akış şeması" çiziyor (ünite ekle/çıkar). Sizin ajanınız ise bir vanayı açıp kapatıyor (sürekli kontrol). Aksiyon uzaylarınız farklı (Discrete/Hierarchical vs Continuous).</p></li></ul></li><br>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Makale, kimyasal süreç 
sentezi (process synthesis) problemlerinde RL ajanlarının eğitiminin çok
 uzun sürmesi ve yüksek hesaplama gücü gerektirmesi sorununu çözmeyi 
hedefler. Temel amaç, <b>Transfer Öğrenme (Transfer Learning)</b> stratejileri kullanarak eğitimi hızlandırmak ve yakınsama başarısını artırmaktır.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Sistem:</b> Kavramsal süreç tasarımı (akış şeması oluşturma).</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Algoritma:</b> PPO (Proximal Policy Optimization) kullanılmıştır.</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Transfer Stratejileri:</b> İki ana strateji test edilmiştir:</p><ol start="1" data-path-to-node="4,1,1,2,1"><li><p data-path-to-node="4,1,1,2,1,0,0"><b>- T1 (Kısayol <span class="math-inline" data-math="\to"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.3669em;"></span><span class="mrel">→</span></span></span></span></span> Titiz):</b>
 Ajan önce basit/kısayol (shortcut) modeller üzerinde eğitilmiş, 
ardından öğrenilen bilgiler titiz (rigorous) simülatöre (DWSIM) 
aktarılmıştır.</p></li><li><p data-path-to-node="4,1,1,2,1,1,0"><b>- T2 (VAE <span class="math-inline" data-math="\to"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.3669em;"></span><span class="mrel">→</span></span></span></span></span> Titiz):</b>
 Bir Varyasyonel Otokodlayıcı (Variational Autoencoder - VAE) 
kullanılarak süreç topolojileri öğrenilmiş ve bu bilgi aktarılmıştır.</p></li></ol></li><li><div><br></div></li></ul></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0"><b>- Başarı:</b>
 Basit modellerden titiz modellere transfer (T1), eğitim süresini ciddi 
oranda kısaltmış (%99''a varan hızlanma) ve nihai performansı 
artırmıştır.</p></li><li><p data-path-to-node="4,2,1,1,0"><b>- Negatif Transfer:</b>
 Eğer kaynak (basit model) ve hedef (titiz model) arasında ödül 
fonksiyonu veya değişken aralıklarında çok büyük farklar varsa, transfer
 öğrenme performansı düşürebilir (Negative Transfer).</p></li><li><p data-path-to-node="4,2,1,2,0"><b>- Verimlilik:</b> Ön eğitimli (pre-trained) ajanlar, sıfırdan başlayanlara göre uygulanabilir çözümlere çok daha hızlı ulaşmıştır.</p></li></ul></li>', 6, 'papers/2/486/Accelerating_process_synthesis_with_reinforcement_learning.pdf', NULL, NULL, '2025-11-22T22:10:26.721Z', '2026-01-21T22:49:29.508Z', 'client_1763443786605_6w2tm45ddct', 7, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (487, 2, 'A digital twin simulator of a pastillation process with applications to automatic control based on computer vision', '["Leonardo D. González","Joshua L. Pulsipher","Shengli Jiang","Angan Mukherjee","Tyler Soderstrom","Victor M. Zavala"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109205', NULL, NULL, '["Metodolojik Alternatif / Kıyaslama Tabanı","Computer Vision","Bayesian Optimization","Synthetic Data Generation","Convolutional Neural Networks (CNN)","Digital Twin","Soft Sensing","Process Control","PID Optimization"]', 'To Read', '[]', '<li><p data-path-to-node="5,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b>- Alternatif (Sensör Odaklı Yaklaşım):</b> Sizin projenizde RL ajanı doğrudan kontrol (aksiyon) yaparken, bu makalede YZ (CNN) sadece "gözlem" (sensing) yapıyor, kontrolü yine PID yapıyor. Bu, RL''in "kara kutu" olmasından çekinen endüstriyel yaklaşımlara bir alternatiftir.</p></li><li><p data-path-to-node="5,1,1,1,0"><b>- Destekleyici (Simülasyonun Önemi):</b> Makale, YZ modellerini eğitmek için gerçek verinin yetersiz olduğu durumlarda (özellikle arıza senaryoları için) <b>sentetik veri üreten bir simülatörün (Digital Twin)</b> ne kadar kritik olduğunu vurgular. Sizin CSTR simülasyonunuz da tam olarak bu amaca hizmet etmektedir.</p></li></ul><div><br></div></li><li><p data-path-to-node="5,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b>- Gelişmiş PID Kıyaslaması (Bayesian Tuning):</b> Sizin projenizde RL''i "Geleneksel PID" ile kıyaslayacaksınız. Bu makale, PID parametrelerini (Kp, Ki, Kd) deneme-yanılma yerine <b>Bayesian - Optimizasyon</b> ile optimize etmiştir. Eğer RL ajanınızı, rastgele ayarlanmış bir PID yerine, bu şekilde optimize edilmiş bir PID ile kıyaslarsanız, tezinizin bilimsel değeri çok artar (RL''in gerçekten "en iyi" PID''den bile iyi olduğunu kanıtlamak gibi).</p></li><li><p data-path-to-node="5,2,1,1,0"><b>- Gözlemlenebilirlik (Observability):</b> Makale, sistemin durumunu (sıcaklık) ölçmek için sanal sensörler kullanıyor. Sizin CSTR projenizde tüm durum değişkenleri (konsantrasyon, sıcaklık) doğrudan ölçülebilir varsayılıyor mu? Eğer ölçülemiyorsa, bir "State Estimator" (Durum Tahmincisi) gerekliliğini tartışma bölümüne ekleyebilirsiniz.</p></li><li><p data-path-to-node="5,2,1,2,0"><b>- Simülasyon Doğrulama:</b> Simülatörün "gerçekçi" veriler üretmesi için fiziksel yasalar (ısı denklemleri) kullanılmıştır. Sizin de CSTR modelinizin fiziksel tutarlılığını (kütle/enerji denkliği) vurgulamanız önemlidir.</p></li></ol></li><div><br></div><li><p data-path-to-node="5,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0"><b>- Kontrol Yöntemi:</b> Makale RL kullanmıyor.</p></li><li><p data-path-to-node="5,3,1,1,0"><b>- Problem:</b> Termal kaçak gibi bir güvenlik problemi yok, daha çok ürün spesifikasyonunu tutturma problemi var.</p></li></ul></li><br>', '<li><p data-path-to-node="3,0,0"><b>Amaç:</b> Makale, pastilasyon (sıvı 
eriyiğin katı damlacıklara dönüştürülmesi) süreci için yüksek doğruluklu
 bir dijital ikiz simülatörü geliştirmeyi amaçlar. Bu simülatör, termal 
kamera görüntüleri üreterek, yapay zeka tabanlı (CNN) yumuşak 
sensörlerin eğitilmesini ve bu sensörlerden gelen verilerle sürecin 
otomatik geri beslemeli kontrolünü (PID) sağlamayı hedefler.</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b>- Sistem:</b> Pastilasyon konveyör bandı (mekansal dağılımlı sistem).</p></li><li><p data-path-to-node="3,1,1,1,0"><b>- Yapay Zeka:</b> Konveyör bandının termal görüntülerini işleyerek sıcaklık ve akış hızı tahmini yapan Evrişimli Sinir Ağları (CNN - PaNet).</p></li><li><p data-path-to-node="3,1,1,2,0"><b>- Kontrol:</b> CNN''den gelen tahminleri kullanarak konveyör hızını ayarlayan <b>PID kontrolcü</b>. PID parametreleri <b>Bayesian Optimizasyon (VP-BO)</b> ile otomatik olarak ayarlanmıştır.</p></li></ul><div><br></div></li><li><p data-path-to-node="3,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- Geliştirilen PaNet-1D modeli, sıcaklık tahmininde <span class="math-inline" data-math="1.3^\circ F"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord">1.</span><span class="mord"><span class="mord">3</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height: 0.6741em;"><span class="" style="top: -3.063em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span style="margin-right: 0.1389em;" class="mord mathnormal">F</span></span></span></span></span>''dan düşük hata (RMSE) ile yüksek doğruluk sağlamıştır.</p></li><li><p data-path-to-node="3,2,1,1,0">-
 Bayesian Optimizasyon ile ayarlanan PID kontrolcü, set noktası 
değişikliklerine hızlı tepki vermiş ve üretim verimliliğini korumuştur.</p></li><li><p data-path-to-node="3,2,1,2,0">-
 Dijital ikiz, gerçek dünyada elde edilmesi zor olan "arıza" (tıkanma) 
senaryolarını simüle ederek kontrol sisteminin dayanıklılığını test etme
 imkanı sunmuştur.</p></li></ul></li>', 4, 'papers/2/487/A_digital_twin_simulator_of_a_pastillation_process_with_applications_to_automatic_control_based_on_computer_vision.pdf', 2944636, NULL, '2025-11-22T22:10:27.378Z', '2026-02-05T17:17:27.043Z', 'client_1764520808415_rtrnhcg8a37', 7, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (488, 2, 'A hybrid Kalman filter and physics-informed neural network approach for leakage detection and localization in heat exchanger networks', '["Ming Shi","Lin Sun","Zhongcheng Bi","Renchu He"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109259', NULL, NULL, '["Metodolojik Tamamlayıcı","Kalman Filter","Physics-Informed Neural Networks (PINN)","Noise Reduction","Heat Exchanger Fouling/Leakage","Fault Detection and Diagnosis (FDD)","Hybrid AI Systems","State Estimation"]', 'To Read', '[]', '<li><p data-path-to-node="5,1,0"><b>Destekleyici/Karşıt Nitelik:s</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b>- Destekleyici (Hibrit Mimari):</b> Sizin projeniz "PID + RL" (Hibrit Kontrol) öneriyor. Bu makale de "Kalman Filtresi + Sinir Ağı" (Hibrit İzleme) öneriyor. Her iki çalışma da tek başına YZ''nin veya tek başına klasik yöntemlerin yetersiz kaldığı durumlarda, ikisinin birleşiminin daha üstün olduğunu savunmaktadır.</p></li><li><p data-path-to-node="5,1,1,1,0"><b>- Destekleyici (Fiziksel Kısıtlar):</b> Bu makalede PINN kullanılarak YZ''nin fiziksel yasaları ihlal etmesi engellenmiştir. Sizin projenizde de RL ajanının ödül fonksiyonuna fiziksel güvenlik cezaları eklenmesi ("Physics-Informed Reward Shaping") aynı amaca hizmet etmektedir.</p></li></ul><div><br></div></li><li><p data-path-to-node="5,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b>- Gözlemci Tasarımı (State Estimation):</b> Sizin CSTR projenizde, reaktör içindeki konsantrasyonu veya anlık ısı üretim hızını doğrudan ölçemeyebilirsiniz. Bu makaledeki gibi bir <b>- Kalman Filtresi (KF)</b> kullanarak, gürültülü sıcaklık verisinden bu gizli durumları tahmin edip RL ajanına "State" olarak verebilirsiniz. Bu, RL ajanının başarısını dramatik şekilde artırabilir.</p></li><li><p data-path-to-node="5,2,1,1,0"><b>-&nbsp;Güvenlik Katmanı:</b> RL ajanınızın karar vermeden önce, sistemin sağlığını kontrol eden bir "Arıza Tespit Modülü"ne ihtiyacı olabilir. Bu makaledeki yöntem, reaktör ceketinde bir sızıntı veya kirlenme (fouling) olup olmadığını anlamak için kullanılabilir.</p></li><li><p data-path-to-node="5,2,1,2,0"><b>- Gürültü Dayanıklılığı:</b> Makale, sensör gürültüsünün YZ modellerini nasıl şaşırttığını ve KF''nin bunu nasıl çözdüğünü gösteriyor. Simülasyonunuza "ölçüm gürültüsü" (measurement noise) eklerseniz, KF kullanımını bir B Planı veya iyileştirme olarak sunabilirsiniz.</p></li></ol></li><div><br></div><li><p data-path-to-node="5,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0"><b>- Kontrol Yok:</b> Makale sadece "Burada sızıntı var" diyor, "Vanayı kapat" demiyor. Karar mekanizması eksik.</p></li><li><p data-path-to-node="5,3,1,1,0"><b>- RL Değil:</b> Kullanılan YZ modeli Supervised Learning (Gözetimli Öğrenme) tabanlıdır, Pekiştirmeli Öğrenme (RL) değildir.</p></li></ul></li>', '<li><p data-path-to-node="3,0,0"><b>Amaç:</b> Isı değiştirici ağlarında (Heat Exchanger Networks - HEN) enerji verimliliğini ve güvenliği tehdit eden sızıntıların (leakage) gerçek zamanlı tespiti ve yerinin belirlenmesi (localization).</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b>- Sistem:</b> Ham petrol damıtma ünitesi öncesi ısı değiştirici ağı.</p></li><li><p data-path-to-node="3,1,1,1,0"><b>Hibrit Yapı:</b></p><ol start="1" data-path-to-node="3,1,1,1,1"><li><p data-path-to-node="3,1,1,1,1,0,0"><b>- Kalman Filtresi (KF):</b> Gürültülü sensör verilerini temizlemek ve sızıntıya duyarlı olan "Isı Transfer Katsayısı (<span class="math-inline" data-math="K"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span style="margin-right: 0.0715em;" class="mord mathnormal">K</span></span></span></span></span>)" parametresini tahmin etmek için kullanılmıştır (Durum Tahmini / State Estimation).</p></li><li><p data-path-to-node="3,1,1,1,1,1,0"><b>- PINN (Physics-Informed Neural Networks):</b> KF''den gelen temizlenmiş verileri kullanarak ve fiziksel yasalarla (kütle/enerji korunumu) sınırlandırılmış bir kayıp fonksiyonu (loss function) ile eğitilerek sızıntının yerini tespit etmiştir.</p></li></ol></li><li><div><br></div></li></ul></li><li><p data-path-to-node="3,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- %1 kadar küçük sızıntı oranlarını bile başarıyla tespit etmiştir.</p></li><li><p data-path-to-node="3,2,1,1,0">- Geleneksel YSA (ANN) ve Rastgele Orman (RF) modellerine göre tahmin hatasını (RMSE) %7-15 oranında düşürmüştür.</p></li><li><p data-path-to-node="3,2,1,2,0">- Çıkarım süresi (inference time) 0.76 ms olup gerçek zamanlı uygulamalar için uygundur.</p></li></ul></li>', 5, 'papers/2/488/A_hybrid_Kalman_filter_and_physics-informed_neural_network_approach_for_leakage_detection_and_localization_in_heat_exchanger_networks.pdf', 5751443, NULL, '2025-11-22T22:10:28.034Z', '2026-02-05T17:17:26.732Z', 'client_1763443786605_6w2tm45ddct', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (489, 2, 'A practical reinforcement learning control design for nonlinear systems with input and output constraints', '["Hesam Hassanpour","Brandon Corbett","Prashant Mhaskar"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109248', NULL, NULL, '["Metodolojik İyileştirme","Warm-Starting (Pre-training)","Constraint Satisfaction","TD3 vs MPC","Reward Shaping for Safety","Safe Reinforcement Learning","Process Control","Hybrid Control Strategies"]', 'To Read', '[]', '<p data-path-to-node="5,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><span class="citation-83"></span></p><p data-path-to-node="5,1,1,0,1"><span data-path-to-node="5,1,1,0,1,0"><b><span class="citation-83">- Destekleyici (Hipotez Doğrulama):</span></b><span class="citation-83"> Makale, "Klasik kontrolcüler (MPC/PID) lineer olmayan durumlarda yetersiz kalır, RL bunları geçebilir" hipotezinizi </span></span><span data-path-to-node="5,1,1,0,1,1"><span class="citation-83 citation-end-83"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="5,1,1,0,1,2"> doğrudan destekler.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div></li><li><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,1,0"><b>- Destekleyici (Yöntem):</b> RL''in sıfırdan eğitilmesinin tehlikeli olabileceği, bu yüzden klasik bir yöntemle (sizde PID, burada MPC) "ısıtılması" (warm-start) gerektiği fikri, projenizin uygulanabilirliğini artıracak bir B planıdır.</p></li></ul></li><li><div><br></div></li><li><p data-path-to-node="5,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><span class="citation-82"></span></p><p data-path-to-node="5,2,1,0,1"><span data-path-to-node="5,2,1,0,1,0"><b><span class="citation-82">- Ödül Fonksiyonu Tasarımı:</span></b><span class="citation-82"> Makale, kısıt ihlalleri için ödül fonksiyonunda nasıl bir "Ceza Mekanizması" (</span><span class="math-inline" data-math="\beta_1, \beta_2"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8889em; vertical-align: -0.1944em;"></span><span class="mord"><span style="margin-right: 0.0528em;" class="mord mathnormal"><span class="citation-82">β</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.0528em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="citation-82">1</span></span></span></span></span><span class="vlist-s"><span class="citation-82">​</span></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct"><span class="citation-82">,</span></span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span style="margin-right: 0.0528em;" class="mord mathnormal"><span class="citation-82">β</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.0528em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="citation-82">2</span></span></span></span></span><span class="vlist-s"><span class="citation-82">​</span></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span><span class="citation-82"> katsayıları ile) kurduğunu açıkça formüle etmiştir</span></span><span data-path-to-node="5,2,1,0,1,1"><span class="citation-82 citation-end-82"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="5,2,1,0,1,2">. Sizin projenizdeki "Fizik Tabanlı Ödül Fonksiyonu"nu tasarlarken bu formülasyonu (Constraint Penalties) doğrudan adapte edebilirsiniz. Örneğin, reaktör sıcaklığı <span class="math-inline" data-math="T_{max}"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span style="margin-right: 0.1389em;" class="mord mathnormal">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span>''ı geçerse verilecek cezanın matematiksel yapısını buradan alabilirsiniz.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div></li><li><p data-path-to-node="5,2,1,1,0"><b>- Eğitim Stratejisi (Risk Yönetimi):</b> Risk Yönetimi tablonuzda "RL ajanının kararsızlığı" riskine karşı bir B planı olarak; <b>"Ajanı önce PID verileriyle eğitip (Pre-training), sonra serbest bırakma"</b> stratejisini ekleyebilirsiniz. Bu makale, bu yöntemin çalıştığının akademik kanıtıdır.</p></li><li><p data-path-to-node="5,2,1,2,0"><b>- Algoritma Kıyaslaması:</b> Makale TD3 kullanmıştır. Sizin SAC kullanmanız (ki TD3''ün entropi eklenmiş, daha kararlı halidir) bu makaledeki başarıyı daha da ileri taşıyabileceğinizi gösterir.</p></li></ol><div><br></div></li><li><p data-path-to-node="5,3,0"><b>Eksik/Farklı Yönler:</b></p></li><li><p data-path-to-node="5,3,1,0,0"><b>- Fiziksel Yasalar:</b> Makale kısıtları matematiksel sınırlar (bounds) olarak ele alır. Sizin projenizdeki gibi "Enerji Denkliği" veya "Termodinamik Yasalar" doğrudan ödül fonksiyonunun içinde (Physics-Informed) değildir; daha çok "Ceza Tabanlı" (Constraint-Based) bir yaklaşımdır.</p></li><li><p><br></p></li></ul>', '<li><p data-path-to-node="3,0,0"><b>Amaç:</b> Makale, süreç kontrolünde RL kullanımının önündeki en büyük engellerden biri olan "eğitim sırasında rastgele keşif (exploration) yaparken güvenli sınırların (constraints) ihlal edilmesi" sorununu çözmeyi hedefler. Amaç, RL ajanını önce güvenli bir şekilde eğitmek (offline), sonra performansı artırmak için sisteme sürmektir (online).</p></li><div>s</div><div><br></div><li><p data-path-to-node="3,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b>- Sistem:</b> pH Nötralizasyon Süreci (CSTR içinde, yüksek derecede doğrusal olmayan bir süreç).</p></li><li><p data-path-to-node="3,1,1,1,0"><b>- Algoritma:</b> TD3 (Twin Delayed Deep Deterministic Policy Gradient) - (Sizin SAC seçiminize çok yakın, modern bir Actor-Critic algoritması).</p></li></ul><div><br></div></li><div><br></div><div><br></div><li><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,2,0"><b>Strateji (Hibrit Yaklaşım):</b></p><ol start="1" data-path-to-node="3,1,1,2,1"><li><p data-path-to-node="3,1,1,2,1,0,0"><b>- Ön Eğitim (Warm-Start):</b> RL ajanı sıfırdan başlamaz. Önce, var olan bir <b>Model Öngörülü Kontrolcüden (MPC)</b> elde edilen verilerle "taklit ederek" (Behavior Cloning) eğitilir.</p></li><li><p data-path-to-node="3,1,1,2,1,1,0"><b>- Çevrimiçi Öğrenme:</b> Ajan, MPC''yi taklit edecek seviyeye gelince sisteme bağlanır ve MPC''nin lineer modelinin yakalayamadığı "doğrusal olmayan" dinamikleri öğrenerek performansı artırır.</p></li></ol></li><li><p data-path-to-node="3,1,1,3,0"><b>- Kısıt Yönetimi:</b> Giriş ve çıkış kısıtları (örn: vana hızı, pH sınırları) ödül fonksiyonuna ceza terimleri olarak eklenmiştir.</p></li></ul><div><br></div></li><div><br></div><div><br></div><li><p data-path-to-node="3,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- Ön eğitimli RL ajanı, başlangıçta MPC''nin performansını birebir kopyalayabilmiştir (Güvenli Başlangıç).</p></li><li><p data-path-to-node="3,2,1,1,0">- Çevrimiçi öğrenme sürecinde RL ajanı, MPC''den <b>daha iyi</b> bir performans sergilemiş ve kısıtları (constraints) ihlal etmeden süreci yönetmiştir.</p></li><li><p data-path-to-node="3,2,1,2,0">- Ödül fonksiyonuna eklenen ceza terimleri, ajanın kısıtlar dışına çıkmasını başarıyla engellemiştir.</p></li></ul></li>', 8, 'papers/2/489/A_practical_reinforcement_learning_control_design_for_nonlinear_systems_with_input_and_output_constraints.pdf', 6180735, NULL, '2025-11-22T22:10:28.690Z', '2026-02-05T17:17:26.427Z', 'client_1764520808415_rtrnhcg8a37', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (490, 2, 'BioProcessNexus: An open-source platform for surrogate techno economic models', '["Tommaso De Santis","Matthias Medl","Peter Satzer","Gerald Striedner"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109220', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-11-22T22:10:29.541Z', '2025-11-29T10:47:32.008Z', 'client_1764169542328_bqvfg4cnetr', 2, '2025-11-29T10:47:32.007Z');
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (491, 2, 'Building hybrid AI models in chemical engineering: A tutorial review', '["Arijit Chakraborty","Naz Pinar Taskiran","Rishab Kottooru","Vipul Mann","Venkat Venkatasubramanian"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109236', NULL, NULL, '["Metodolojik Dayanak","Residual Modeling","Domain Knowledge Integration","Safe AI","Constraint Imposition","Hybrid AI","Physics-Informed Machine Learning (PIML)","Chemical Engineering Methodology"]', 'To Read', '[490]', '<li><p data-path-to-node="5,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b>- Destekleyici (Teorik Zemin):</b> Sizin projenizdeki <b>"Physics-Informed Reward Shaping"</b> (Fiziksel yasaları ödül fonksiyonuna ekleme) yaklaşımı, bu makaledeki <b>"Şablon 3: Ek Kısıtlamalar Ekleme (Imposing Additional Constraints)"</b> başlığıyla birebir örtüşmektedir.</p></li><li><p data-path-to-node="5,1,1,1,0"><b>- Destekleyici (Hibrit Yapı):</b> Projenizdeki <b>PID + RL (Residual RL)</b> yapısı, makalede bahsedilen <b>"Residual Modeling"</b> (Mekanistik modelin hatasını YZ ile düzeltme) kavramının kontrol teorisindeki karşılığıdır. Bu makaleyi referans göstererek yönteminizin literatürdeki yerini sağlamlaştırabilirsiniz.</p></li><li><p data-path-to-node="5,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ol start="1" data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b>- Metodolojinizi Sınıflandırma:</b> Tezinizin "Yöntem" kısmında, geliştirdiğiniz RL modelini bu makaledeki şablonlara göre sınıflandırabilirsiniz. Örneğin: <i>"Geliştirilen model, Chakraborty ve ark. (2025) tarafından tanımlanan ''Şablon 3: Ek Kısıtlamalar Ekleme'' (Ödül Fonksiyonu yoluyla) ve ''Şablon 5: Özel Model Mimarisi'' (Hibrit Kontrol) kategorilerine girmektedir."</i> demek tezinize akademik bir ağırlık katar.</p></li><li><p data-path-to-node="5,2,1,1,0"><b>- Güvenlik ve Açıklanabilirlik Argümanı:</b> Makale, saf YZ''nin mühendislikte neden riskli olduğunu (fiziksel yasaları ihlal edebilmesi) çok iyi açıklar. Giriş bölümünüzde, CSTR''de neden sadece RL değil de "Fizik Tabanlı RL" kullandığınızı savunurken bu argümanları kullanabilirsiniz.</p></li><li><p data-path-to-node="5,2,1,2,0"><b>-Bilgi Değerlendirmesi (Stage 1):</b> CSTR simülasyonunuzu tasarlarken, makalenin önerdiği "Hangi fiziksel yasalar (kütle/enerji) modele gömülmeli, hangileri YZ''ye bırakılmalı?" sorusunu sormak, model tasarımınızı netleştirecektir.</p></li><li><p data-path-to-node="5,2,1,2,0"><br></p></li></ol></li><li><p data-path-to-node="5,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0"><b>- Uygulama:</b> Makale genel kimya mühendisliği (termodinamik, ilaç keşfi vb.) örnekleri verirken, siz dinamik süreç kontrolüne odaklanıyorsunuz.</p></li></ul></li>', '<li><p data-path-to-node="3,0,0"><b>Amaç:</b> Makale, modern Makine 
Öğrenmesi (ML) yöntemlerinin (özellikle Büyük Dil Modelleri ve Kara Kutu
 modellerin) mühendislik uygulamalarındaki "açıklanabilirlik", 
"halüsinasyon" ve "fiziksel yasalara uyum" sorunlarını ele alır. Bu 
sorunları aşmak için alan bilgisini (Domain Knowledge) yapay zeka ile 
birleştiren <b>Hibrit Yapay Zeka (Hybrid AI)</b> modellerinin nasıl geliştirileceğine dair sistematik bir yol haritası sunar.</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b>- 4 Aşamalı Çerçeve:</b> (1) Bilgi Değerlendirmesi, (2) Alan Bilgisi Destekli Problem Formülasyonu, (3) Model Seçimi, (4) Doğrulama.</p></li><li><p data-path-to-node="3,1,1,1,0"><b>- 6 Hibritleşme Şablonu (Templates):</b>
 Özellik Mühendisliği''nden (Feature Engineering) başlayıp, Özel Bilgi 
Temsili, Ek Kısıtlamalar Ekleme (Constraints) ve Uçtan Uca (End-to-End) 
Hibrit Modellere kadar uzanan bir sınıflandırma sunar.</p></li></ul><div><br></div></li><li><p data-path-to-node="3,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- Saf veri odaklı (data-driven) modeller, fiziksel yasaları bilmedikleri için mühendislikte güvenilmez olabilir.</p></li><li><p data-path-to-node="3,2,1,1,0">-
 Klasik yöntemler (First-principles) ile YZ''nin birleştirilmesi 
(Hibrit), özellikle veri azlığında ve güvenlik gerektiren durumlarda 
daha üstün performans ve güvenilirlik sağlar.</p></li><li><p data-path-to-node="3,2,1,2,0"><b>- "Physics-Informed Neural Networks (PINN)"</b> ve <b>"Residual Modeling" (Artık Modelleme)</b> gibi teknikler, bu hibritleşmenin en başarılı örneklerindendir.</p></li><li><p data-path-to-node="3,2,1,2,0">s</p></li></ul></li>', 8, 'papers/2/491/Building_hybrid_AI_models_in_chemical_engineering_A_tutorial_review.pdf', 2306359, NULL, '2025-11-22T22:10:30.200Z', '2026-02-05T17:17:26.120Z', 'client_1764520808415_rtrnhcg8a37', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (492, 2, 'Computing control invariant set using reinforcement learning by leveraging default value function', '["Song Bo","Bernard T. Agyeman","Benjamin Decardi-Nelson","Haihan Wang","Jinfeng Liu"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109249', NULL, NULL, '["Temel Teori","Güvenlik Modülü","Control Invariant Set (CIS)","CSTR Safety Constraints","Deep Q-Learning","Value Function Approximation","Process Safety","Safe Reinforcement Learning","Nonlinear Systems Control"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Destekleyici:</b> Projenizdeki "RL, PID''den daha güvenlidir" hipotezini destekler niteliktedir. Çünkü bu makale, RL''in sadece performans maksimizasyonu değil, aynı zamanda sistemin güvenli sınırlarını (termal kaçak sınırlarını) öğrenmek için de kullanılabileceğini kanıtlamaktadır.</p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Destekleyici:</b> "Physics-Informed" yaklaşımınızı destekler; çünkü makale, fiziksel kısıtların (constraints) ihlal edilmesini doğrudan negatif ödül olarak tanımlayarak ajanı eğitmiştir.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar:</b></p><ol start="1" data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>- Güvenlik Kalkanı (Safety Shield):</b> Projenizdeki Hibrit RL yapısında, PID''nin veya RL ajanının ürettiği aksiyonları denetleyen bir "Güvenlik Katmanı" tasarlayabilirsiniz. Bu makaledeki yöntemle CSTR''nizin "Güvenli Bölge Haritasını" (CIS) çıkarıp, ajan bu haritanın dışına çıkmaya çalıştığında müdahale eden bir mekanizma kurgulayabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><b>- Ödül Fonksiyonu Tasarımı:</b> Makalede kullanılan "Kısıt ihlali varsa negatif sabit ödül, yoksa 0" mantığı, sizin "Fizik Tabanlı Ödül Fonksiyonunuz" içine bir ceza terimi olarak entegre edilebilir.</p></li><li><p data-path-to-node="7,2,1,2,0"><b>- Başlangıç Değeri (Initialization):</b> Makale, RL ajanının değer fonksiyonunu (Value Function) sıfır veya iyimser başlatmanın, güvenli bölgeyi keşfetmede kritik olduğunu belirtiyor. Bu, eğitim stabilitesi için projenize transfer edilebilir.</p></li><li><p data-path-to-node="7,2,1,2,0"><br></p></li></ol></li><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0">- Bu makale bir "kontrolör" (set point takibi yapan) değil, bir "sınır belirleyici" (neresi güvenli neresi değil) üzerinedir. Sizin projeniz ise aktif kontrol (set point takibi) yapmayı hedefliyor. Bu makaleyi, kontrolcünüzün "güvenlik modülü" olarak konumlandırabilirsiniz.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Makale, genel doğrusal olmayan sistemler (örneğin CSTR) için "Kontrol Değişmez Kümesi"ni (Control Invariant Set - CIS) hesaplamak amacıyla bir Pekiştirmeli Öğrenme (RL) çerçevesi sunmaktadır. Temel amaç, sistemin güvenli sınırlar (constraints) içinde sonsuza kadar kalabileceği durum uzayını (state space), karmaşık geometrik varsayımlara girmeden, sadece RL etkileşimleri ile belirlemektir.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Sistem:</b> Sürekli Karıştırmalı Tank Reaktörü (CSTR). (Tekli ve Çoklu Reaksiyonlu senaryolar).</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Algoritma:</b> Tabular Q-Learning ve Deep Q-Learning (DQN).</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Yaklaşım:</b> Özel bir ödül fonksiyonu tasarımı ve değer fonksiyonu (Value Function) başlatması kullanılmıştır. Güvenli durumlar negatif olmayan bir değere yakınsarken, kısıt ihlaline (termal kaçak gibi) giden durumlar negatif birikimli değere sahip olacak şekilde kodlanmıştır.</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Geliştirilen RL tabanlı yöntem, sistemin güvenli çalışma bölgesini (CIS) başarıyla haritalandırmıştır.</p></li><li><p data-path-to-node="4,2,1,1,0">- CSTR üzerindeki denemelerde, RL ile bulunan güvenli bölge sınırları, mevcut grafik tabanlı (graph-based) matematiksel yöntemlerle elde edilen sonuçlarla örtüşmüştür.</p></li><li><p data-path-to-node="4,2,1,2,0">- Yöntem, sistemin "güvenli" ve "güvensiz" bölgelerini, modelin karmaşık lineer olmayan dinamiklerine rağmen yüksek doğrulukla ayırabilmiştir.</p></li><li><p data-path-to-node="4,2,1,2,0">s</p></li></ul></li>', 9, 'papers/2/492/Computing_control_invariant_set_using_reinforcement_learning_by_leveraging_default_value_function.pdf', 3148895, NULL, '2025-11-22T22:10:30.856Z', '2026-02-05T17:17:25.815Z', 'client_1764520808415_rtrnhcg8a37', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (493, 2, 'Continuous learning of the value function utilizing deep reinforcement learning to be used as the objective in model predictive control', '["Daniel Beahr","Elijah Hedrick","Debangsu Bhattacharyya"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109262', NULL, NULL, '["Metodolojik Destek","Teorik Temel","Safe RL","Value Function Approximation","SCR Unit","Adaptive Control","Process Control","Reinforcement Learning","Hybrid Control Systems","Plant-Model Mismatch"]', 'To Read', '[]', '<p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b> <b>Güçlü Şekilde Destekleyici ve Tamamlayıcı</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><span data-path-to-node="7,1,1,0,0,0"><b>- Hipotez Doğrulaması:</b> Referans projenizdeki "Hibrit (Artık) RL" yaklaşımının temel motivasyonu olan "Klasik kontrolcünün güvenilirliği ile YZ''nin adaptasyon yeteneğini birleştirme" fikrini destekler. </span><span data-path-to-node="7,1,1,0,0,1"><span class="citation-137"></span></span><span data-path-to-node="7,1,1,0,0,2"><span class="citation-137">Makale, RL''in "kara kutu" risklerini azaltmak için klasik bir kontrolcü (burada MPC, sizde PID) çatısı altında çalışmasının güvenliği artırdığını savunmaktadır</span></span><span data-path-to-node="7,1,1,0,0,3"><span class="citation-137 citation-end-137"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="10"></sup></span></span><span data-path-to-node="7,1,1,0,0,4">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><b>- Dinamik Değişim:</b> Projenizde <i>bozulma senaryoları</i> (disturbance) test edilecekken, bu makale <i>tesis-model uyuşmazlığı</i> (katalizör bozunması) üzerine odaklanmıştır. Bu, YZ''nin klasik yöntemlere göre "adaptasyon" üstünlüğünü kanıtlamak için projenizde ek bir argüman olarak kullanılabilir.</p></li></ul><div><br></div><div><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><span class="citation-136"></span></p><p data-path-to-node="7,2,1,0,1"><span data-path-to-node="7,2,1,0,1,0"><b><span class="citation-136">- Güvenlik Yaklaşımı:</span></b><span class="citation-136"> Makale, "Safe RL" (Güvenli RL) kavramına atıfta bulunarak, kontrol eylemlerinin klasik kontrolcü (MPC) sınırları/kısıtları içinde kalmasının güvenliği garanti ettiğini belirtir</span></span><span data-path-to-node="7,2,1,0,1,1"><span class="citation-136 citation-end-136"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="11"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="11"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="11"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="11"></sup></span></span><span data-path-to-node="7,2,1,0,1,2">. Siz de Hibrit PID+RL yapınızda, RL''in üreteceği katkıyı (<span class="math-inline" data-math="Eylem_{RL}"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8889em; vertical-align: -0.1944em;"></span><span style="margin-right: 0.0576em;" class="mord mathnormal">E</span><span style="margin-right: 0.0359em;" class="mord mathnormal">y</span><span style="margin-right: 0.0197em;" class="mord mathnormal">l</span><span class="mord mathnormal">e</span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3283em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0077em;" class="mord mathnormal mtight">R</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) belirli sınırlar içinde tutarak (clipping) benzer bir "güvenlik garantisi" argümanı geliştirebilirsiniz.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><span data-path-to-node="7,2,1,1,1,0"><b><span class="citation-135">- n-Adım Öngörü (n-step return):</span></b><span class="citation-135"> Makale, RL ajanının öğrenmesini hızlandırmak için modelin n-adım sonrasını tahmin etme gücünden yararlanmıştır</span></span><span data-path-to-node="7,2,1,1,1,1"><span class="citation-135 citation-end-135"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="12"></sup></span></span><span data-path-to-node="7,2,1,1,1,2">. Sizin projenizde "Fizik Tabanlı Ödül" fonksiyonunda, sadece anlık durum değil, CSTR denklemlerinden türetilen kısa vadeli bir <i>termal kaçak eğilimi</i> (türevsel bir terim) ödüle eklenebilir.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><span data-path-to-node="7,2,1,2,1,0"><b><span class="citation-134">- Simülasyon Araçları:</span></b><span class="citation-134"> Makalede kullanılan OMLT ve Pyomo araçları</span></span><span data-path-to-node="7,2,1,2,1,1"><span class="citation-134 citation-end-134"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="13"></sup></span></span><span data-path-to-node="7,2,1,2,1,2">, Python tabanlı simülasyon ortamınızda optimizasyon tabanlı kıyaslamalar yapmak isterseniz (örneğin ideal NMPC performansı nedir?) referans olabilir.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div></div></li><li><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Kontrolcü Farkı:</b> Makale MPC kullanırken siz PID kullanıyorsunuz. MPC, geleceği öngören bir model kullandığı için projenizdeki PID''den daha gelişmiştir. Ancak makale, modelin hatalı olduğu durumlarda (mismatch) RL''in MPC''yi düzelttiğini gösteriyor. Sizin projenizde ise RL, PID''nin <i>doğrusal olmayan</i> durumlardaki yetersizliğini düzeltecek. Bu analoji literatür taraması (Literature Review) kısmında kurulmalıdır.</p></li><li><p data-path-to-node="7,3,1,1,0"><span class="citation-133"></span></p><p data-path-to-node="7,3,1,1,1"><span data-path-to-node="7,3,1,1,1,0"><b><span class="citation-133">- Uygulama:</span></b><span class="citation-133"> Makale SCR ünitesindeki </span><span class="math-inline" data-math="NO_x"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span style="margin-right: 0.109em;" class="mord mathnormal"><span class="citation-133">N</span></span><span class="mord"><span style="margin-right: 0.0278em;" class="mord mathnormal"><span class="citation-133">O</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.0278em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight"><span class="citation-133">x</span></span></span></span></span><span class="vlist-s"><span class="citation-133">​</span></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span><span class="citation-133"> emisyonuna odaklanırken</span></span><span data-path-to-node="7,3,1,1,1,1"><span class="citation-133 citation-end-133"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="14"></sup></span></span><span data-path-to-node="7,3,1,1,1,2">, siz CSTR''deki sıcaklık kontrolüne odaklanıyorsunuz.</span></p></li></ul></div></div></li></ul></div>', '<span data-path-to-node="4,0,1,0"><b><span class="citation-146 interactive-span-hovered">Amaç:</span></b><span class="citation-146 interactive-span-hovered">
 Makale, Model Öngörülü Kontrol (MPC) ile Derin Pekiştirmeli Öğrenmeyi 
(RL) birleştirerek, MPC''nin objektif fonksiyonunu (value function) RL 
ile dinamik olarak öğrenmeyi ve güncellemeyi hedeflemektedir</span></span><span data-path-to-node="4,0,1,1"><span class="citation-146 citation-end-146 interactive-span-hovered"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="4,0,1,2">. </span><span data-path-to-node="4,0,1,3"><span class="citation-145"></span></span><span data-path-to-node="4,0,1,4"><span class="citation-145">Temel
 amaç, süreç dinamikleri değiştiğinde (örneğin tesis-model uyuşmazlığı) 
MPC''nin performansını manuel güncelleme gerektirmeden koruyabilmektir</span></span><span data-path-to-node="4,0,1,5"><span class="citation-145 citation-end-145"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="4,0,1,6">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><span class="citation-144"></span></p><p data-path-to-node="4,1,1,0,1"><span data-path-to-node="4,1,1,0,1,0"><b><span class="citation-144">- Sistem:</span></b><span class="citation-144"> İki vaka çalışması kullanılmıştır: 1) Çift entegratör (Double Integrator) </span></span><span data-path-to-node="4,1,1,0,1,1"><span class="citation-144 citation-end-144"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="3"></sup></span></span><span data-path-to-node="4,1,1,0,1,2"><span class="citation-143"></span></span><span data-path-to-node="4,1,1,0,1,3"><span class="citation-143">ve 2) </span><b><span class="citation-143">Seçici Katalitik İndirgeme (SCR) Ünitesi</span></b><span class="citation-143"> (Endüstriyel, çok değişkenli, doğrusal olmayan bir sistem)</span></span><span data-path-to-node="4,1,1,0,1,4"><span class="citation-143 citation-end-143"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="4"></sup></span></span><span data-path-to-node="4,1,1,0,1,5">.</span></p></li></ul><span data-path-to-node="4,1,1,1,0,0"><b>- Algoritma:</b> Yazarlar, <b>VFMPC</b> (Value Function MPC) adını verdikleri bir yapı önermektedir. </span><span data-path-to-node="4,1,1,1,0,1"><span class="citation-142"></span></span><span data-path-to-node="4,1,1,1,0,2"><span class="citation-142">Bu
 yapıda MPC politikasının (trajectory optimization) ürettiği sonuçlar, 
RL ajanı (Semi-Gradient SARSA benzeri bir yapı) tarafından değer 
fonksiyonunu güncellemek için kullanılır</span></span><span data-path-to-node="4,1,1,1,0,3"><span class="citation-142 citation-end-142"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="5"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="5"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="5"></sup></span></span><span data-path-to-node="4,1,1,1,0,4">. </span><span data-path-to-node="4,1,1,1,0,5"><span class="citation-141"></span></span><span data-path-to-node="4,1,1,1,0,6"><span class="citation-141">Ayrıca
 süreç dinamiklerini öğrenmek için Yapay Sinir Ağları (ANN) ve OMLT 
(Optimization &amp; Machine Learning Toolkit) entegrasyonu 
kullanılmıştır</span></span><span data-path-to-node="4,1,1,1,0,7"><span class="citation-141 citation-end-141"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="6"></sup></span></span><span data-path-to-node="4,1,1,1,0,8">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted">-&nbsp;<span data-path-to-node="4,1,1,2,1,0"><b><span class="citation-140">Yaklaşım:</span></b><span class="citation-140">
 "High-level RL" olarak tanımladıkları, RL''in doğrudan kontrol sinyali 
üretmek yerine, MPC''nin maliyet fonksiyonunu optimize ettiği bir yapı 
benimsenmiştir</span></span><span data-path-to-node="4,1,1,2,1,1"><span class="citation-140 citation-end-140"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="7"></sup></span></span><span data-path-to-node="4,1,1,2,1,2">.</span><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div></div><br><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0"><span data-path-to-node="4,2,1,0,0,0"><span class="citation-139"></span></span><span data-path-to-node="4,2,1,0,0,1"><span class="citation-139">-
 VFMPC(n) (n-adım öngörülü algoritma), statik parametreli geleneksel 
MPC''ye kıyasla, özellikle model uyuşmazlığı (katalizör bozunması gibi) 
durumlarında çok daha hızlı adapte olmuş ve daha düşük hata oranları 
(ödül kaybı) sergilemiştir</span></span><span data-path-to-node="4,2,1,0,0,2"><span class="citation-139 citation-end-139"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="8"></sup></span></span><span data-path-to-node="4,2,1,0,0,3">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"></div><p><span data-path-to-node="4,2,1,1,0,1"><span class="citation-138">-
 Yapay sinir ağı tabanlı değer fonksiyonu kullanımı, doğrusal olmayan 
bozunma senaryolarında (catalyst decay) LMPC (Lineer MPC) performansını 
aşarak NMPC (Nonlinear MPC) performansına yaklaşmıştır</span></span><span data-path-to-node="4,2,1,1,0,2"><span class="citation-138 citation-end-138"><sup _ngcontent-ng-c571306383="" class="superscript" data-turn-source-index="9"></sup></span></span><span data-path-to-node="4,2,1,1,0,3">.</span></p><div _ngcontent-ng-c341599530="" class="source-inline-chip-container ng-star-inserted"><br></div><p>s<br><br></p></li></ul></div>', 7, 'papers/2/493/Continuous_learning_of_the_value_function_utilizing_deep_reinforcement_learning_to_be_used_as_the_objective_in_model_predictive_control.pdf', 3573736, NULL, '2025-11-22T22:10:31.512Z', '2026-02-05T17:17:25.509Z', 'client_1764520808415_rtrnhcg8a37', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (494, 2, 'Digital twins for accurate prediction beyond routine operation', '["Bryan Li","Isaac Severinsen","Wei Yu","Timothy Walmsley","Brent Young"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109211', NULL, NULL, '["Metodolojik İyileştirme","Alternatif Eğitim Stratejisi","Meta-learning","PINN (Physics-Informed Neural Networks)","Extrapolation Capability","Dynamic Weighting","Digital Twin","Physics-Informed Machine Learning","Process Modeling","Mass & Energy Balance"]', 'To Read', '[489]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b> <b>Güçlü Şekilde Destekleyici</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Hipotez Doğrulaması:</b> Projenizdeki "Sadece veriye dayalı (pure data-driven) yöntemler, CSTR''in tehlikeli (runaway) bölgelerinde yetersiz kalır" tezini bilimsel olarak kanıtlıyor. Makale, verinin olmadığı yerlerde (extrapolation) fizik kurallarının (kütle/enerji denkliği) rehberliğine muhtaç olduğumuzu gösteriyor.</p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Basitleştirme:</b> Makale, çok karmaşık diferansiyel denklemler yerine, sadece temel korunum yasalarının (mass &amp; energy balance) bile model başarısını radikal şekilde artırdığını göstererek, sizin CSTR modelinizin geçerliliğini destekliyor.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>- Dinamik Ödül Ağırlıklandırma (Meta-learning):</b> Bu, projeniz için <b>"Game Changer"</b> olabilir. Referans projenizde ödül fonksiyonu şu şekildeydi: <span class="math-inline" data-math="R_t = w_{verim}R_{verim} - w_{guvenlik}P_{guvenlik}"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span class="" style="top: -2.55em; margin-left: -0.0077em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3117em;"><span class="" style="top: -2.55em; margin-left: -0.0269em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">v</span><span style="margin-right: 0.0278em;" class="mord mathnormal mtight">er</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3117em;"><span class="" style="top: -2.55em; margin-left: -0.0077em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">v</span><span style="margin-right: 0.0278em;" class="mord mathnormal mtight">er</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: -0.0269em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">guv</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span style="margin-right: 0.0197em;" class="mord mathnormal mtight">l</span><span style="margin-right: 0.0315em;" class="mord mathnormal mtight">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span><span class="mord"><span style="margin-right: 0.1389em;" class="mord mathnormal">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">guv</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span style="margin-right: 0.0197em;" class="mord mathnormal mtight">l</span><span style="margin-right: 0.0315em;" class="mord mathnormal mtight">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span></span></span></span></span>. Genelde bu <span class="math-inline" data-math="w"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.4306em;"></span><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span></span></span></span></span> değerleri elle sabitlenir. Bu makale diyor ki: <i>"Eğitimin başında fiziğe çok güven, öğrenme ilerledikçe veriye/deneyime güven."</i></p><ul data-path-to-node="7,2,1,0,1"><li><p data-path-to-node="7,2,1,0,1,0,0"><b>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Öneri:</b> RL ajanınızı eğitirken, güvenlik cezasının ağırlığını (<span class="math-inline" data-math="w_{guvenlik}"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7167em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: -0.0269em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">guv</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span style="margin-right: 0.0197em;" class="mord mathnormal mtight">l</span><span style="margin-right: 0.0315em;" class="mord mathnormal mtight">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) eğitimin başlarında çok yüksek tutup, ajan öğrendikçe dinamik olarak optimize etmeyi düşünebilirsiniz (Curriculum Learning benzeri bir yapı).</p></li></ul></li><li><p data-path-to-node="7,2,1,1,0"><b>- Eğitim Süresi Uyarısı:</b> Makale, Meta-learning PINN''in eğitim süresinin saf veri modeline göre <b>30 kat</b> daha uzun olduğunu belirtiyor. Proje planınızdaki GPU bütçesi ve zaman planlamasında (İP3) bu ekstra maliyeti göz önünde bulundurmalısınız.</p></li><li><p data-path-to-node="7,2,1,2,0"><b>- Validasyon Yöntemi:</b> Makale, modelleri test ederken veriyi "Rutin" ve "Rutin Dışı" (Test 1 vs Test 2) olarak ayırmış. Siz de CSTR kontrolcüsünü test ederken sadece set-point değişimi (rutin) değil, <b>sınırları zorlayan bozulmalar (rutin dışı)</b> ile test etmelisiniz.</p></li><li><p data-path-to-node="7,2,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Uygulama Alanı:</b> Onlar Isı Değiştirici kullanıyor, siz CSTR. CSTR''in dinamiği (üstelik reaksiyon var) ısı değiştiriciden daha kaotiktir (runaway riski daha ani ve şiddetlidir). Bu durum, fizik tabanlı yaklaşımınızı daha da zorunlu kılar.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Kimyasal süreçlerde "rutin
 dışı" (non-routine) veya beklenmedik operasyonel koşullarda (arıza, ani
 yük değişimi vb.) sistem davranışını doğru tahmin edebilen, yüksek 
sadakatli bir Dijital İkiz geliştirmek.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Sistem:</b> Endüstriyel bir <b>Jeotermal Isı Değiştirici (Heat Exchanger)</b>.</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Algoritma:</b> Saf veri odaklı modeller (LSTM, rMLP) ile <b>Fiziksel Bilgilendirilmiş Sinir Ağları (PINN)</b> karşılaştırılmış.</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Yenilik:</b>
 PINN yapısında, fiziksel kısıtların (denklemlerin) kayıp 
fonksiyonundaki ağırlığını eğitim sırasında dinamik olarak optimize eden
 <b>Meta-learning</b> stratejisi kullanılmış.</p></li><li><p data-path-to-node="4,1,1,3,0"><b>- Fiziksel Temel:</b> Karmaşık ısı transfer katsayıları yerine sadece temel <b>Kütle ve Enerji Denkliği</b> denklemleri kısıt olarak eklenmiş.</p></li><li><p data-path-to-node="4,1,1,3,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Saf veri odaklı model (rMLP), eğitim verisinde olmayan rutin dışı durumlarda çuvallamış (<span class="math-inline" data-math="R^2"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8141em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height: 0.8141em;"><span class="" style="top: -3.063em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></span> değeri 0.65''ten 0.48''e düşmüş).</p></li><li><p data-path-to-node="4,2,1,1,0">- Meta-learning destekli PINN (MLPI-rMLP), bu zorlu senaryolarda <b><span class="math-inline" data-math="R^2 = 0.97"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8141em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height: 0.8141em;"><span class="" style="top: -3.063em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0.97</span></span></span></span></span></b> gibi çok yüksek bir başarı yakalamış.</p></li><li><p data-path-to-node="4,2,1,2,0">- Dinamik ağırlıklandırma, sabit ağırlıklı PINN''in yaşadığı sistematik sapma (bias) sorununu çözmüş.</p></li></ul></li>', 8, 'papers/2/494/Digital_twins_for_accurate_prediction_beyond_routine_operation.pdf', 5321223, NULL, '2025-11-22T22:10:32.168Z', '2026-02-05T17:17:25.202Z', 'client_1764520808415_rtrnhcg8a37', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (495, 2, 'Economic nonlinear model predictive control and scheduling of multiple fed-batch fermenters in a lignocellulosic biorefinery', '[]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109223', NULL, NULL, '["Rakip Yöntem","Benchmark Çalışması","ENMPC","Economic Optimization","Integrated Scheduling and Control","Constraint Handling","Process Control","Model Predictive Control (MPC)","Biorefinery","Fed-Batch Fermentation"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b> <b>Alternatif/Rakip Yöntem (Benchmark)s</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Rakip Yaklaşım:</b> Bu makale, senin projenin savunduğu "Yapay Zeka (RL)" yaklaşımının karşısındaki en güçlü klasik/modern rakip olan "Model Tabanlı Kontrol (MPC)" yaklaşımını temsil eder. Senin projenin literatür kısmında, <i>"MPC gibi yöntemler model doğruluğuna çok hassasken ve hesaplama yükü (optimization solving time) yüksekken, önerdiğimiz RL ajanı eğitildikten sonra milisaniyeler içinde aksiyon alabilir"</i> argümanını kurmak için bu makaleyi kullanmalısın.</p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Destekleyici Yön:</b> Makale, "sabit PID/sabit akış" mantığının yetersiz olduğunu ve sürecin dinaiğine göre değişen (non-linear) kontrol sinyallerinin verimliliği artırdığını kanıtlıyor. Bu, senin "RL, PID''den iyidir" hipotezini dolaylı olarak destekler (çünkü ikisi de PID''den üstün olan ileri kontrol yöntemleridir).</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>- Kısıt Yönetimi (Constraint Handling):</b> Makalede, maya hücrelerinin ozmotik şoka girmemesi için besleme hızındaki değişim oranına (rate-of-change) kısıt konulmuş (<span class="math-inline" data-math="\Delta u"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">u</span></span></span></span></span> constraints). Sen de RL ajanını eğitirken, aksiyon uzayına veya ödül fonksiyonuna benzer bir "yumuşak değişim" (smoothness) cezası ekleyebilirsin. Bu, CSTR''in vanalarının çok hızlı açılıp kapanmasını önleyerek aktüatör ömrünü uzatır ve süreci kararlı tutar.</p></li><li><p data-path-to-node="7,2,1,1,0"><b>- Ekonomik Ödül Fonksiyonu:</b> Makale, doğrudan karı maksimize eden bir objektif fonksiyon kullanmış (<span class="math-inline" data-math="Revenue - Cost"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7667em; vertical-align: -0.0833em;"></span><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="mord mathnormal">e</span><span style="margin-right: 0.0359em;" class="mord mathnormal">v</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mord mathnormal">u</span><span class="mord mathnormal">e</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.6833em;"></span><span style="margin-right: 0.0715em;" class="mord mathnormal">C</span><span class="mord mathnormal">os</span><span class="mord mathnormal">t</span></span></span></span></span>). Senin "Fizik Tabanlı Ödül" fonksiyonuna, güvenlik terimlerinin yanına bir de "enerji maliyeti" veya "hammadde israfı" terimi ekleyerek <b>Ekonomik RL</b> (Economic RL) boyutunu katabilirsin.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Çizelgeleme (Scheduling):</b> Bu makale birden fazla reaktörün zamanlamasına odaklanırken, senin projen tek bir CSTR''in anlık kontrolüne odaklanıyor.</p></li><li><p data-path-to-node="7,3,1,1,0"><b>- Hesaplama Yükü:</b> ENMPC her adımda bir optimizasyon problemi çözer (Online optimization). Senin RL ajanının (eğitildikten sonra) böyle bir yükü yoktur.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Biyoetanol üreten bir biyorafineride, paralel çalışan çoklu yarı-kesikli (fed-batch) fermentörlerin hem <b>çizelgeleme (scheduling)</b> hem de <b>kontrol (control)</b> kararlarını entegre bir şekilde optimize etmek. Geleneksel sabit besleme stratejileri yerine, ekonomik karı maksimize eden dinamik besleme politikaları geliştirmek.s</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Sistem:</b> Lignoselülozik biyokütleden etanol üreten, paralel bağlanmış Yarı-Kesikli (Fed-Batch) Fermentörler.</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Algoritma:</b> Ekonomik Doğrusal Olmayan Model Öngörülü Kontrol (<b>ENMPC</b> - Economic Nonlinear Model Predictive Control).</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Yöntem:</b> Süreç dinamiklerini (kütle, enerji, kinetik) içeren birinci prensip (first-principles) modeller kullanılarak, bir optimizasyon problemi (NLP) çözülmektedir. Kontrolcü, hem hammadde besleme hızlarını (kontrol değişkeni) hem de işlem sürelerini/başlangıçlarını (çizelgeleme değişkeni) aynı anda optimize eder.</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Geleneksel sabit debili besleme yöntemlerine kıyasla, ENMPC ile elde edilen değişken besleme profilleri (variable feeding rates) <b>%13 oranında daha yüksek kar</b> sağlamıştır.</p></li><li><p data-path-to-node="4,2,1,1,0">- Girdi bileşimindeki bozulmalara (disturbances) karşı sistemin dirençli olduğu ve operasyonel kısıtları (örn: besleme hızındaki ani değişimlerin sınırlandırılması) başarıyla yönettiği gösterilmiştir.</p></li></ul></li>', 6, NULL, NULL, NULL, '2025-11-22T22:10:32.824Z', '2025-11-30T15:53:16.720Z', 'client_1763443786605_6w2tm45ddct', 7, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (496, 2, 'Integrating coding platforms with process simulators for custom applications', '["Kumar","Anikesh","Vo","Chi Hung","Shahabuddin","M","Garud","Sushant S","Karimi","Iftekhar A"]', 2025, 'Computers & Chemical Engineering', '10.1016/j.compchemeng.2025.109247', NULL, NULL, '["Gelecek Çalışmalar","Endüstriyel Entegrasyon Vizyonu","Aspen HYSYS API","ActiveX/COM","Co-simulation Architectures","Process Simulation","Python Integration","Automation","Digital Twin"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b>Destekleyici/Karşıt Nitelik:</b> <b>Metodolojik Genişleme (Methodological Expansion)</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b>- Gelecek Vizyonu:</b> Bu makale, projenizin "Gelecek Çalışmalar" veya "Endüstriyel Uygulanabilirlik" kısmı için altın değerindedir. Jüriye şunu diyebilirsiniz: <i>"Şu an CSTR modelini Python''da matematiksel olarak modelliyoruz, ancak geliştirdiğimiz RL ajanı bu makaledeki yöntemler kullanılarak doğrudan bir fabrikanın Aspen HYSYS modeline de bağlanabilir."</i></p></li><li><p data-path-to-node="7,1,1,1,0"><b>- Eksiklik Giderici:</b> Python tabanlı matematiksel modeller (ODE çözücüler), termodinamik özellikleri (yoğunluk, viskozite, ısı kapasitesi değişimi) genellikle sabit varsayar. HYSYS entegrasyonu ise bu özellikleri gerçekçi bir şekilde hesaplar.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b>-&nbsp; Eş-Simülasyon (Co-Simulation) Kavramı:</b> Makaledeki "Fig. 5: Simulation-based optimization architecture", sizin projenizdeki RL döngüsüne çok benzer. Oradaki "Optimizer" kutusu yerine sizin "RL Agent"ınız, "HYSYS" yerine sizin "Python Environment"ınız var. Bu mimari şemasını kendi raporunuzda uyarlayarak kullanabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><b>- Otomasyon Mantığı:</b> Makale, bir sürecin dışarıdan (Python''dan) adım adım nasıl işletileceğini (set point değiştir -&gt; simüle et -&gt; sonucu oku) anlatıyor. Bu döngü, sizin RL eğitim döngünüzün (Action -&gt; Step -&gt; Reward) teknik karşılığıdır.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b>- Uygulama:</b> Makale CSTR kontrolüne değil, genel entegrasyona odaklanıyor.</p></li><li><p data-path-to-node="7,3,1,1,0"><b>- Yöntem:</b> Makalede RL (Yapay Zeka) yok, klasik optimizasyon (Solver) var.</p></li><li><p data-path-to-node="7,3,1,1,0"><br></p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b>Amaç:</b> Araştırmacıların ve mühendislerin, ticari süreç simülatörlerini (özellikle Aspen HYSYS) harici kodlama platformlarıyla (Python, MATLAB) entegre ederek, standart yazılımların yapamadığı özel analizleri, optimizasyonları ve otomasyonları gerçekleştirmelerini sağlayan kapsamlı bir rehber sunmak.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b>- Entegrasyon Teknolojisi:</b> Windows <b>ActiveX (COM)</b> teknolojisi kullanılarak Python ile HYSYS arasında köprü kurulması.</p></li><li><p data-path-to-node="4,1,1,1,0"><b>- Nesne Yönelimli Yaklaşım:</b> HYSYS''in nesne hiyerarşisinin (SimulationCases -&gt; Flowsheet -&gt; Operations -&gt; Streams) Python tarafından nasıl manipüle edileceği detaylandırılmış.</p></li><li><p data-path-to-node="4,1,1,2,0"><b>- Uygulama Alanları:</b> Tekno-ekonomik analiz (TEA) ve Simülasyon tabanlı optimizasyon (Simulation-based optimization) için "Wrapper" (sarmalayıcı) kod yapıları gösterilmiş.</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Simülatörlerin "Backdoor" (arka kapı) değişkenlerine erişim yöntemleri ile normalde arayüzden ulaşılamayan verilere nasıl ulaşılacağı gösterilmiş.</p></li><li><p data-path-to-node="4,2,1,1,0">- Python''un güçlü kütüphaneleri (SciPy, Pandas) ile HYSYS''in termodinamik motorunun nasıl birleştirilebileceği kanıtlanmış.</p></li></ul></li>', 5, 'papers/2/496/Integrating_coding_platforms_with_process_simulators_for_custom_applications.pdf', 3710641, NULL, '2025-11-22T22:10:33.483Z', '2026-02-05T17:17:24.592Z', 'client_1764520808415_rtrnhcg8a37', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (497, 2, 'Leveraging machine learning algorithms to predict life cycle inventory assessments (LCIA) to facilitate sustainable process design', '["Aboagye","Emmanuel","Longo","Jared","Conway","Matt","Pazik","John","Barkow","Milo","McMahon","Marcella","Weil","Brendan","Appiah","Harriet Dufie","Hesketh","Robert","Yenkie","Kirti M."]', 2025, 'Computers & Chemical Engineering', '10.1016/j.compchemeng.2025.109217', NULL, NULL, '["İlham Verici","Geniş Bağlam","ANN","XGBoost","Molecular Descriptors","Environmental Impact Prediction","Life Cycle Assessment (LCA)","Machine Learning in Chemical Engineering","Sustainability"]', 'To Read', '[]', '<li><p data-path-to-node="6,1,0"><b>Destekleyici/Karşıt Nitelik:</b> <b>Tamamlayıcı (Farklı Bir Katman)</b></p><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0"><b>Geniş Perspektif:</b> Projeniz "Dijital Dönüşüm" başlığı altındadır. Bu makale, dijital dönüşümün <i>kontrol</i> değil, <i>sürdürülebilir tasarım</i> ayağını temsil eder. Projenizin "Güvenlik" (Safety) odağına, bu makale "Çevre" (Environment) odağıyla eşlik edebilir ancak metodolojik olarak (RL vs Supervised Learning) farklıdırlar.</p></li><li><p data-path-to-node="6,1,1,0,0"><br></p></li></ul></li><li><p data-path-to-node="6,2,0"><b>Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0"><b>Fiziksel Özelliklerin Girdi Olarak Kullanımı:</b> Makale, ML modellerine sadece ham veriyi değil, <i>termodinamik özellikleri</i> (ısı kapasitesi, kritik sıcaklık vb.) girdi olarak vermenin model başarısını artırdığını kanıtlıyor. Bu, sizin projenizdeki "Physics-Informed" yaklaşımı (fiziksel yasaların ajana öğretilmesi veya girdi olarak verilmesi) destekleyen bir argümandır.</p></li><li><p data-path-to-node="6,2,1,1,0"><b>Özellik Seçimi (Feature Selection):</b> Makalede kullanılan SHAP analizi ve özellik eleme yöntemleri, RL ajanınızın durum uzayını (state space) belirlerken hangi sensör verilerinin (sıcaklık, basınç, soğutma suyu debisi vb.) daha kritik olduğunu belirlemek için kullanılabilir bir tekniktir.</p></li><li><p data-path-to-node="6,2,1,2,0"><b>Gelecek Vizyonu:</b> Projenizin ilerleyen aşamalarında RL ajanının ödül fonksiyonuna sadece "Güvenlik" ve "Verim" değil, bu makaledeki gibi "Çevresel Etki / Karbon Ayak İzi" parametreleri de eklenebilir. (Örn: Soğutma suyunun aşırı kullanımı çevresel bir maliyettir).</p></li><li><p data-path-to-node="6,2,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="6,3,0"><b>Eksik/Farklı Yönler:</b></p><ul data-path-to-node="6,3,1"><li><p data-path-to-node="6,3,1,0,0"><b>Yöntem:</b> Makale Denetimli Öğrenme (Supervised Learning - Regresyon) kullanırken, siz Pekiştirmeli Öğrenme (Reinforcement Learning) kullanıyorsunuz.</p></li><li><p data-path-to-node="6,3,1,1,0"><b>Zaman Boyutu:</b> Makale statik bir analiz (LCA) yaparken, sizin projeniz dinamik zaman serileri ve anlık tepkiler üzerine kurulu.</p></li></ul></li>', '<li><p data-path-to-node="3,0,0"><b>Amaç:</b> Yeni kimyasallar ve proses teknolojileri için Yaşam Döngüsü Envanteri (LCI) verilerinin erken tasarım aşamalarında bulunmaması sorununu çözmek. Makine öğrenmesi (ML) algoritmalarını kullanarak, kimyasalların fizikokimyasal ve moleküler özelliklerinden çevresel etkilerini (insan sağlığı, ekosistem kalitesi vb.) tahmin etmek ve böylece sürdürülebilir proses tasarımını kolaylaştırmak.</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b>Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b>Sistem:</b> Genel kimyasal proses tasarımı (Vaka çalışması olarak NMP solvent geri kazanım ünitesi kullanılmış).</p></li><li><p data-path-to-node="3,1,1,1,0"><b>Algoritma:</b> Yapay Sinir Ağları (ANN) ve Extreme Gradient Boosting (XGBoost).</p></li><li><p data-path-to-node="3,1,1,2,0"><b>Girdi/Çıktı:</b> Girdi olarak termodinamik özellikler (kaynama noktası, ısı kapasitesi vb.) ve moleküler tanımlayıcılar kullanılmış; çıktı olarak 4 ana etki kategorisi (İnsan Sağlığı, Ekosistem Kalitesi, Küresel Isınma, Kaynak Kullanımı) tahmin edilmiştir.</p></li><li><p data-path-to-node="3,1,1,3,0"><b>Yaklaşım:</b> "Sıralı Geriye Doğru Özellik Seçimi" (Sequential Backward Feature Selection) kullanılarak en etkili 10 özellik (5 termodinamik + 5 moleküler) belirlenmiştir.</p></li><li><p data-path-to-node="3,1,1,3,0"><br></p></li></ul></li><li><p data-path-to-node="3,2,0"><b>Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">Geliştirilen ANN ve XGBoost modelleri, özellikle İnsan Sağlığı (<span class="math-inline" data-math="R^2=0.957"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8141em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height: 0.8141em;"><span class="" style="top: -3.063em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0.957</span></span></span></span></span>) ve Kaynak Kullanımı gibi kategorilerde yüksek doğrulukla tahmin yapabilmiştir.</p></li><li><p data-path-to-node="3,2,1,1,0">Dinamik bir ağırlıklandırma (Meta-learning benzeri) yerine, özelliklerin fiziksel anlamlılığına (SHAP değerleri ile) odaklanılmıştır.</p></li><li><p data-path-to-node="3,2,1,2,0">Makine öğrenmesi destekli LCA''nın, tam ölçekli veriler olmadan da erken aşamada çevresel etki analizi yapılmasına olanak tanıdığı gösterilmiştir.</p></li></ul></li>', 3, 'papers/2/497/Leveraging_machine_learning_algorithms_to_predict_life_cycle_inventory_assessments__LCIA__to_facilitate_sustainable_process_design.pdf', 5747790, NULL, '2025-11-22T22:10:34.144Z', '2025-11-30T15:57:11.681Z', 'client_1763443786605_6w2tm45ddct', 7, NULL);
