INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (551, 2, 'ML@ChemE: Past, Present, and Future of Machine Learning in Chemical Engineering', '["Pınar Özdemir","Ramazan Yıldırım"]', 2025, 'ChemBioEng Reviews', '10.1002/cben.70012', NULL, NULL, '["Review","Machine Learning","Chemical Engineering","Process Control","Physics-Informed ML","Hybrid ML","Reinforcement Learning (RL) in Control","Future Trends","Temel Teori","Doğrudan Alıntılanmalı"]', 'To Read', '[]', '<li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="5,1,0" data-index-in-node="29">Güçlü Destekleyici</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0" id="p-rc_cb24d96f0c1f666e-109"><span data-path-to-node="5,1,1,0,0,0"><span class="citation-258"></span></span><span data-path-to-node="5,1,1,0,0,1"><span class="citation-258">Makale, bizim projenin en büyük özgünlük iddiası olan "geleneksel yapay zeka sadece veriye bakar ve güvensizdir, bu yüzden fizik tabanlı (physics-informed) ödül fonksiyonları kullanılmalıdır" tezini birebir desteklemektedir</span></span><span data-path-to-node="5,1,1,0,0,2"><span class="citation-258 citation-end-258"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup></span></span><span data-path-to-node="5,1,1,0,0,3">. Literatürün de bu yöne kaydığını göstererek projemizin ne kadar güncel ve doğru bir noktaya temas ettiğini kanıtlamaktadır.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div><p></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b data-path-to-node="5,2,1,0,0" data-index-in-node="0">- Proje Gerekçelendirmesi (Giriş/Motivasyon):</b> Bu makale, araştırma önerinizin veya nihai raporunuzun giriş bölümünde kesinlikle kullanılmalıdır. <i data-path-to-node="5,2,1,0,0" data-index-in-node="143">"Saf veriye dayalı ML modellerinin kimyasal reaksiyonların termodinamik sınırlarını öngörememe riski bulunduğu için [Özdemir ve Yıldırım, 2025], bu projede fizik-tabanlı bir yaklaşım benimsenmiştir"</i> şeklinde bir atıf, projenin kalitesini artıracaktır.</p></li><li><p data-path-to-node="5,2,1,0,0"><br></p></li><li><p data-path-to-node="5,2,1,1,0"><span class="citation-257"></span></p><p data-path-to-node="5,2,1,1,1" id="p-rc_cb24d96f0c1f666e-110"><span data-path-to-node="5,2,1,1,1,0"><b data-path-to-node="5,2,1,1,1,0" data-index-in-node="0"><span class="citation-257">- Hibrit Model Argümanı:</span></b><span class="citation-257"> Makalede, RL''nin "model öngörülü kontrolcülerle (MPC) veya mevcut kontrol sistemleriyle entegre edilmesi" stratejisinden bahsedilmektedir</span></span><span data-path-to-node="5,2,1,1,1,1"><span class="citation-257 citation-end-257"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="9"></sup></span></span><span data-path-to-node="5,2,1,1,1,2">. Bu durum, bizim projemizdeki <b data-path-to-node="5,2,1,1,1,2" data-index-in-node="31">PID + RL (Hibrit/Artık RL)</b> mimarisinin endüstriyel uygulanabilirlik açısından ne kadar mantıklı bir yaklaşım olduğunu akademik olarak destekler.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c864260379="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahgKEwi_3dm1pseTAxUAAAAAHQAAAAAQxAI"></button></div><p></p></li></ul></li><li><p data-path-to-node="5,3,0"><b data-path-to-node="5,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0">- Bu bir derleme makalesi olduğu için, Referans Proje''de ihtiyaç duyduğumuz CSTR simülasyon parametreleri, diferansiyel denklemler veya hiperparametre ayarları (learning rate, discount factor vb.) gibi teknik ve sayısal detayları içermez.</p></li></ul></li>', '<li><p data-path-to-node="3,0,1" id="p-rc_cb24d96f0c1f666e-106"><span data-path-to-node="3,0,1,0"><b data-path-to-node="3,0,1,0" data-index-in-node="0"><span class="citation-265">Amaç:</span></b><span class="citation-265"> Makale, makine öğrenmesinin (ML) kimya mühendisliği (ChemE) alanındaki geçmişini, güncel uygulamalarını ve gelecekteki yönelimlerini incelemeyi amaçlamaktadır</span></span><span data-path-to-node="3,0,1,1"><span class="citation-265 citation-end-265"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="3,0,1,2">. </span><span data-path-to-node="3,0,1,3"><span class="citation-264"></span></span><span data-path-to-node="3,0,1,4"><span class="citation-264">Özellikle büyük veri, makine öğrenmesi ve yeni nesil üretken yapay zeka (Generative AI/LLM) araçlarının kimya mühendisliğine entegrasyonu sırasındaki fırsatlar ve zorluklar tartışılmaktadır</span></span><span data-path-to-node="3,0,1,5"><span class="citation-264 citation-end-264"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="3,0,1,6">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div><p></p></li><li><p data-path-to-node="3,1,0" id="p-rc_cb24d96f0c1f666e-107"><span data-path-to-node="3,1,0,0"><b data-path-to-node="3,1,0,0" data-index-in-node="0">Metodoloji:</b> Bu çalışma bir literatür derlemesi (review) olduğu için spesifik bir reaktör (örn. CSTR) veya tek bir algoritma üzerinde sayısal bir deney yapılmamıştır. </span><span data-path-to-node="3,1,0,1"><span class="citation-263"></span></span><span data-path-to-node="3,1,0,2"><span class="citation-263">Ancak, literatürdeki proses kontrolü, malzeme keşfi, özellik tahmini ve optimizasyon gibi alanlardaki ML uygulamaları incelenmiştir</span></span><span data-path-to-node="3,1,0,3"><span class="citation-263 citation-end-263"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="3"></sup></span></span><span data-path-to-node="3,1,0,4">. </span><span data-path-to-node="3,1,0,5"><span class="citation-262"></span></span><span data-path-to-node="3,1,0,6"><span class="citation-262">Süreç izleme ve kontrol problemlerinde Pekiştirmeli Öğrenme (RL) ve Derin Öğrenme gibi yaklaşımların kullanımı analiz edilmiştir</span></span><span data-path-to-node="3,1,0,7"><span class="citation-262 citation-end-262"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="4"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="4"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="4"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="4"></sup></span></span><span data-path-to-node="3,1,0,8">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div><p></p></li><li><p data-path-to-node="3,2,0" id="p-rc_cb24d96f0c1f666e-108"><span data-path-to-node="3,2,0,0"><b data-path-to-node="3,2,0,0" data-index-in-node="0">Temel Bulgular:</b> Makale, sayısal bir deney sonucu yerine literatür trendlerini ortaya koymaktadır. </span><span data-path-to-node="3,2,0,1"><span class="citation-261"></span></span><span data-path-to-node="3,2,0,2"><span class="citation-261">En önemli bulgulardan biri, kimya mühendisliği problemlerinde yalnızca veriye dayalı (purely data-driven) ML modellerinin termodinamik ve fiziksel kuralları (kütle ve enerji korunumu gibi) ihlal edebileceği riskidir</span></span><span data-path-to-node="3,2,0,3"><span class="citation-261 citation-end-261"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="5"></sup></span></span><span data-path-to-node="3,2,0,4">. </span><span data-path-to-node="3,2,0,5"><span class="citation-260"></span></span><span data-path-to-node="3,2,0,6"><span class="citation-260">Bu zayıflığı gidermek için fizik kurallarını ve denklemleri modelin içine entegre eden </span><b data-path-to-node="3,2,0,6" data-index-in-node="87"><span class="citation-260">Fizik Tabanlı ML (Physics-Informed ML)</span></b><span class="citation-260"> ve </span><b data-path-to-node="3,2,0,6" data-index-in-node="129"><span class="citation-260">Hibrit ML</span></b><span class="citation-260"> yaklaşımlarının gelecekteki en kritik gelişim alanları olduğu saptanmıştır</span></span><span data-path-to-node="3,2,0,7"><span class="citation-260 citation-end-260"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="6"></sup></span></span><span data-path-to-node="3,2,0,8">. </span><span data-path-to-node="3,2,0,9"><span class="citation-259"></span></span><span data-path-to-node="3,2,0,10"><span class="citation-259">Ayrıca, süreç kontrolünde RL''nin geleneksel kontrolcülerin yerine veya onlarla entegre bir şekilde kullanılmasının giderek yaygınlaştığı belirtilmiştir</span></span><span data-path-to-node="3,2,0,11"><span class="citation-259 citation-end-259"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup></span></span><span data-path-to-node="3,2,0,12">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div><p></p></li>', 6, 'papers/2/551/ChemBioEng_Reviews_-_2025_-___zdemir_-_ML_ChemE_Past_Present_and_Future_of_Machine_Learning_in_Chemical_Engineering.pdf', 5809258, NULL, '2025-11-29T10:53:41.781Z', '2026-03-30T06:49:08.337Z', 'client_1763443786605_6w2tm45ddct', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (552, 2, 'Control invariant set enhanced safe reinforcement learning: Improved sampling efficiency, guaranteed stability and robustness', '["Song Bo","Bernard T. Agyeman","Xunyuan Yin","Jinfeng Liu"]', 2023, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2023.108413', NULL, NULL, '["Process Control","Reinforcement Learning","Safe RL","Safety-Critical Systems","CSTR","Control Invariant Sets (CIS)","Safety Supervisor","Mixed Integer Linear Programming (MILP)","State Reset Technique","Robust CIS (RCIS)","Rakip Yaklaşım"]', 'To Read', '[]', '<ul><li><b data-path-to-node="6,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik: Rakip/Alternatif Yaklaşım (Güçlü Destekleyici)</b></li></ul><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0" id="p-rc_4415728edf41941b-87"><span data-path-to-node="6,1,1,0,0,0"><span class="citation-191"></span></span><span data-path-to-node="6,1,1,0,0,1"><span class="citation-191">&nbsp;- Bu makale, projenizin temel argümanı olan "geleneksel RL''nin proses güvenliği için yetersiz olduğu ve kısıtların sisteme doğrudan öğretilmesi gerektiği" fikrini güçlü bir şekilde desteklemektedir</span></span><span data-path-to-node="6,1,1,0,0,2"><span class="citation-191 citation-end-191"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="15"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="15"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="15"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="15"></sup></span></span><span data-path-to-node="6,1,1,0,0,3">. </span><span data-path-to-node="6,1,1,0,0,4"><span class="citation-190"></span></span><span data-path-to-node="6,1,1,0,0,5"><span class="citation-190">Ancak güvenliği sağlamak için </span><i data-path-to-node="6,1,1,0,0,5" data-index-in-node="30"><span class="citation-190">ödül fonksiyonunu termodinamik denklemlerle (fizik tabanlı)</span></i><span class="citation-190"> zenginleştirmek yerine, eylemleri bir MILP çözücüsü ile filtreleyerek </span><i data-path-to-node="6,1,1,0,0,5" data-index-in-node="160"><span class="citation-190">katı matematiksel denetim</span></i><span class="citation-190"> yapmayı seçmişlerdir</span></span></p></li></ul><div><br></div><div><br></div><li><p data-path-to-node="6,2,0"><b data-path-to-node="6,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar:</b></p><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0"><span class="citation-189"></span></p><p data-path-to-node="6,2,1,0,1" id="p-rc_4415728edf41941b-88"><span data-path-to-node="6,2,1,0,1,0"><b data-path-to-node="6,2,1,0,1,0" data-index-in-node="0"><span class="citation-189">- Eğitimi Hızlandırma Stratejisi (State Reset):</span></b><span class="citation-189"> Makalede ajan CIS dışına çıktığında "Durum Sıfırlama (State Reset)" yapılarak önceki güvenli ana geri döndürülmüştür</span></span><span data-path-to-node="6,2,1,0,1,1"><span class="citation-189 citation-end-189"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="17"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="17"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="17"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="17"></sup></span></span><span data-path-to-node="6,2,1,0,1,2">. Referans projenizin İP3 (Yapay Zeka Ajanlarının Eğitimi) aşamasında hesaplama maliyetlerini (GPU sürelerini) azaltmak ve verimi artırmak için bu tekniği doğrudan kodunuza entegre edebilirsiniz.</span></p></li></ul><div><br></div><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,1,0"><span class="citation-188"></span></p><p data-path-to-node="6,2,1,1,1" id="p-rc_4415728edf41941b-89"><span data-path-to-node="6,2,1,1,1,0"><b data-path-to-node="6,2,1,1,1,0" data-index-in-node="0"><span class="citation-188">- Ceza Fonksiyonu Mimarisi:</span></b><span class="citation-188"> Makale, güvenli bölge dışına çıkıldığında </span><span class="math-inline" data-math="-1000" data-index-in-node="68"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord"><span class="citation-188">−</span></span><span class="mord"><span class="citation-188">1000</span></span></span></span></span></span><span class="citation-188">, içeride kalındığında </span><span class="math-inline" data-math="+10000" data-index-in-node="96"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord"><span class="citation-188">+</span></span><span class="mord"><span class="citation-188">10000</span></span></span></span></span></span><span class="citation-188"> gibi katı ayrık (discrete) ödüller kullanmıştır</span></span><span data-path-to-node="6,2,1,1,1,1"><span class="citation-188 citation-end-188"></span></span><span data-path-to-node="6,2,1,1,1,2">. </span><span data-path-to-node="6,2,1,1,1,3"><span class="citation-187"></span></span><span data-path-to-node="6,2,1,1,1,4"><span class="citation-187">Sizin projenizde üstel (exponential) bir ceza planlanıyor</span></span><span data-path-to-node="6,2,1,1,1,5"><span class="citation-187 citation-end-187"></span></span><span data-path-to-node="6,2,1,1,1,6">. Literatür tartışmanızda, katı bariyerler yerine üstel fonksiyonların ajana nasıl daha pürüzsüz bir gradyan sunabileceğini tartışarak kendi yönteminizi ön plana çıkarabilirsiniz.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li><li><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li><li><p data-path-to-node="6,2,1,2,0"><span class="citation-186"></span></p><p data-path-to-node="6,2,1,2,1" id="p-rc_4415728edf41941b-90"><span data-path-to-node="6,2,1,2,1,0"><b data-path-to-node="6,2,1,2,1,0" data-index-in-node="0"><span class="citation-186">- Hibrit PID Argümanını Güçlendirme:</span></b><span class="citation-186"> Bu makaledeki "Güvenlik Denetleyicisi" her adımda bir optimizasyon (MILP) çözmek zorundadır, bu da 0.20 ila 2.0 saniye sürebilen bir işlem yükü yaratır</span></span><span data-path-to-node="6,2,1,2,1,1"><span class="citation-186 citation-end-186"></span></span><span data-path-to-node="6,2,1,2,1,2">. </span><span data-path-to-node="6,2,1,2,1,3"><span class="citation-185"></span></span><span data-path-to-node="6,2,1,2,1,4"><span class="citation-185">Projenizin raporunda, "Hibrit (Artık) RL" stratejinizin (PID + RL)</span></span><span data-path-to-node="6,2,1,2,1,5"><span class="citation-185 citation-end-185"></span></span><span data-path-to-node="6,2,1,2,1,6">, ekstra bir çevrimiçi optimizasyon çözücüsüne ihtiyaç duymadan PID''nin temel kararlılığını kullanarak <b data-path-to-node="6,2,1,2,1,6" data-index-in-node="103">işlemsel olarak (computationally) çok daha hafif ve endüstri için daha pratik</b> bir alternatif sunduğunu vurgulayabilirsiniz.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li><li><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li></ul></li><li><p data-path-to-node="6,3,0"><b data-path-to-node="6,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="6,3,1"><li><p data-path-to-node="6,3,1,0,0" id="p-rc_4415728edf41941b-91"><span data-path-to-node="6,3,1,0,0,0"><span class="citation-184"></span></span><span data-path-to-node="6,3,1,0,0,1"><span class="citation-184">- Bu makale çevrimdışı RL için Soft Actor-Critic (SAC) değil, </span><b data-path-to-node="6,3,1,0,0,1" data-index-in-node="60"><span class="citation-184">PPO</span></b><span class="citation-184"> kullanmıştır</span></span><span data-path-to-node="6,3,1,0,0,2"><span class="citation-184 citation-end-184"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="22"></sup></span></span><span data-path-to-node="6,3,1,0,0,3">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c864260379="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahgKEwi_3dm1pseTAxUAAAAAHQAAAAAQvAE"></button></div><p></p></li><li><p data-path-to-node="6,3,1,1,0" id="p-rc_4415728edf41941b-92"><span data-path-to-node="6,3,1,1,0,0"><span class="citation-183"></span></span><span data-path-to-node="6,3,1,1,0,1"><span class="citation-183">- Bu çalışmada endüstriyel standardı temsil eden bir </span><b data-path-to-node="6,3,1,1,0,1" data-index-in-node="51"><span class="citation-183">PID kontrolcü veya hibritleştirme yoktur</span></b></span><span data-path-to-node="6,3,1,1,0,2"><span class="citation-183 citation-end-183"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="23"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="23"></sup></span></span><span data-path-to-node="6,3,1,1,0,3">. </span><span data-path-to-node="6,3,1,1,0,4"><span class="citation-182"></span></span><span data-path-to-node="6,3,1,1,0,5"><span class="citation-182">Acil durumlarda ajanı PID''ye devretmek yerine, çevrimiçi yeniden eğitme veya önceden hesaplanmış rastgele bir yedek tablo (backup table) kullanmaktadırlar</span></span><span data-path-to-node="6,3,1,1,0,6"><span class="citation-182 citation-end-182"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="24"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="24"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="24"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="24"></sup></span></span><span data-path-to-node="6,3,1,1,0,7">.</span></p></li></ul></li>', '<li><p data-path-to-node="3,0,1" id="p-rc_4415728edf41941b-80"><span data-path-to-node="3,0,1,0"><b data-path-to-node="3,0,1,0" data-index-in-node="0"><span class="citation-205">Amaç:</span></b><span class="citation-205"> Standart Pekiştirmeli Öğrenme (RL) algoritmaları, gerçek dünya uygulamaları için hayati önem taşıyan güvenlik kısıtlarını (safety constraints) ve kapalı çevrim kararlılık (closed-loop stability) garantilerini sağlayamaz</span></span><span data-path-to-node="3,0,1,1"><span class="citation-205 citation-end-205"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="3,0,1,2">. </span><span data-path-to-node="3,0,1,3"><span class="citation-204"></span></span><span data-path-to-node="3,0,1,4"><span class="citation-204">Ayrıca standart RL algoritmalarının örneklem verimliliği (sampling efficiency) düşüktür</span></span><span data-path-to-node="3,0,1,5"><span class="citation-204 citation-end-204"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="3,0,1,6">. </span><span data-path-to-node="3,0,1,7"><span class="citation-203"></span></span><span data-path-to-node="3,0,1,8"><span class="citation-203">Makale, "Kontrol Değişmez Kümeleri (CIS)" kavramını RL''ye entegre ederek hem kararlılığı garanti altına almayı hem de eğitim verimliliğini artırmayı amaçlamaktadır</span></span><span data-path-to-node="3,0,1,9"><span class="citation-203 citation-end-203"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="3"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="3"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="3"></sup></span></span><span data-path-to-node="3,0,1,10">.</span></p></li><div><br></div><div><br></div><li><p data-path-to-node="3,1,0"><span class="citation-202"></span></p><p data-path-to-node="3,1,1" id="p-rc_4415728edf41941b-81"><span data-path-to-node="3,1,1,0"><b data-path-to-node="3,1,1,0" data-index-in-node="0"><span class="citation-202">Metodoloji:</span></b><span class="citation-202"> * </span><b data-path-to-node="3,1,1,0" data-index-in-node="14"><span class="citation-202">Sistem:</span></b><span class="citation-202"> Birinci dereceden egzotermik ve geri dönüşümsüz reaksiyonun gerçekleştiği, ceketli bir Sürekli Karıştırmalı Tank Reaktör (CSTR) kullanılmıştır</span></span><span data-path-to-node="3,1,1,1"><span class="citation-202 citation-end-202"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="4"></sup></span></span><span data-path-to-node="3,1,1,2">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c864260379="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahgKEwi_3dm1pseTAxUAAAAAHQAAAAAQsgE"></button></div><p></p><ul data-path-to-node="3,1,2"><li><p data-path-to-node="3,1,2,0,0"><span class="citation-201"></span></p><p data-path-to-node="3,1,2,0,1" id="p-rc_4415728edf41941b-82"><span data-path-to-node="3,1,2,0,1,0"><b data-path-to-node="3,1,2,0,1,0" data-index-in-node="0"><span class="citation-201">Algoritma:</span></b><span class="citation-201"> Çevrimdışı eğitimde Proximal Policy Optimization (PPO) algoritması kullanılmıştır</span></span><span data-path-to-node="3,1,2,0,1,1"><span class="citation-201 citation-end-201"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="5"></sup></span></span><span data-path-to-node="3,1,2,0,1,2">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c864260379="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahgKEwi_3dm1pseTAxUAAAAAHQAAAAAQswE"></button></div><p></p></li><li><p data-path-to-node="3,1,2,1,0"><span class="citation-200"></span></p><p data-path-to-node="3,1,2,1,1" id="p-rc_4415728edf41941b-83"><span data-path-to-node="3,1,2,1,1,0"><b data-path-to-node="3,1,2,1,1,0" data-index-in-node="0"><span class="citation-200">Kontrol Yapısı:</span></b><span class="citation-200"> Süreç, çevrimdışı (offline) ve çevrimiçi (online) olmak üzere iki aşamada tasarlanmıştır</span></span><span data-path-to-node="3,1,2,1,1,1"><span class="citation-200 citation-end-200"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="6"></sup></span></span><span data-path-to-node="3,1,2,1,1,2">. </span><span data-path-to-node="3,1,2,1,1,3"><span class="citation-199"></span></span><span data-path-to-node="3,1,2,1,1,4"><span class="citation-199">Çevrimdışı eğitimde, CIS kullanılarak ajan sadece güvenli başlangıç durumlarında başlatılmış ve sistem güvenli bölgeden çıkarsa ajan cezalandırılarak durumu sıfırlanmıştır (state reset)</span></span><span data-path-to-node="3,1,2,1,1,5"><span class="citation-199 citation-end-199"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="7"></sup></span></span><span data-path-to-node="3,1,2,1,1,6">. </span><span data-path-to-node="3,1,2,1,1,7"><span class="citation-198"></span></span><span data-path-to-node="3,1,2,1,1,8"><span class="citation-198">Çevrimiçi uygulamada ise bir "Güvenlik Denetleyicisi (Safety Supervisor)", RL ajanının ürettiği aksiyonun güvenli olup olmadığını Karışık Tamsayılı Doğrusal Programlama (MILP) çözerek denetler</span></span><span data-path-to-node="3,1,2,1,1,9"><span class="citation-198 citation-end-198"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="8"></sup></span></span><span data-path-to-node="3,1,2,1,1,10">. </span><span data-path-to-node="3,1,2,1,1,11"><span class="citation-197"></span></span><span data-path-to-node="3,1,2,1,1,12"><span class="citation-197">Eğer öngörülen durum güvenli (RCIS) değilse, ajan o noktada çevrimiçi olarak yeniden eğitilir</span></span><span data-path-to-node="3,1,2,1,1,13"><span class="citation-197 citation-end-197"><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="9"></sup><sup _ngcontent-ng-c2361586534="" class="superscript" data-turn-source-index="9"></sup></span></span><span data-path-to-node="3,1,2,1,1,14">.</span></p><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li><li><div _ngcontent-ng-c864260379="" class="source-inline-chip-container ng-star-inserted"><br></div></li></ul></li><li><p data-path-to-node="3,2,0"><span class="citation-196"></span></p><p data-path-to-node="3,2,1" id="p-rc_4415728edf41941b-84"><span data-path-to-node="3,2,1,0"><b data-path-to-node="3,2,1,0" data-index-in-node="0"><span class="citation-196">Temel Bulgular:</span></b></span>-<span data-path-to-node="3,2,1,0"><span class="citation-196">&nbsp;CIS entegrasyonu, aynı miktarda veriyle çevrimdışı eğitilen standart RL''ye kıyasla hata oranını (failure rate) %34.30''dan %8.42''ye düşürerek örneklem verimliliğini ciddi şekilde artırmıştır</span></span><span data-path-to-node="3,2,1,1"><span class="citation-196 citation-end-196"></span></span><span data-path-to-node="3,2,1,2">.</span></p></li><br><div><span data-path-to-node="3,2,2,0,0,1"><span class="citation-195">- Geliştirilen Güvenlik Denetleyicisi sayesinde, hem deterministik hem de belirsizlik içeren (stokastik) senaryolarda kapalı çevrim sistemin daima güvenli bölgede (CIS ve RCIS) kalması garanti altına alınmış ve testlerde %0.02''ye kadar inen mükemmel güvenlik oranları elde edilmiştir</span></span><span data-path-to-node="3,2,2,0,0,2"><span class="citation-195 citation-end-195"></span></span><span data-path-to-node="3,2,2,0,0,3">.</span></div>', 8, 'papers/2/552/Control_invariant_set_enhanced_safe_reinforcement_learning_Improved_sampling_efficiency__guaranteed_stability_and_robustness.pdf', 1791543, NULL, '2025-12-02T07:07:12.259Z', '2026-03-30T06:44:18.537Z', 'client_1763443786605_6w2tm45ddct', 12, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (553, 2, 'Safe Reinforcement Learning with Lyapunov-Based Constraints for Control of an Unstable Reactor', '["Jos� R. Torraca Neto","Bruno D. O. Capron","Argimiro R. Secchi","Antonio d.R. Chanona"]', 2025, 'Systems and Control Transactions', '10.69997/sct.137298', NULL, NULL, '["Process Control","Reinforcement Learning","Safety-Critical Systems","Chemical Reaction Engineering","CSTR","Lyapunov Stability","SAC (Soft Actor-Critic)","Constrained RL","PC-Gym","Doğrudan Alıntılanmalı"]', 'To Read', '[]', '<li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="5,1,0" data-index-in-node="29">Güçlü Destekleyici</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0">Bu çalışma, <b data-path-to-node="5,1,1,0,0" data-index-in-node="12">Referans Proje</b>''nizin temel hipotezi olan "RL algoritmalarının CSTR gibi güvenlik açısından kritik sistemlerde kullanılabileceği" savını doğrulamaktadır.</p></li><li><p data-path-to-node="5,1,1,1,0"><span data-path-to-node="5,1,1,1,0,0"><span class="citation-20"></span></span><span data-path-to-node="5,1,1,1,0,1"><span class="citation-20">Özellikle </span><b data-path-to-node="5,1,1,1,0,1" data-index-in-node="10"><span class="citation-20">SAC (Soft Actor-Critic)</span></b><span class="citation-20"> algoritmasının CSTR kontrolünde başarılı olduğunun gösterilmesi</span></span><span data-path-to-node="5,1,1,1,0,2"><span class="citation-20 citation-end-20"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="10"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="10"></sup></span></span><span data-path-to-node="5,1,1,1,0,3">, projenizdeki algoritma seçimini (İP2.3) akademik olarak temellendirmektedir.</span></p><br></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b data-path-to-node="5,2,1,0,0" data-index-in-node="0">Alternatif Güvenlik Mekanizması:</b> Referans projeniz "Fizik Tabanlı Ödül (Semenov Sayısı)" kullanırken, bu makale "Lyapunov Kısıtlı Kayıp Fonksiyonu" kullanmaktadır. Projenizin tartışma bölümünde, kendi yönteminizin bu makaledeki yöntemden farkını (ödül şekillendirme vs. gradient kısıtlama) vurgulayabilirsiniz.</p></li><li><p data-path-to-node="5,2,1,1,0"><span class="citation-19"></span></p><p data-path-to-node="5,2,1,1,1"><span data-path-to-node="5,2,1,1,1,0"><b data-path-to-node="5,2,1,1,1,0" data-index-in-node="0"><span class="citation-19">Benzerlik Kurulacak Kütüphane (PC-Gym):</span></b><span class="citation-19"> Makale, kimyasal süreçler için geliştirilmiş </span><b data-path-to-node="5,2,1,1,1,0" data-index-in-node="85"><span class="citation-19">PC-Gym</span></b><span class="citation-19"> </span></span><span data-path-to-node="5,2,1,1,1,1"><span class="citation-19 citation-end-19"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="11"></sup></span></span><span data-path-to-node="5,2,1,1,1,2"> ortamını kullanmaktadır. Sizin geliştireceğiniz Python simülasyon ortamının (İP1) validasyonu veya özelliklerinin karşılaştırılması için bu kütüphane incelenebilir.</span></p><p></p></li><li><p data-path-to-node="5,2,1,2,0"><span class="citation-18"></span></p><p data-path-to-node="5,2,1,2,1"><span data-path-to-node="5,2,1,2,1,0"><b data-path-to-node="5,2,1,2,1,0" data-index-in-node="0"><span class="citation-18">NMPC Kıyaslaması:</span></b><span class="citation-18"> Makale, RL''in başarısını ölçmek için PID yerine NMPC (Model Predictive Control) kullanmıştır</span></span><span data-path-to-node="5,2,1,2,1,1"><span class="citation-18 citation-end-18"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="12"></sup></span></span><span data-path-to-node="5,2,1,2,1,2">. Eğer projenizde zaman kalırsa, PID''ye ek olarak NMPC ile kıyaslama yapmak projenizin kalitesini "lisans projesi" seviyesinden "yüksek lisans tezi" seviyesine taşıyabilir.</span></p><p></p></li><li><p data-path-to-node="5,2,1,3,0"><span class="citation-17"></span></p><p data-path-to-node="5,2,1,3,1"><span data-path-to-node="5,2,1,3,1,0"><b data-path-to-node="5,2,1,3,1,0" data-index-in-node="0"><span class="citation-17">Gürültü ve Bozulma Testleri:</span></b><span class="citation-17"> Makalede ölçüm gürültüsü %0.1 ile %0.5 arasında değiştirilerek testler yapılmıştır</span></span><span data-path-to-node="5,2,1,3,1,1"><span class="citation-17 citation-end-17"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="13"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="13"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="13"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="13"></sup></span></span><span data-path-to-node="5,2,1,3,1,2">. Sizin projenizdeki "bozulma senaryoları" (İP4.1) için bu oranlar referans alınabilir.</span></p><br></li></ul></li><li><p data-path-to-node="5,3,0"><b data-path-to-node="5,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0"><b data-path-to-node="5,3,1,0,0" data-index-in-node="0">Hibrit Yapı:</b> Bu makale saf RL kullanırken, sizin projeniz <b data-path-to-node="5,3,1,0,0" data-index-in-node="58">Hibrit (Artık/Residual) RL</b> önermektedir. Bu, sizin projenizin "Endüstriyel Uygulanabilirlik" iddiasını güçlendiren özgün bir farktır. Makalede PID ile hibrit bir yapı denenmemiştir.</p></li><li><p data-path-to-node="5,3,1,1,0"><span class="citation-16"></span></p><p data-path-to-node="5,3,1,1,1"><span data-path-to-node="5,3,1,1,1,0"><b data-path-to-node="5,3,1,1,1,0" data-index-in-node="0"><span class="citation-16">Ödül Fonksiyonu:</span></b><span class="citation-16"> Makale basit bir "Negatif Karesel Hata" ödülü kullanıp güvenliği kayıp fonksiyonuna (loss function) gömmüştür</span></span><span data-path-to-node="5,3,1,1,1,1"><span class="citation-16 citation-end-16"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="14"></sup></span></span><span data-path-to-node="5,3,1,1,1,2">. Sizin projeniz ise güvenliği doğrudan ödüle (reward) gömmektedir. Bu metodolojik fark, literatür tartışması için mükemmel bir noktadır.</span></p><div _ngcontent-ng-c2671931107="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c2671931107="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahcKEwievcu5mMOSAxUAAAAAHQAAAAAQNw"></button></div><p></p></li></ul></li><br>', '<li><p data-path-to-node="3,0,1"><span data-path-to-node="3,0,1,0"><b data-path-to-node="3,0,1,0" data-index-in-node="0"><span class="citation-29">Amaç:</span></b><span class="citation-29"> Makale, kararsız (unstable) reaktörlerin kontrolünde, standart Pekiştirmeli Öğrenme (RL) algoritmalarının kapalı çevrim kararlılık garantisi sunmamasını ele almaktadır</span></span><span data-path-to-node="3,0,1,1"><span class="citation-29 citation-end-29"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="1"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="1"></sup></span></span><span data-path-to-node="3,0,1,2">. </span><span data-path-to-node="3,0,1,3"><span class="citation-28"></span></span><span data-path-to-node="3,0,1,4"><span class="citation-28">Çalışma, modelden bağımsız (model-free) bir yaklaşımla, Value ve Q fonksiyonlarına doğrudan kısıtlamalar getirerek Lyapunov tabanlı bir kararlılık çerçevesi sunmayı amaçlamaktadır</span></span><span data-path-to-node="3,0,1,5"><span class="citation-28 citation-end-28"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="2"></sup></span></span><span data-path-to-node="3,0,1,6">.</span></p><div _ngcontent-ng-c2671931107="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c2671931107="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahcKEwievcu5mMOSAxUAAAAAHQAAAAAQJQ"></button></div><p></p></li><li><p data-path-to-node="3,1,0"><b data-path-to-node="3,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><span class="citation-27"></span></p><p data-path-to-node="3,1,1,0,1"><span data-path-to-node="3,1,1,0,1,0"><b data-path-to-node="3,1,1,0,1,0" data-index-in-node="0"><span class="citation-27">Sistem:</span></b><span class="citation-27"> Egzotermik, geri dönüşümsüz (A </span><span class="math-inline" data-math="\rightarrow" data-index-in-node="39"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.3669em;"></span><span class="mrel"><span class="citation-27">→</span></span></span></span></span></span><span class="citation-27"> B) reaksiyonlu, ceketli Sürekli Karıştırmalı Tank Reaktör (CSTR)</span></span><span data-path-to-node="3,1,1,0,1,1"><span class="citation-27 citation-end-27"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="3"></sup></span></span><span data-path-to-node="3,1,1,0,1,2">.</span></p><p></p></li><li><p data-path-to-node="3,1,1,1,0"><span class="citation-26"></span></p><p data-path-to-node="3,1,1,1,1"><span data-path-to-node="3,1,1,1,1,0"><b data-path-to-node="3,1,1,1,1,0" data-index-in-node="0"><span class="citation-26">Algoritmalar:</span></b><span class="citation-26"> Hem on-policy (PPO) hem de off-policy (SAC, TD3, DDPG) algoritmaları "Güvenli (Safe)" versiyonlarıyla test edilmiştir</span></span><span data-path-to-node="3,1,1,1,1,1"><span class="citation-26 citation-end-26"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="4"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="4"></sup></span></span><span data-path-to-node="3,1,1,1,1,2">.</span></p><p></p></li><li><p data-path-to-node="3,1,1,2,0"><span class="citation-25"></span></p><p data-path-to-node="3,1,1,2,1"><span data-path-to-node="3,1,1,2,1,0"><b data-path-to-node="3,1,1,2,1,0" data-index-in-node="0"><span class="citation-25">Kontrol Yapısı:</span></b><span class="citation-25"> Standart ödül maksimizasyonuna ek olarak, kayıp (loss) fonksiyonuna iki terim eklenmiştir: 1) Lyapunov adayı olan </span><span class="math-inline" data-math="-V(s)" data-index-in-node="130"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord"><span class="citation-25">−</span></span><span style="margin-right: 0.2222em;" class="mord mathnormal"><span class="citation-25">V</span></span><span class="mopen"><span class="citation-25">(</span></span><span class="mord mathnormal"><span class="citation-25">s</span></span><span class="mclose"><span class="citation-25">)</span></span></span></span></span></span><span class="citation-25"> ve </span><span class="math-inline" data-math="-Q(s,a)" data-index-in-node="139"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord"><span class="citation-25">−</span></span><span class="mord mathnormal"><span class="citation-25">Q</span></span><span class="mopen"><span class="citation-25">(</span></span><span class="mord mathnormal"><span class="citation-25">s</span></span><span class="mpunct"><span class="citation-25">,</span></span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord mathnormal"><span class="citation-25">a</span></span><span class="mclose"><span class="citation-25">)</span></span></span></span></span></span><span class="citation-25"> fonksiyonlarının pozitif olmasını cezalandıran terim, 2) Bu fonksiyonların zaman türevinin pozitif olmasını (enerji artışını) cezalandıran terim</span></span><span data-path-to-node="3,1,1,2,1,1"><span class="citation-25 citation-end-25"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="5"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="5"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="5"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="5"></sup></span></span><span data-path-to-node="3,1,1,2,1,2">.</span></p><p></p></li><li><p data-path-to-node="3,1,1,3,0"><span class="citation-24"></span></p><p data-path-to-node="3,1,1,3,1"><span data-path-to-node="3,1,1,3,1,0"><b data-path-to-node="3,1,1,3,1,0" data-index-in-node="0"><span class="citation-24">Kıyaslama:</span></b><span class="citation-24"> Performans, kısıtlamasız (baseline) RL algoritmaları ve teorik en iyi performansı temsil eden Doğrusal Olmayan Model Öngörülü Kontrol (NMPC) "Oracle" ile karşılaştırılmıştır</span></span><span data-path-to-node="3,1,1,3,1,1"><span class="citation-24 citation-end-24"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="6"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="6"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="6"></sup></span></span><span data-path-to-node="3,1,1,3,1,2">.</span></p><div _ngcontent-ng-c2671931107="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c2671931107="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahcKEwievcu5mMOSAxUAAAAAHQAAAAAQKw"></button></div><div _ngcontent-ng-c2671931107="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c2671931107="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahcKEwievcu5mMOSAxUAAAAAHQAAAAAQLA"></button></div><p></p></li></ul></li><li><p data-path-to-node="3,2,0"><b data-path-to-node="3,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0"><span data-path-to-node="3,2,1,0,0,0"><span class="citation-23"></span></span><span data-path-to-node="3,2,1,0,0,1"><span class="citation-23">Kararlılık kısıtları, test edilen tüm algoritmalarda (özellikle SAC, PPO ve DDPG) aşımı (overshoot) ve değişkenliği (variability) önemli ölçüde azaltmıştır</span></span><span data-path-to-node="3,2,1,0,0,2"><span class="citation-23 citation-end-23"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="7"></sup><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="7"></sup></span></span><span data-path-to-node="3,2,1,0,0,3">.</span></p><p></p></li><li><p data-path-to-node="3,2,1,1,0"><span data-path-to-node="3,2,1,1,0,0"><span class="citation-22"></span></span><span data-path-to-node="3,2,1,1,0,1"><span class="citation-22">Türev tabanlı kısıtlamalar, özellikle PPO''da görülen osilasyonları (salınımları) bastırmada kritik rol oynamıştır</span></span><span data-path-to-node="3,2,1,1,0,2"><span class="citation-22 citation-end-22"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="8"></sup></span></span><span data-path-to-node="3,2,1,1,0,3">.</span></p><p></p></li><li><p data-path-to-node="3,2,1,2,0"><span data-path-to-node="3,2,1,2,0,0"><span class="citation-21"></span></span><span data-path-to-node="3,2,1,2,0,1"><span class="citation-21">Güvenli RL stratejileri, NMPC Oracle performansına yaklaşan yüksek kümülatif ödüller elde etmiştir</span></span><span data-path-to-node="3,2,1,2,0,2"><span class="citation-21 citation-end-21"><sup _ngcontent-ng-c1345682840="" class="superscript" data-turn-source-index="9"></sup></span></span><span data-path-to-node="3,2,1,2,0,3">.</span></p><div _ngcontent-ng-c2671931107="" class="source-inline-chip-container ng-star-inserted"><button _ngcontent-ng-c2671931107="" class="button ng-star-inserted" aria-label="Kaynak ayrıntılarını görüntüler. Yan paneli açar." data-hveid="0" data-ved="0CAAQvoAQahcKEwievcu5mMOSAxUAAAAAHQAAAAAQMA"></button></div><p></p></li></ul></li><br>', 9, 'papers/2/553/Safe_Reinforcement_Learning_with_Lyapunov-Based.pdf', 660555, NULL, '2025-12-02T09:01:15.597Z', '2026-02-05T17:31:31.584Z', 'client_1770322601560_v4bj2jg61va', 15, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (554, 2, 'CAMP: Counterexamples, Abstraction, MDPs, and Policy Refinement for Enhancing Safety, Stability, and Rewards in Reinforcement Learning', '["Ryeonggu Kwon","Gihwon Kwon"]', 2025, 'IEEE Access', '10.1109/access.2025.3556125', NULL, NULL, '["Formal Verification in RL","Safety-Critical AI","Abstraction Methods","CEGAR (Counterexample-Guided Abstraction Refinement)","Policy Stability","Failure State Avoidance","Abstract MDP","Teorik Alternatif","Metodolojik Kıyaslama"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Metodolojik Kontrast (Alternatif Yöntem)</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- Yöntem Farkı:</b> Sen güvenliği <b data-path-to-node="8,1,1,0,0" data-index-in-node="28">"Fiziksel Ceza"</b> (Reward Shaping) ile sağlıyorsun (Yumuşak Kısıt). Bu makale ise güvenliği <b data-path-to-node="8,1,1,0,0" data-index-in-node="118">"Durum Uzayı Soyutlaması"</b> (State Abstraction) ile sağlıyor (Sert/Yapısal Kısıt).</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Savunma Stratejisi:</b> Raporunda; <i data-path-to-node="8,1,1,1,0" data-index-in-node="31">"Kwon ve Kwon (2025), güvenliği sağlamak için durum uzayını soyutlayan karmaşık bir matematiksel yapı (CAMP) önermiştir. Ancak CSTR gibi yüksek boyutlu ve sürekli sistemlerde durum uzayını kümelemek (clustering) hesaplama açısından çok maliyetlidir. Bu nedenle projemizde, hesaplama yükü daha hafif olan ve doğrudan fiziksel değişkenlere odaklanan <b data-path-to-node="8,1,1,1,0" data-index-in-node="379">Fizik Tabanlı Ödül</b> mekanizması tercih edilmiştir."</i> diyebilirsin.</p></li><li><p data-path-to-node="8,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Stabilite Tanımı:</b> Makale, stabiliteyi (kararlılığı) "seçilen aksiyonların varyansının düşük olması" olarak tanımlıyor. Yani ajan bir adımda vanayı %10, diğer adımda %90 açmamalı. CSTR projenizde de "kontrolcü çıktısının pürüzsüzlüğü" (smoothness) için bu tanımı referans alabilir, ödül fonksiyonunuza aksiyon değişim cezası (<span class="math-inline" data-math="|u_t - u_{t-1}|" data-index-in-node="325"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2083em;"><span class=""></span></span></span></span></span></span><span class="mord">∣</span></span></span></span></span>) ekleyebilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Başarısızlık Tanımı (Failure State):</b> Makale "Failure State" kavramını çok net tanımlıyor. Siz de CSTR için <span class="math-inline" data-math="T &gt; 450 K" data-index-in-node="107"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7224em; vertical-align: -0.0391em;"></span><span style="margin-right: 0.1389em;" class="mord mathnormal">T</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord">450</span><span style="margin-right: 0.0715em;" class="mord mathnormal">K</span></span></span></span></span> durumunu bir "Failure State" olarak tanımlayıp, simülasyonu o anda durdurarak (early termination) ajana büyük bir ceza verebilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0"><b data-path-to-node="8,3,1,0,0" data-index-in-node="0">- Uygulama Alanı:</b> Makale basit oyun ortamlarında denenmiş, endüstriyel bir proseste (CSTR) denenmemiş. Bu, sizin projenizin "uygulama zorluğu" açısından bu makaleden daha ileride olduğunu gösterir.</p></li><li><p data-path-to-node="8,3,1,0,0"><br></p></li></ul></li>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Pekiştirmeli Öğrenme (RL) ajanlarının, ödül maksimizasyonu yaparken güvenlik ihlallerinden (failure states) kaçınmasını ve kararlı (stable) aksiyonlar üretmesini sağlamak. Mevcut yöntemlerin aksine, güvenliği şansa bırakmayıp <b data-path-to-node="5,0,0" data-index-in-node="232">Karşıt Örnekler (Counterexamples)</b> üzerinden matematiksel bir filtreleme mekanizması geliştirmek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Yöntem:</b> <b data-path-to-node="5,1,1,0,0" data-index-in-node="8">CAMP</b> adı verilen 4 aşamalı bir mimari:</p><ol start="1" data-path-to-node="5,1,1,0,1"><li><p data-path-to-node="5,1,1,0,1,0,0"><b data-path-to-node="5,1,1,0,1,0,0" data-index-in-node="0">&nbsp; &nbsp; 1. Counterexamples (Karşıt Örnekler):</b> Ajanın başarısız olduğu durumları tespit et.</p></li><li><p data-path-to-node="5,1,1,0,1,1,0"><b data-path-to-node="5,1,1,0,1,1,0" data-index-in-node="0">&nbsp; &nbsp; 2. Abstraction (Soyutlama):</b> Durum uzayını (State Space) kümelere (cluster) ayırarak basitleştirilmiş bir model (Abstract MDP) oluştur.</p></li><li><p data-path-to-node="5,1,1,0,1,2,0"><b data-path-to-node="5,1,1,0,1,2,0" data-index-in-node="0">&nbsp; &nbsp; 3. Refinement (İyileştirme):</b> Eğer bir küme "güvensiz" ise, onu bölerek (split) güvenli ve güvensiz bölgeleri netleştir. (CEGAR - Counterexample-Guided Abstraction Refinement mantığı).</p></li><li><p data-path-to-node="5,1,1,0,1,3,0"><b data-path-to-node="5,1,1,0,1,3,0" data-index-in-node="0">&nbsp; &nbsp; 4. Policy Optimization:</b> PPO algoritmasını bu güvenli soyut model üzerinde eğit.</p></li></ol></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Uygulama:</b> Grid World (basit labirent) ve CartPole (denge çubuğu) gibi klasik kontrol problemleri üzerinde test edilmiş.</p></li><li><p data-path-to-node="5,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- CAMP yöntemi, standart PPO ve diğer Safe RL yöntemlerine kıyasla <b data-path-to-node="5,2,1,0,0" data-index-in-node="65">%0 kaza oranı</b> (tam güvenlik) yakalamıştır.</p></li><li><p data-path-to-node="5,2,1,1,0">- Ödül performansından ödün vermeden, aksiyonlardaki varyansı (titreşimi) düşürerek <b data-path-to-node="5,2,1,1,0" data-index-in-node="82">kararlılığı (stability)</b> artırmıştır.</p></li></ul></li>', 6, 'papers/2/554/CAMP_Counterexamples_Abstraction_MDPs_and_Policy_Refinement_for_Enhancing_Safety_Stability_and_Rewards_in_Reinforcement_Learning.pdf', 4202009, NULL, '2025-12-02T09:03:12.987Z', '2026-01-22T18:46:13.495Z', 'client_1763443786605_6w2tm45ddct', 4, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (555, 2, 'Physics‐informed reinforcement learning for optimal control of nonlinear systems', '["Yujia Wang","Zhe Wu"]', 2024, 'AIChE Journal', '10.1002/aic.18542', NULL, NULL, '["Physics-Informed Machine Learning (PIML)","Physics-Informed Neural Networks (PINN)","Optimal Control","Lyapunov Stability","Input Constraints","Critic-Actor Structure","Loss Function Engineering","İsim Babası","Temel Teorik Referans"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Teorik Doğrulayıcı ve Yöntemsel Kıyaslama Noktası</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- "Fizik Tabanlı" Kavramının Derinliği:</b> Sen projende fiziği <b data-path-to-node="8,1,1,0,0" data-index-in-node="58">Ödül Fonksiyonu</b> (<span class="math-inline" data-math="R = R_{hedef} - Ceza_{fizik}" data-index-in-node="75"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: -0.0077em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">h</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span><span class="mord mathnormal mtight">e</span><span style="margin-right: 0.1076em;" class="mord mathnormal mtight">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span style="margin-right: 0.0715em;" class="mord mathnormal">C</span><span style="margin-right: 0.044em;" class="mord mathnormal">ez</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.1076em;" class="mord mathnormal mtight">f</span><span class="mord mathnormal mtight">i</span><span style="margin-right: 0.044em;" class="mord mathnormal mtight">z</span><span style="margin-right: 0.0315em;" class="mord mathnormal mtight">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) üzerinden sisteme dahil ediyorsun. Bu makale ise fiziği <b data-path-to-node="8,1,1,0,0" data-index-in-node="161">Sinir Ağı Kayıp Fonksiyonu</b> (<span class="math-inline" data-math="Loss = Error + \lambda \cdot Lyapunov" data-index-in-node="189"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">L</span><span class="mord mathnormal">oss</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.7667em; vertical-align: -0.0833em;"></span><span style="margin-right: 0.0576em;" class="mord mathnormal">E</span><span style="margin-right: 0.0278em;" class="mord mathnormal">rror</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.8778em; vertical-align: -0.1944em;"></span><span class="mord mathnormal">L</span><span style="margin-right: 0.0359em;" class="mord mathnormal">y</span><span class="mord mathnormal">a</span><span class="mord mathnormal">p</span><span class="mord mathnormal">u</span><span class="mord mathnormal">n</span><span class="mord mathnormal">o</span><span style="margin-right: 0.0359em;" class="mord mathnormal">v</span></span></span></span></span>) üzerinden dahil ediyor.</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Savunma Stratejisi:</b> Raporunda şunu demelisin: <i data-path-to-node="8,1,1,1,0" data-index-in-node="46">"Wang ve Wu (2024), fiziği sinir ağı yapısına gömen PINN mimarisini önermiştir. Ancak bu yöntem yüksek hesaplama yükü ve karmaşık türev işlemleri gerektirir. Bizim projemizde ise, endüstriyel uygulanabilirliği artırmak ve işlem yükünü azaltmak amacıyla, fizik kuralları ''Ödül Şekillendirme'' (Reward Shaping) mekanizmasıyla sisteme entegre edilmiştir. Bu, daha pratik bir ''Fizik Tabanlı'' yaklaşımdır."</i></p></li><li><p data-path-to-node="8,1,1,1,0"><i data-path-to-node="8,1,1,1,0" data-index-in-node="46"><br></i></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Girdi Kısıtları (Input Constraints):</b> Makale, vanaların fiziksel sınırlarını (saturation) kontrol algoritmasına nasıl yedirdiğini matematiksel olarak açıklıyor. CSTR simülasyonunda eylem uzayını (Action Space) belirlerken (örn: <span class="math-inline" data-math="[-1, 1]" data-index-in-node="227"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span></span> arası), bu makaledeki matematiksel tanımı referans gösterebilirsin.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Kararlılık (Stability):</b> Jüri sana "RL ajanının sistemi patlatmayacağını nasıl garanti edersin?" diye sorarsa; <i data-path-to-node="8,2,1,1,0" data-index-in-node="110">"Wang ve Wu (2024)''nun da gösterdiği gibi, fiziksel kısıtların (Lyapunov veya Enerji Korunumu) öğrenme sürecine dahil edilmesi kararlılığı matematiksel olarak artırır. Biz de bu prensibi ödül fonksiyonunda uyguluyoruz"</i> cevabını verebilirsin.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0">- Bu makale <b data-path-to-node="8,3,1,0,0" data-index-in-node="10">saf RL</b> kullanıyor, senin projen <b data-path-to-node="8,3,1,0,0" data-index-in-node="42">Hibrit (PID+RL)</b> kullanıyor. Hibrit yapının güvenlik açısından bir ekstra katman daha sağladığını belirterek kendi projenin özgün değerini vurgula.</p></li><li><p data-path-to-node="8,3,1,0,0"><br></p></li></ul></li><br>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Doğrusal olmayan ve girdi kısıtlamaları (vana açıklığı vb.) olan sistemler için, sistemin matematiksel modeline ihtiyaç duymayan (model-free) ancak fiziksel kararlılık kurallarına (Lyapunov) sıkı sıkıya bağlı kalan bir optimal kontrol stratejisi geliştirmek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Teknoloji:</b> <b data-path-to-node="5,1,1,0,0" data-index-in-node="11">PINN (Physics-Informed Neural Networks)</b>. Standart derin sinir ağları sadece veriyi ezberlerken, burada ağın kayıp fonksiyonuna (Loss Function) Lyapunov kararlılık denklemleri eklenmiştir.</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Algoritma:</b> İki ayrı sinir ağı kullanılmıştır:</p><ol start="1" data-path-to-node="5,1,1,1,1"><li><p data-path-to-node="5,1,1,1,1,0,0"><b data-path-to-node="5,1,1,1,1,0,0" data-index-in-node="0">&nbsp; &nbsp; 1. Değer Ağı (Critic):</b> Lyapunov fonksiyonunu (<span class="math-inline" data-math="V(x)" data-index-in-node="43"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span style="margin-right: 0.2222em;" class="mord mathnormal">V</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></span>) modeller. Fizik kuralı olarak <span class="math-inline" data-math="V(x) &gt; 0" data-index-in-node="79"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span style="margin-right: 0.2222em;" class="mord mathnormal">V</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0</span></span></span></span></span> ve <span class="math-inline" data-math="\dot{V}(x) &lt; 0" data-index-in-node="91"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1.1702em; vertical-align: -0.25em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height: 0.9202em;"><span class="" style="top: -3em;"><span class="pstrut" style="height: 3em;"></span><span style="margin-right: 0.2222em;" class="mord mathnormal">V</span></span><span class="" style="top: -3.2523em;"><span class="pstrut" style="height: 3em;"></span><span class="accent-body" style="left: -0.1389em;"><span class="mord">˙</span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.6444em;"></span><span class="mord">0</span></span></span></span></span> şartlarını sağlamaya zorlanır.</p></li><li><p data-path-to-node="5,1,1,1,1,1,0"><b data-path-to-node="5,1,1,1,1,1,0" data-index-in-node="0">&nbsp; &nbsp; 2. Politika Ağı (Actor):</b> Kontrol kuralını (<span class="math-inline" data-math="u(x)" data-index-in-node="40"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord mathnormal">u</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span></span>) modeller.</p></li></ol></li><li><p data-path-to-node="5,1,1,2,0"><b data-path-to-node="5,1,1,2,0" data-index-in-node="0">- Yenilik:</b> Model-Free bir yapı olmasına rağmen, Lyapunov teoremini eğitimin içine gömerek matematiksel olarak kararlı bir kapalı çevrim garanti eder.</p></li><li><p data-path-to-node="5,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- Geliştirilen yöntem, sistem modelini tam bilmese bile (model-free), Lyapunov kısıtları sayesinde sistemi her zaman kararlı bölgede tutmayı başarmıştır.</p></li><li><p data-path-to-node="5,2,1,1,0">- Geleneksel RL yöntemlerinin aksine, eğitim sırasında "fiziğe aykırı" (kararsız) davranışlar sergilemesi engellenmiştir.</p></li></ul></li><br>', 10, 'papers/2/555/AIChE_Journal_-_2024_-_Wang_-_Physics___informed_reinforcement_learning_for_optimal_control_of_nonlinear_systems.pdf', 2091627, NULL, '2025-12-02T09:04:36.250Z', '2026-01-22T18:45:11.805Z', 'client_1763443786605_6w2tm45ddct', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (556, 2, 'A tutorial review of machine learning-based model predictive control methods', '["Zhe Wu","Panagiotis D. Christofides","Wanlu Wu","Yujia Wang","Fahim Abdullah","Aisha Alnajdi","Yash Kadakia"]', 2024, 'Reviews in Chemical Engineering', '10.1515/revce-2024-0055', NULL, NULL, '["Model Predictive Control (MPC)","Machine Learning in Control","Stability Analysis","Lyapunov-based MPC","Generalization Error","Recurrent Neural Networks (RNN)","Benchmark CSTR","Rakip Yöntem","Kıyaslama","Kod Kaynağı"]', 'To Read', '[]', '<li><p data-path-to-node="9,1,0"><b data-path-to-node="9,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="9,1,0" data-index-in-node="29">Güçlü Rakip ve Benchmark Kaynağı</b></p><ul data-path-to-node="9,1,1"><li><p data-path-to-node="9,1,1,0,0"><b data-path-to-node="9,1,1,0,0" data-index-in-node="0">- Karşıt Argüman (MPC vs RL):</b> Makale, ML-MPC''nin ne kadar gelişmiş olduğunu gösteriyor. Ancak MPC''nin temel dezavantajı olan <b data-path-to-node="9,1,1,0,0" data-index-in-node="123">"Online Optimizasyon Yükü"</b> (her adımda işlemciyi yorması) devam etmektedir.</p></li><li><p data-path-to-node="9,1,1,1,0"><b data-path-to-node="9,1,1,1,0" data-index-in-node="0">- Savunma Stratejiniz:</b> Raporunuzda bu makaleye atıf yaparak şunu demelisiniz: <i data-path-to-node="9,1,1,1,0" data-index-in-node="76">"Wu ve Christofides (2025), ML tabanlı MPC''nin kararlılığını ispatlamıştır. Ancak MPC her adımda yinelemeli optimizasyon çözdüğü için hesaplama maliyeti yüksektir. Bizim önerdiğimiz RL yöntemi ise optimizasyonu ''çevrimdışı'' (offline) eğitimde yapar ve çalışma anında (online) milisaniyeler içinde aksiyon üretir."</i></p></li><li><p data-path-to-node="9,1,1,1,0"><i data-path-to-node="9,1,1,1,0" data-index-in-node="76"><br></i></p></li></ul></li><li><p data-path-to-node="9,2,0"><b data-path-to-node="9,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="9,2,1"><li><p data-path-to-node="9,2,1,0,0"><b data-path-to-node="9,2,1,0,0" data-index-in-node="0">- GitHub Kodları:</b> Makalede CSTR simülasyonu için Python kodlarının paylaşıldığı belirtiliyor. Bu kodları indirip kendi RL ajanınızı eğitmek için <b data-path-to-node="9,2,1,0,0" data-index-in-node="143">"Simülasyon Ortamı"</b> olarak kullanabilirsiniz. Bu, projenizi sıfırdan model yazma zahmetinden kurtarır ve literatürle uyumlu hale getirir.</p></li><li><p data-path-to-node="9,2,1,1,0"><b data-path-to-node="9,2,1,1,0" data-index-in-node="0">- Lyapunov Kararlılığı:</b> Makaledeki Lyapunov tabanlı güvenlik analizi, sizin "Fizik Tabanlı Ödül" fonksiyonunuzun matematiksel temelini oluşturabilir. Onlar kısıt (constraint) olarak kullanıyor, siz ceza (penalty) olarak kullanıyorsunuz.</p></li><li><p data-path-to-node="9,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="9,3,0"><b data-path-to-node="9,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="9,3,1"><li><p data-path-to-node="9,3,1,0,0"><b data-path-to-node="9,3,1,0,0" data-index-in-node="0">- Yöntem:</b> Onlar Denetimli Öğrenme (Supervised Learning - RNN) kullanıyor, siz Pekiştirmeli Öğrenme (Reinforcement Learning - SAC) kullanıyorsunuz.</p></li></ul></li><br>', '<li><p data-path-to-node="6,0,0"><b data-path-to-node="6,0,0" data-index-in-node="0">Amaç:</b> Makine Öğrenmesi (ML) tabanlı Model Öngörülü Kontrol (MPC) yöntemlerine dair kapsamlı bir eğitim (tutorial) ve literatür taraması sunmak. Özellikle fiziksel modelin tam bilinmediği durumlarda, Yapay Sinir Ağları (RNN/LSTM) kullanılarak süreç modelinin nasıl öğrenileceğini ve bu modelin MPC içinde kararlılık (stability) garantisiyle nasıl kullanılacağını açıklamak.</p></li><div><br></div><li><p data-path-to-node="6,1,0"><b data-path-to-node="6,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0"><b data-path-to-node="6,1,1,0,0" data-index-in-node="0">- Teori:</b> Lyapunov tabanlı kararlılık analizi. ML modelinin "Genelleştirme Hatası"nın (Generalization Error) kapalı çevrim kontrol performansına etkisi matematiksel olarak incelenmiş.</p></li><li><p data-path-to-node="6,1,1,1,0"><b data-path-to-node="6,1,1,1,0" data-index-in-node="0">- Zorluklar:</b> Veri azlığı (data scarcity), model belirsizliği ve hesaplama yükü gibi pratik sorunlara çözümler sunulmuş.</p></li><li><p data-path-to-node="6,1,1,2,0"><b data-path-to-node="6,1,1,2,0" data-index-in-node="0">- Uygulama:</b> Doğrusal olmayan bir kimyasal reaktör (CSTR) üzerinde RNN tabanlı MPC uygulaması gösterilmiş ve <b data-path-to-node="6,1,1,2,0" data-index-in-node="106">açık kaynak kodları GitHub''da paylaşılmış.</b></p></li><li><p data-path-to-node="6,1,1,2,0"><b data-path-to-node="6,1,1,2,0" data-index-in-node="106"><br></b></p></li></ul></li><li><p data-path-to-node="6,2,0"><b data-path-to-node="6,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0">- ML modelleri (Neural Networks), birinci prensip (first-principles) modellerin yerini alabilir, ancak eğitim verisinin kapsamadığı bölgelerde "tahmin hatası" riski taşır.</p></li><li><p data-path-to-node="6,2,1,1,0">- Bu hatayı yönetmek için Lyapunov tabanlı kısıtlar kullanıldığında, ML-MPC sistemin kararlılığını garanti edebilir.</p></li></ul></li>', 7, 'papers/2/556/10.1515_revce-2024-0055.pdf', 2884056, NULL, '2025-12-02T09:05:54.864Z', '2026-01-22T18:22:53.007Z', 'client_1763443786605_6w2tm45ddct', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (557, 2, 'Reinforcement learning for optimal control of stochastic nonlinear systems', '["Xinji Zhu","Yujia Wang","Zhe Wu"]', 2025, 'AIChE Journal', '10.1002/aic.18840', NULL, NULL, '["Stochastic Control","Nonlinear Systems","Control Lyapunov Function (CLF)","Process Stability","Stability in Probability","SCLF","Sample-and-Hold Implementation","Neural Network Approximation","Matematiksel Güvenlik Temeli","Teorik Doğrulama"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Teorik Temellendirici</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- Lyapunov ve Ödül Fonksiyonu İlişkisi:</b> Siz projenizde "Fizik Tabanlı Ödül" fonksiyonu kullanıyorsunuz. Bu makale diyor ki: <i data-path-to-node="8,1,1,0,0" data-index-in-node="122">"Eğer ödül fonksiyonunuzu ve kontrol politikanızı doğru tasarlarsanız (SCLF şartlarını sağlarsa), RL ajanınız aslında bir kararlılık denetleyicisine dönüşür."</i> Raporunuzda kendi yönteminizi savunurken; <i data-path-to-node="8,1,1,0,0" data-index-in-node="323">"Bizim tasarladığımız fizik tabanlı ceza fonksiyonları, literatürde Zhu ve ark. (2025) tarafından önerilen Stokastik Kontrol Lyapunov Fonksiyonu (SCLF) mantığıyla örtüşmekte olup, sistemin kararlı bölgede kalmasını teşvik etmektedir"</i> diyebilirsiniz.</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Stokastik (Rastgele) Süreçler:</b> Makale, kimyasal süreçlerin doğasında gürültü (stochastic uncertainty) olduğunu vurguluyor. Sizin simülasyonunuzda da sensör gürültüsü veya reaksiyon hızı belirsizliği eklemeniz gerektiğini teorik olarak doğruluyor.</p></li><li><p data-path-to-node="8,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- "Stability in Probability" Kavramı:</b> Güvenlik analizi yaparken <i data-path-to-node="8,2,1,0,0" data-index-in-node="62">"Sistem %100 güvenlidir"</i> demek yerine, bu makaledeki terimi kullanarak <i data-path-to-node="8,2,1,0,0" data-index-in-node="133">"Sistem, SCLF tabanlı yaklaşım sayesinde ''Olasılıksal Kararlılık'' (Stability in Probability) prensiplerine uygun davranmaktadır"</i> demek çok daha bilimseldir.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Sample-and-Hold (Örnekle ve Tut):</b> Dijital kontrolcüler (bilgisayarlar) sürekli değil, kesikli zamanlarda (örn: her 1 saniyede bir) sinyal gönderir. Makale, RL''in bu kesikli yapıda da kararlılığı koruduğunu ispatlıyor. Simülasyonunuzdaki <code data-path-to-node="8,2,1,1,0" data-index-in-node="237">dt</code> (zaman adımı) seçimini bu referansla gerekçelendirebilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0">- Makale çok ağır matematik (ispatlar, teoremler) içeriyor. Sizin projeniz daha çok uygulama/simülasyon odaklı. İspatları yeniden yapmanıza gerek yok, sonuçlarını referans göstermeniz yeterli.</p></li></ul></li>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Stokastik (rastgele gürültü içeren) doğrusal olmayan sistemler için, sadece performansı optimize etmekle kalmayıp aynı zamanda sistemin kararlılığını (stability) matematiksel olarak garanti eden bir RL çerçevesi geliştirmek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Sistem:</b> Stokastik gürültüye maruz kalan Kimyasal Reaktörler (CSTR örnekleri kullanılmış).</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Teori:</b> <b data-path-to-node="5,1,1,1,0" data-index-in-node="7">Stokastik Kontrol Lyapunov Fonksiyonu (SCLF)</b> kavramı merkeze alınmış.</p></li><li><p data-path-to-node="5,1,1,2,0"><b data-path-to-node="5,1,1,2,0" data-index-in-node="0">- Algoritma:</b> RL ajanının öğrendiği "Değer Fonksiyonu"nun (Value Function), aynı zamanda bir Lyapunov Fonksiyonu gibi davranması sağlanmış. Yani ajan ödülü maksimize etmeye çalışırken, aslında matematiksel olarak sistemin enerjisini (hata karesini) minimize ederek kararlılığı sağlıyor.</p></li><li><p data-path-to-node="5,1,1,3,0"><b data-path-to-node="5,1,1,3,0" data-index-in-node="0">- Uygulama:</b> Sinir ağları (Neural Networks) kullanılarak SCLF yaklaşıklanmış ve kontrol eylemlerinin "Örnekle-ve-Tut" (Sample-and-Hold) yöntemiyle uygulandığı gerçekçi senaryolar test edilmiş.</p></li><li><p data-path-to-node="5,1,1,3,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- Geliştirilen yöntem, sistem belirsizlikleri ve gürültüler (noise) altında dahi "Olasılıksal Kararlılık" (Stability in Probability) sağlamıştır.</p></li><li><p data-path-to-node="5,2,1,1,0">- RL tabanlı kontrolcünün, klasik Lyapunov tabanlı yöntemlere göre hem kararlılığı koruduğu hem de optimallik (verim/maliyet) açısından daha iyi sonuçlar verdiği gösterilmiştir.</p></li></ul></li>', 9, 'papers/2/557/AIChE_Journal_-_2025_-_Zhu_-_Reinforcement_learning_for_optimal_control_of_stochastic_nonlinear_systems.pdf', 2834925, NULL, '2025-12-02T09:07:05.284Z', '2026-01-22T18:16:53.213Z', 'client_1763443786605_6w2tm45ddct', 5, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (558, 2, 'How to support decision making with reinforcement learning in hierarchical chemical process control?', '["Kinga Szatmári","Tibor Chován","Sándor Németh","Alex Kummer"]', 2025, 'Chemical Engineering Journal Advances', '10.1016/j.ceja.2025.100753', NULL, NULL, '["Hierarchical Control","Decision Support Systems","Methodology","Explainable AI (XAI)","CRISP-RL","Industrial Implementation Standards","Multi-Agent Systems","Safety Protocols","Proje Yönetim Metodolojisi","Akış Şeması Referansı"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Metodolojik Standart Belirleyici</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- CRISP-RL Metodolojisi:</b> Proje raporunuzda "Yöntem" kısmını yazarken, <i data-path-to-node="8,1,1,0,0" data-index-in-node="68">"Bu projede Szatmári ve ark. (2025) tarafından önerilen CRISP-RL döngüsü takip edilmiştir"</i> diyerek adımlarınızı (Ortam Tasarımı -&gt; Ajan Eğitimi -&gt; Güvenlik Validasyonu) bu standarda göre şematize edebilirsiniz. Bu, projenizin planlı ilerlediğini gösterir.</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Hiyerarşik Konumlandırma:</b> Sizin projeniz (CSTR Kontrolü), hiyerarşinin en alt katmanında (Level 1-2: Basic/Advanced Control) yer alıyor. Makale, bu katmanda RL kullanımının "non-linearite" ve "belirsizlik" sorunlarını çözdüğünü teyit ediyor.</p></li><li><p data-path-to-node="8,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Açıklanabilirlik (Explainability):</b> Makale, RL''in "kara kutu" olmaktan çıkarılması gerektiğini savunuyor. Sizin projenizdeki <b data-path-to-node="8,2,1,0,0" data-index-in-node="124">"Fizik Tabanlı Ödül"</b> mekanizması, aslında bir nevi açıklanabilirlik sunar: <i data-path-to-node="8,2,1,0,0" data-index-in-node="199">"Ajan bu kararı verdi çünkü termal kaçak denklemi (Arrhenius) ona ceza puanı yazdı."</i> Bu argümanı savunmanızda kullanabilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Döngüsel Süreç:</b> Makaledeki akış şemalarını inceleyin. RL ajanını eğittikten sonra simülasyonda test edip, başarısız olursa "Ödül Tasarımı"na geri döndüğünüz süreci, bu makaledeki diyagramlarla görselleştirebilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0">- Makale sadece kontrol değil, tedarik zinciri ve planlama konularına da değiniyor (daha geniş kapsamlı). Sizin odak noktanız ise sadece reaktör içi dinamikler.</p></li></ul></li>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Pekiştirmeli Öğrenme''nin (RL) kimyasal süreç kontrol hiyerarşisinin (temel kontrol, optimizasyon, planlama, çizelgeleme) farklı seviyelerinde nasıl karar destek mekanizması olarak kullanılabileceğini araştırmak. Ayrıca, endüstriyel RL projelerinin standartlaştırılması için <b data-path-to-node="5,0,0" data-index-in-node="280">CRISP-RL</b> (Cross-Industry Standard Process for Reinforcement Learning) adı verilen yeni bir metodolojik akış şeması önermek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Hiyerarşik Analiz:</b> RL''in ISA-95 standardındaki (Otomasyon Piramidi) yeri incelenmiş. Hem tekli ajan (Single-Agent) hem de çoklu ajan (Multi-Agent RL) sistemlerinin bu piramitteki rolleri tartışılmış.</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- CRISP-RL:</b> Klasik veri madenciliği döngüsü (Business Understanding -&gt; Data Understanding -&gt; Modeling -&gt; Evaluation -&gt; Deployment), RL''in dinamik doğasına (Environment Design, Reward Engineering) göre yeniden düzenlenmiş.</p></li><li><p data-path-to-node="5,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- RL, hiyerarşinin alt seviyelerinde (Process Control) PID gibi davranırken, üst seviyelerinde (Scheduling) bir "Operasyon Müdürü" gibi stratejik kararlar alabilir.</p></li><li><p data-path-to-node="5,2,1,1,0">- Endüstriyel kabul için en kritik iki bileşenin <b data-path-to-node="5,2,1,1,0" data-index-in-node="47">Güvenlik (Safety)</b> ve <b data-path-to-node="5,2,1,1,0" data-index-in-node="68">Açıklanabilirlik (Explainability - XRL)</b> olduğu vurgulanmış. Senin "Fizik Tabanlı Ödül" yaklaşımın, bu güvenlik ihtiyacını doğrudan karşılıyor.</p></li></ul></li>', 9, 'papers/2/558/How_to_support_decision_making_with_reinforcement_learning_in_hierarchical_chemical_process.pdf', 5819183, NULL, '2025-12-02T09:10:06.452Z', '2026-01-22T18:08:08.935Z', 'client_1763443786605_6w2tm45ddct', 3, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (559, 2, 'Reinforcement learning-based autonomous control of bench-scale primary separation vessel', '["Oguzhan Dogru","Mahmut Berat Tatlici","Biao Huang"]', 2026, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109405', NULL, NULL, '["Experimental RL","Hybrid Control","Process Automation","Fault Tolerance","State Estimation","Sensor Fusion","Primary Separation Vessel","Real-world Application","Deneysel Kanıt","Gelecek Vizyonu"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Uygulanabilirlik Kanıtı ve Mimari Destek</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- Hibrit Yapı Desteği:</b> Makale, MPC ve RL''i birleştiriyor. Sizin projeniz PID ve RL''i birleştiriyor. Jüriye şunu diyebilirsiniz: <i data-path-to-node="8,1,1,0,0" data-index-in-node="126">"Dogru ve ark. (2026), gerçek sistemlerde tek başına RL yerine klasik yöntemlerle (MPC/PID) hibritlenmiş yapıların daha güvenli ve başarılı olduğunu deneysel olarak göstermiştir."</i></p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Sensör Gürültüsü Gerçeği:</b> Simülasyonlarda genelde sensörler mükemmel ölçüm yapar varsayılır. Bu makale, gerçek hayatta sensörlerin gürültülü olduğunu ve <b data-path-to-node="8,1,1,1,0" data-index-in-node="153">Durum Kestirimi (State Estimation)</b> gerektiğini vurguluyor. Bu, sizin projenizin simülasyonuna "gürültü" (noise) eklemeniz için güçlü bir akademik sebeptir.</p></li><li><p data-path-to-node="8,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Gürültü Dayanıklılığı Testi:</b> Simülasyon ortamınızda sıcaklık sensörüne <code data-path-to-node="8,2,1,0,0" data-index-in-node="71">%1-2</code> oranında rastgele gürültü (Gaussian Noise) ekleyin. RL ajanınızın bu gürültüye rağmen sistemi kararlı tutup tutamadığını test edin. Raporunuzda bu testi <i data-path-to-node="8,2,1,0,0" data-index-in-node="229">"Dogru ve ark. (2026) tarafından vurgulanan sensör belirsizliği problemine karşı algoritmanın dayanıklılığını ölçmek için..."</i> şeklinde sunun.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Hata Toleransı (Fault Tolerance):</b> Makalede "Fault Tolerance" vurgusu var. Siz de simülasyon sırasında örneğin soğutma suyu vanasının anlık olarak sıkışmasını (actuator fault) simüle edip, Hibrit RL''in bu hatayı nasıl telafi ettiğini gösterebilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0"><b data-path-to-node="8,3,1,0,0" data-index-in-node="0">- Reaksiyon Yok:</b> Ayırma işlemi fizikseldir (yerçekimi/faz ayrımı), CSTR ise kimyasaldır (ekzotermik reaksiyon). CSTR''in termal kaçak riski PSV''den çok daha tehlikeli ve hızlıdır. Bu durum sizin projenizin "Güvenlik" önemini daha da artırır.</p></li><li><p data-path-to-node="8,3,1,0,0"><br></p></li></ul></li>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Birincil Ayırma Kaplarının (PSV) kontrolünde karşılaşılan sensör belirsizlikleri (sensory uncertainty), doğrusal olmayan dinamikler ve operasyonel değişkenliklerle başa çıkmak. Sadece simülasyonda değil, <b data-path-to-node="5,0,0" data-index-in-node="210">gerçek bir deney düzeneğinde</b> çalışabilen, hataya dayanıklı (fault-tolerant) ve otonom bir kontrol çerçevesi geliştirmek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Sistem:</b> Birincil Ayırma Kabı (Primary Separation Vessel - PSV). (Petrol/gaz endüstrisinde su-yağ-gaz ayrımı yapan kritik ünite).</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Algoritma:</b> <b data-path-to-node="5,1,1,1,0" data-index-in-node="11">Hibrit Entegrasyon:</b></p><ol start="1" data-path-to-node="5,1,1,1,1"><li><p data-path-to-node="5,1,1,1,1,0,0"><b data-path-to-node="5,1,1,1,1,0,0" data-index-in-node="0">&nbsp; &nbsp; 1. MPC (Model Predictive Control):</b> Temel kontrol stratejisi.</p></li><li><p data-path-to-node="5,1,1,1,1,1,0"><b data-path-to-node="5,1,1,1,1,1,0" data-index-in-node="0">&nbsp; &nbsp; 2. RL (Reinforcement Learning):</b> MPC''nin performansını artırmak ve uyum sağlamak için yardımcı.</p></li><li><p data-path-to-node="5,1,1,1,1,2,0"><b data-path-to-node="5,1,1,1,1,2,0" data-index-in-node="0">&nbsp; &nbsp; 3. State Estimation (Durum Kestirimi):</b> Gürültülü sensör verilerini temizlemek için sensör füzyonu teknikleri.</p></li></ol></li><li><p data-path-to-node="5,1,1,2,0"><b data-path-to-node="5,1,1,2,0" data-index-in-node="0">- Uygulama:</b> Yöntem, laboratuvar ölçekli gerçek bir PSV düzeneğinde test edilmiştir.</p></li><br></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- Geliştirilen çerçevenin, sensör gürültüleri ve beklenmedik fiziksel bozulmalar altında bile sistemi güvenli ve optimal noktada tutabildiği deneysel olarak kanıtlanmıştır.</p></li><li><p data-path-to-node="5,2,1,1,0">- RL ve Durum Kestirimi entegrasyonunun, tek başına çalışan klasik kontrolcülere göre çok daha yüksek bir "uyum yeteneği" (adaptability) sağladığı görülmüştür.</p></li></ul></li>', 8, 'papers/2/559/Reinforcement_learning-based_autonomous_control_of_bench-scale_primary_separation_vessel.pdf', 3980027, NULL, '2025-12-02T09:37:56.400Z', '2026-01-22T18:08:18.288Z', 'client_1763443786605_6w2tm45ddct', 3, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (560, 2, 'Survey and Tutorial of Reinforcement Learning Methods in Process Systems Engineering', '["Maximilian Bloor","Max Mowbray","Ehecatl Antonio Del Rio Chanona","Calvin Tsay"]', 2025, '', '10.48550/ARXIV.2510.24272', NULL, NULL, '["Tutorial","Process Systems Engineering (PSE)","Reinforcement Learning Theory","ctor-Critic Methods","Continuous Control","State-of-the-Art (2025)","SAC vs DDPG","BAŞUCU KAYNAĞI","TEORİK ÇERÇEVE"]', 'To Read', '[]', '<li><p data-path-to-node="9,1,0"><b data-path-to-node="9,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="9,1,0" data-index-in-node="29">Eğitici, Doğrulayıcı ve Vizyon Verici</b></p><ul data-path-to-node="9,1,1"><li><p data-path-to-node="9,1,1,0,0"><b data-path-to-node="9,1,1,0,0" data-index-in-node="0">- Algoritma Seçiminin Doğrulanması:</b> Makale, sürekli süreçler (CSTR gibi) için <b data-path-to-node="9,1,1,0,0" data-index-in-node="76">Soft Actor-Critic (SAC)</b> yönteminin, kararlılık (stability) ve keşif (exploration) dengesi açısından DDPG''den daha üstün olduğunu teknik detaylarıyla anlatıyor. Bu, senin neden SAC seçtiğinin akademik kanıtıdır.</p></li><li><p data-path-to-node="9,1,1,1,0"><b data-path-to-node="9,1,1,1,0" data-index-in-node="0">- Proje Değerini Artırma:</b> Makale, PSE alanında RL''in henüz emekleme aşamasından çıkıp olgunluk çağına girdiğini, ancak <b data-path-to-node="9,1,1,1,0" data-index-in-node="117">"Güvenlik"</b> ve <b data-path-to-node="9,1,1,1,0" data-index-in-node="131">"Yorumlanabilirlik"</b> sorunlarının hala "Açık Araştırma Konusu" olduğunu söylüyor. Senin projen tam olarak bu açık kapıdan içeri giriyor.</p></li><li><p data-path-to-node="9,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="9,2,0"><b data-path-to-node="9,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="9,2,1"><li><p data-path-to-node="9,2,1,0,0"><b data-path-to-node="9,2,1,0,0" data-index-in-node="0">- Matematiksel Gösterim (Notation):</b> Raporunuzda kullanacağınız matematiksel denklemleri (<span class="math-inline" data-math="S_t, A_t, R_t, \pi(a|s)" data-index-in-node="87"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mord"><span style="margin-right: 0.0576em;" class="mord mathnormal">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span class="" style="top: -2.55em; margin-left: -0.0576em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.2806em;"><span class="" style="top: -2.55em; margin-left: -0.0077em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span style="margin-right: 0.0359em;" class="mord mathnormal">π</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mord">∣</span><span class="mord mathnormal">s</span><span class="mclose">)</span></span></span></span></span>) bu makaledeki standart notasyona göre yazın. Bu, raporunuza uluslararası bir standart kazandırır.</p></li><li><p data-path-to-node="9,2,1,1,0"><b data-path-to-node="9,2,1,1,0" data-index-in-node="0">- Pseudocode (Sözde Kod):</b> Makalede SAC ve diğer algoritmaların çalışma mantığını anlatan şemalar var. Bunları referans göstererek kendi algoritma akış şemanızı oluşturabilirsiniz.</p></li><li><p data-path-to-node="9,2,1,2,0"><b data-path-to-node="9,2,1,2,0" data-index-in-node="0">- Benchmarking (Kıyaslama):</b> Makale, RL''in PID veya MPC ile kıyaslandığı çalışmaları listeliyor. Senin projenin "Karşılaştırmalı Analiz" başlığı için mükemmel argümanlar içeriyor.</p></li><li><p data-path-to-node="9,2,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="9,3,0"><b data-path-to-node="9,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="9,3,1"><li><p data-path-to-node="9,3,1,0,0">- Bu bir uygulama makalesi değil, o yüzden "CSTR için <span class="math-inline" data-math="K_p" data-index-in-node="52"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0715em;" class="mord mathnormal">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.0715em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span></span></span></span></span> değeri şu olmalı" demez. Ama "CSTR için ödül fonksiyonu tasarlarken nelere dikkat etmeli" sorusunun cevabını verir.</p></li></ul></li>', '<li><p data-path-to-node="6,0,0"><b data-path-to-node="6,0,0" data-index-in-node="0">Amaç:</b> Proses Sistemleri Mühendisliği (PSE) topluluğu için özel olarak hazırlanmış, hem yeni başlayanlara RL''i öğreten bir <b data-path-to-node="6,0,0" data-index-in-node="122">Eğitim (Tutorial)</b> hem de mevcut uygulamaları özetleyen bir <b data-path-to-node="6,0,0" data-index-in-node="181">Tarama (Survey)</b> çalışması sunmak. RL''in temel kavramlarından (MDP, Bellman Denklemleri) başlayıp, CSTR kontrolü, tedarik zinciri ve biyo-proses optimizasyonuna kadar geniş bir yelpazeyi kapsıyor.</p></li><div><br></div><li><p data-path-to-node="6,1,0"><b data-path-to-node="6,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0"><b data-path-to-node="6,1,1,0,0" data-index-in-node="0">- Eğitim Kısmı:</b> Algoritmaları üç ana aileye ayırarak anlatıyor: 1) Değer Tabanlı (DQN vb.), 2) Politika Tabanlı (REINFORCE vb.), 3) <b data-path-to-node="6,1,1,0,0" data-index-in-node="130">Aktör-Kritik (Actor-Critic)</b>.</p></li><li><p data-path-to-node="6,1,1,1,0"><b data-path-to-node="6,1,1,1,0" data-index-in-node="0">- Tarama Kısmı:</b> Kimya mühendisliğindeki RL uygulamalarını; sürekli kontrol (continuous control), kesikli (batch) süreçler ve çizelgeleme (scheduling) olarak sınıflandırıyor.</p></li><li><p data-path-to-node="6,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="6,2,0"><b data-path-to-node="6,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0">- Kimya süreçlerinin çoğu sürekli eylem uzayına (continuous action space) sahip olduğu için, <b data-path-to-node="6,2,1,0,0" data-index-in-node="91">Actor-Critic (DDPG, TD3, SAC)</b> yöntemlerinin bu alandaki standart haline geldiği belirtiliyor.</p></li><li><p data-path-to-node="6,2,1,1,0">- "Off-the-shelf" (hazır kütüphane) algoritmaların, kimya mühendisliğinin katı güvenlik kısıtları ve fiziksel sınırları nedeniyle doğrudan uygulanamadığı, mutlaka <b data-path-to-node="6,2,1,1,0" data-index-in-node="161">"Domain Knowledge" (Alan Bilgisi)</b> ile harmanlanması gerektiği vurgulanıyor.</p></li></ul></li>', 10, 'papers/2/560/A_SURVEY_AND_TUTORIAL_OF_REINFORCEMENT_LEARNING.pdf', 1143612, NULL, '2025-12-02T09:40:24.735Z', '2026-01-28T10:06:16.437Z', 'client_1769604999983_07rwwn6k1aq', 9, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (561, 2, 'Where Reinforcement Learning Meets Process Control: Review and Guidelines', '["Ruan de Rezende Faria","Bruno Didier Olivier Capron","Argimiro Resende Secchi","Maurício B. de Souza"]', 2022, 'Processes', '10.3390/pr10112311', 'http://dx.doi.org/10.3390/pr10112311', NULL, '["Process Control","Reinforcement Learning Guidelines","Sim-to-Real Transfer","Imitation Learning","Transfer Learning","Hyperparameter Optimization","Offline Training","Eğitim Metodolojisi","Uygulama Rehberi"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="7,1,0" data-index-in-node="29">Metodolojik Rehber ve İyileştirici</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b data-path-to-node="7,1,1,0,0" data-index-in-node="0">- Taklit Öğrenimi (Imitation Learning):</b> Projenizde PID kontrolcü zaten var. Bu makale diyor ki: <i data-path-to-node="7,1,1,0,0" data-index-in-node="94">"RL ajanını PID ile yarıştırmadan önce, PID''den öğrenmesini sağla."</i> Bu, sizin projenizde RL ajanının eğitim süresini kısaltmak ve güvenliği artırmak için kullanabileceğiniz harika bir tekniktir. Raporunuzda; <i data-path-to-node="7,1,1,0,0" data-index-in-node="302">"Faria ve ark. (2022) tarafından önerilen yöntem izlenerek, RL ajanı ilk aşamada PID kontrolcünün davranışlarını taklit edecek şekilde ön eğitime tabi tutulmuş, ardından kendi politikasını geliştirmesine izin verilmiştir"</i> diyebilirsiniz.</p></li><li><p data-path-to-node="7,1,1,1,0"><b data-path-to-node="7,1,1,1,0" data-index-in-node="0">- Hiperparametre Optimizasyonu:</b> Jüri size <i data-path-to-node="7,1,1,1,0" data-index-in-node="40">"Sinir ağında neden 3 katman ve 64 nöron kullandın?"</i> diye sorarsa, cevabınız bu makaleye dayalı olmalıdır. Makaledeki optimizasyon çerçevesini referans göstererek deneme-yanılma değil, sistematik bir seçim yaptığınızı savunabilirsiniz.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b data-path-to-node="7,2,1,0,0" data-index-in-node="0">- Sim-to-Real (Simülasyondan Gerçeğe):</b> Projeniz şu an simülasyon aşamasında. Ancak raporun "Gelecek Çalışmalar" veya "Yaygın Etki" kısmında, bu makaledeki <b data-path-to-node="7,2,1,0,0" data-index-in-node="153">Transfer Öğrenimi</b> prensiplerine atıfta bulunarak, geliştirdiğiniz ajanın gerçek bir CSTR''e nasıl aktarılabileceğini (Sim-to-Real Gap''in nasıl aşılacağını) anlatabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><b data-path-to-node="7,2,1,1,0" data-index-in-node="0">- Eğitim Stabilitesi:</b> Makale, DDPG gibi algoritmaların hassas olduğunu belirtiyor. Sizin kullandığınız SAC (Soft Actor-Critic) daha kararlıdır, ancak yine de bu makaledeki "hiperparametre optimizasyonu" adımlarını uygulamanız, SAC''nin performansını maksimize eder.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0">- Makale DDPG kullanıyor, siz daha ileri bir teknoloji olan SAC kullanıyorsunuz. (Bunu bir avantaj olarak sunun).</p></li><li><p data-path-to-node="7,3,1,1,0">- Makale veriden öğrenmeye (Data-driven) odaklanırken, siz fizik kurallarından öğrenmeye (Physics-informed) odaklanıyorsunuz.</p></li></ul></li>', '<li><p data-path-to-node="4,0,0"><b data-path-to-node="4,0,0" data-index-in-node="0">Amaç:</b> Pekiştirmeli Öğrenme (RL) uygulamalarının proses kontrolüne entegrasyonundaki zorlukları (eğitim kararsızlığı, gerçek dünyaya aktarım sorunu) aşmak için pratik bir yol haritası sunmak. Özellikle <b data-path-to-node="4,0,0" data-index-in-node="201">Simülasyon Tabanlı Çevrimdışı Eğitim</b> (Simulation-based Offline Training) ve <b data-path-to-node="4,0,0" data-index-in-node="277">Transfer Öğrenimi</b> (Transfer Learning) kavramlarına odaklanarak, RL ajanının "laboratuvardan fabrikaya" geçişini kolaylaştırmak.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b data-path-to-node="4,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b data-path-to-node="4,1,1,0,0" data-index-in-node="0">- Yaklaşım:</b> Literatür taraması ile deneysel bir vaka çalışmasını birleştirmişler.</p></li><li><p data-path-to-node="4,1,1,1,0"><b data-path-to-node="4,1,1,1,0" data-index-in-node="0">- Teknik:</b> <b data-path-to-node="4,1,1,1,0" data-index-in-node="8">Taklit Öğrenimi (Imitation Learning - IL):</b> Ajanı sıfırdan (rastgele) başlatmak yerine, mevcut kontrolcüden (PID veya insan operatör) alınan verilerle "ön eğitime" tabi tutarak başlatma stratejisi.</p></li><li><p data-path-to-node="4,1,1,2,0"><b data-path-to-node="4,1,1,2,0" data-index-in-node="0">- Optimizasyon:</b> RL ajanının başarısını etkileyen hiperparametrelerin (öğrenme katsayısı, ağ katman sayısı vb.) sistematik olarak nasıl optimize edileceğine dair bir çerçeve sunulmuş.</p></li><li><p data-path-to-node="4,1,1,3,0"><b data-path-to-node="4,1,1,3,0" data-index-in-node="0">- Uygulama:</b> DDPG algoritması, Taklit Öğrenimi ile güçlendirilerek bir kesikli (batch) süreç üzerinde test edilmiş.</p></li><li><p data-path-to-node="4,1,1,3,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b data-path-to-node="4,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0"><b data-path-to-node="4,2,1,0,0" data-index-in-node="0">- Taklit Öğrenimi (IL)</b> ile başlatılan ajanların, sıfırdan başlayanlara (tabula rasa) göre çok daha hızlı yakınsadığı (convergence) ve eğitim başlangıcında kararsız davranışlar sergilemediği görülmüş.</p></li><li><p data-path-to-node="4,2,1,1,0">Simülasyon ortamında eğitilen politikanın, <b data-path-to-node="4,2,1,1,0" data-index-in-node="43">Transfer Öğrenimi (TL)</b> teknikleri kullanıldığında gerçek (veya farklı) süreç koşullarına başarıyla adapte olabildiği gösterilmiş.</p></li></ul></li>', 8, 'papers/2/561/Where_Reinforcement_Learning_Meets_Process_Control.pdf', 1277078, NULL, '2025-12-02T17:41:55.500Z', '2026-01-22T18:10:00.888Z', 'client_1769116131465_tu4fu21lhsp', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (562, 2, 'Safe chance constrained reinforcement learning for batch process control', '["M. Mowbray","P. Petsagkourakis","E.A. del Rio-Chanona","D. Zhang"]', 2022, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2021.107630', 'http://dx.doi.org/10.1016/j.compchemeng.2021.107630', NULL, '["Safe RL","Process Safety","Stochastic Optimization","Chance Constraints","Batch Process Control","Uncertainty Handling","Constrained MDP","Güvenlik Yöntemi Alternatifi","Tartışma Referansı"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Metodolojik Alternatif (Benchmark Yöntem)</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- Yöntemsel Farklılık:</b> Siz güvenliği <b data-path-to-node="8,1,1,0,0" data-index-in-node="35">"Fiziksel Bilgi"</b> (Termal denklemlerden gelen ceza) ile sağlarken, bu makale <b data-path-to-node="8,1,1,0,0" data-index-in-node="111">"İstatistiksel Bilgi"</b> (Olasılık dağılımları) ile sağlıyor.</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Savunma Argümanı:</b> Projenizi savunurken; <i data-path-to-node="8,1,1,1,0" data-index-in-node="40">"Mowbray ve ark. (2022) güvenliği şans kısıtları ile sağlamıştır. Ancak bu yöntem geniş bir veri geçmişi ve olasılık dağılımı analizi gerektirir. Bizim projemizdeki <b data-path-to-node="8,1,1,1,0" data-index-in-node="205">Fizik Tabanlı Yaklaşım</b> ise veri az olsa bile termodinamik yasalar değişmeyeceği için daha kesin (deterministik) bir güvenlik kalkanı sunar"</i> diyebilirsiniz.</p></li><li><p data-path-to-node="8,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Belirsizlik Yönetimi:</b> Makale, modelin %100 doğru olmadığı durumlarda güvenliğin nasıl korunacağını tartışıyor. CSTR simülasyonunuzda parametreleri (örn: <span class="math-inline" data-math="U" data-index-in-node="153"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span style="margin-right: 0.109em;" class="mord mathnormal">U</span></span></span></span></span>, <span class="math-inline" data-math="k_0" data-index-in-node="156"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8444em; vertical-align: -0.15em;"></span><span class="mord"><span style="margin-right: 0.0315em;" class="mord mathnormal">k</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.0315em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) rastgele değiştirerek test yaparken, bu makaledeki "olasılıksal güvenlik" kavramına atıf yapabilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Kısıt Tanımı:</b> Makalede güvenlik kısıtlarının nasıl formüle edildiğini (matematiksel eşitsizlikler) inceleyin. Sizin projenizde "Termal Kaçak" sınırını belirlerken benzer bir matematiksel eşik (threshold) kullanabilirsiniz.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0"><b data-path-to-node="8,3,1,0,0" data-index-in-node="0">- Süreç Tipi:</b> Batch süreçlerin sonlu bir zamanı vardır, CSTR sonsuz (sürekli) çalışır. Bu nedenle onların "Episode sonu başarısı" metriği yerine sizin "Anlık kararlılık" metriğiniz farklılaşacaktır.</p></li></ul><div><br></div></li>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Kesikli (Batch) kimyasal süreçlerin kontrolünde, RL ajanlarının öğrenme ve uygulama sırasında güvenlik sınırlarını (sıcaklık, basınç vb.) ihlal etmesini önlemek. Standart RL''in "deneme-yanılma" doğasının getirdiği riskleri, kısıtların belirli bir olasılıkla (<span class="math-inline" data-math="1-\epsilon" data-index-in-node="265"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span></span>) sağlanmasını garanti eden "Şans Kısıtlı" (Chance Constrained) bir çerçeve ile minimize etmek.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Sistem:</b> Biyoprosesler gibi model belirsizliğinin yüksek olduğu <b data-path-to-node="5,1,1,0,0" data-index-in-node="63">Kesikli (Batch)</b> süreçler.</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Algoritma:</b> <b data-path-to-node="5,1,1,1,0" data-index-in-node="11">Safe RL</b> (Güvenli Pekiştirmeli Öğrenme). Ancak güvenliği sadece ödüle ceza ekleyerek (reward shaping) değil, optimizasyon probleminin içine <b data-path-to-node="5,1,1,1,0" data-index-in-node="150">olasılıksal kısıtlar</b> ekleyerek sağlar.</p></li><li><p data-path-to-node="5,1,1,2,0"><b data-path-to-node="5,1,1,2,0" data-index-in-node="0">- Yaklaşım:</b> Süreçteki belirsizlikleri (stokastik yapı) dikkate alarak, ajanın "X sıcaklığını %99 olasılıkla aşma" gibi komutlara uymasını sağlar.</p></li><li><p data-path-to-node="5,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- Önerilen yöntem, belirsizlik altındaki süreçlerde standart RL algoritmalarına göre kısıt ihlallerini (güvenlik kazalarını) radikal şekilde azaltmıştır.</p></li><li><p data-path-to-node="5,2,1,1,0">- Sadece ortalama performansı değil, "en kötü durum" (worst-case) senaryolarını da yönetebildiği gösterilmiştir.</p></li></ul></li>', 7, 'papers/2/562/Safe_chance_constrained_reinforcement_learning_for_batch_process.pdf', 1418332, NULL, '2025-12-02T17:44:46.039Z', '2026-01-22T12:17:53.053Z', 'client_1763443786605_6w2tm45ddct', 6, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (563, 2, 'SafeOR-Gym: A Benchmark Suite for Safe Reinforcement Learning Algorithms on Practical Operations Research Problems', '["Unknown Author"]', 2025, 'arXiv', '10.48550/arXiv.2506.02255', 'https://arxiv.org/abs/2506.02255', NULL, '["Safe RL","Benchmarking","Industrial AI","Constrained MDP (CMDP)","SafeOR-Gym","Operations Research","OmniSafe","Cost-Based Constraints","Problem Tanımı","Ortam Gerekçelendirme"]', 'To Read', '[]', '<li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="5,1,0" data-index-in-node="29">Metodolojik Çerçeveyi Güçlendirici</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Güçlü Argüman:</b> Proje raporunuzda şunu diyebilirsiniz: <i data-path-to-node="5,1,1,0,0" data-index-in-node="54">"Ramanujam ve ark. (2025), mevcut Safe RL çalışmalarının robotik alanına sıkıştığını ve kimya/üretim endüstrisi için özel simülasyon ortamlarına ihtiyaç duyulduğunu belirtmiştir. Bizim geliştirdiğimiz CSTR simülasyon ortamı, tam olarak bu çağrıya yanıt veren, termal güvenlik kısıtlarına sahip özelleştirilmiş bir Safe RL ortamıdır."</i></p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Kısıtlı MDP (CMDP):</b> Makale, güvenliği sağlamak için CMDP (Constrained Markov Decision Process) yapısını kullanıyor. Siz ise "Reward Shaping" (Ödül Şekillendirme) kullanıyorsunuz. Bu farkı raporunuzda tartışarak, <i data-path-to-node="5,1,1,1,0" data-index-in-node="212">"CMDP gibi katı kısıtlar yerine, CSTR''in dinamik yapısına daha uygun olan fizik tabanlı esnek cezalandırma (soft constraints via rewards) tercih edilmiştir"</i> diyebilirsiniz.</p></li><li><p data-path-to-node="5,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0"><b data-path-to-node="5,2,1,0,0" data-index-in-node="0">- Blending Environment (Karıştırma Ortamı):</b> Makaledeki "BlendingEnv", kimyasal proseslere en yakın örnektir. Orada güvenliği nasıl tanımladıklarına (örneğin: ürün kalitesinin belirli aralıkta kalması) bakarak kendi CSTR güvenlik tanımınızı zenginleştirebilirsiniz.</p></li><li><p data-path-to-node="5,2,1,1,0"><b data-path-to-node="5,2,1,1,0" data-index-in-node="0">- OmniSafe Entegrasyonu:</b> Eğer projenizde zamanınız kalırsa, geliştirdiğiniz CSTR ortamını OpenAI Gym (Gymnasium) formatında standartlaştırıp <i data-path-to-node="5,2,1,1,0" data-index-in-node="139">"Bu ortam OmniSafe gibi kütüphanelerle uyumlu hale getirilmiştir"</i> demek, projenizin teknik kalitesini "lisans projesi" seviyesinden "yüksek lisans/doktora" seviyesine taşır.</p></li><li><p data-path-to-node="5,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="5,3,0"><b data-path-to-node="5,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="5,3,1"><li><p data-path-to-node="5,3,1,0,0">Makale algoritmaları (PPO, CPO) kıyaslamak için ortam sunuyor; sizin projeniz ise spesifik bir problemi (CSTR Runaway) çözmek için algoritma (SAC) ve ortam geliştiriyor.</p></li></ul><div><br></div></li><div><br></div><div><br></div>', '<li><p data-path-to-node="3,0,0"><b data-path-to-node="3,0,0" data-index-in-node="0">Amaç:</b> Mevcut "Güvenli Pekiştirmeli Öğrenme" (Safe RL) kıyaslama ortamlarının (benchmarks) genellikle robotik (RoboSuite vb.) üzerine odaklandığını ve endüstriyel/operasyonel (Yöneylem Araştırması - OR) problemlerini temsil etmekte yetersiz kaldığını göstermek. Bu boşluğu doldurmak için enerji sistemleri, üretim ve tedarik zinciri gibi riskli alanlara odaklanan 9 yeni ortamdan oluşan <b data-path-to-node="3,0,0" data-index-in-node="386">"SafeOR-Gym"</b> kütüphanesini sunmak.</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b data-path-to-node="3,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b data-path-to-node="3,1,1,0,0" data-index-in-node="0">- Altyapı:</b> Ortamlar, Safe RL alanında standart haline gelen <b data-path-to-node="3,1,1,0,0" data-index-in-node="58">OmniSafe</b> kütüphanesi ve <b data-path-to-node="3,1,1,0,0" data-index-in-node="82">Constrained MDP (CMDP)</b> arayüzü ile tam uyumlu tasarlanmış.</p></li><li><p data-path-to-node="3,1,1,1,0"><b data-path-to-node="3,1,1,1,0" data-index-in-node="0">- Kapsam:</b> Envanter yönetimi, enerji şebekesi ve kimyasal karıştırma (Blending) gibi problemler için kısıtlar (örneğin: depo kapasitesi, maksimum güç yükü) tanımlanmış.</p></li><li><p data-path-to-node="3,1,1,2,0"><b data-path-to-node="3,1,1,2,0" data-index-in-node="0">- Test:</b> PPO-Lagrangian, CPO (Constrained Policy Optimization) gibi popüler Safe RL algoritmaları bu ortamlarda test edilmiş.</p></li><li><p data-path-to-node="3,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="3,2,0"><b data-path-to-node="3,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- Mevcut Safe RL algoritmalarının, robotik dışı endüstriyel kısıtları öğrenmekte zorlandığı görülmüş.</p></li><li><p data-path-to-node="3,2,1,1,0">Endüstriyel problemlerde "Güvenlik" kısıtlarının ihlalinin maliyetinin çok yüksek olduğu ve standart algoritmaların bu ihlalleri sıfıra indirmekte yetersiz kaldığı raporlanmış.</p></li></ul></li>', 7, 'https://arxiv.org/pdf/2506.02255v1', NULL, NULL, '2025-12-02T17:46:29.958Z', '2026-01-22T12:17:52.601Z', 'client_1763443786605_6w2tm45ddct', 2, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (564, 2, 'Deep reinforcement learning with shallow controllers: An experimental application to PID tuning', '["Nathan P. Lawrence","Michael G. Forbes","Philip D. Loewen","Daniel G. McClement","Johan U. Backström","R. Bhushan Gopaluni"]', 2022, 'Control Engineering Practice', '10.1016/j.conengprac.2021.105046', 'http://dx.doi.org/10.1016/j.conengprac.2021.105046', NULL, '["Process Control","Deep Reinforcement Learning","Hybrid Control Systems","PID Tuning","DDPG","Shallow Controllers","Experimental Validation","Hierarchical RL","Alternatif Hibrit Mimari","Endüstriyel Motivasyon Kaynağı"]', 'To Read', '[]', '<li><p data-path-to-node="8,1,0"><b data-path-to-node="8,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="8,1,0" data-index-in-node="29">Metodolojik Alternatif ve Felsefi Destek</b></p><ul data-path-to-node="8,1,1"><li><p data-path-to-node="8,1,1,0,0"><b data-path-to-node="8,1,1,0,0" data-index-in-node="0">- Güçlü Destek:</b> Makale, "Endüstri saf nöral ağlara güvenmez, PID yapısını korumalıyız" tezini savunuyor. Bu, senin projenin Hibrit ayağının temel motivasyonudur. Raporunda <i data-path-to-node="8,1,1,0,0" data-index-in-node="170">"Lawrence ve ark. (2022), endüstriyel kabul edilebilirlik için PID yapısının korunmasının önemini vurgulamıştır"</i> diyerek kendi yaklaşımını meşrulaştırabilirsin.</p></li><li><p data-path-to-node="8,1,1,1,0"><b data-path-to-node="8,1,1,1,0" data-index-in-node="0">- Teknik Fark (Residual vs Tuning):</b> Bu makale RL''i PID katsayılarını değiştirmek için kullanırken, sen RL''i PID''nin çıktısına <i data-path-to-node="8,1,1,1,0" data-index-in-node="124">ekleme</i> yapmak için kullanıyorsun.</p><ul data-path-to-node="8,1,1,1,1"><li><p data-path-to-node="8,1,1,1,1,0,0"><i data-path-to-node="8,1,1,1,1,0,0" data-index-in-node="0">Argüman:</i> Raporunda bu makaleyi tartışırken; <i data-path-to-node="8,1,1,1,1,0,0" data-index-in-node="44">"Lawrence ve ark. (2022) RL''i parametre ayarlama için kullanmıştır. Ancak bu projede, CSTR''in ani termal kaçak durumlarında PID parametrelerinin değişmesi yavaş kalabileceğinden, doğrudan müdahale edebilen ''Artık (Residual) RL'' mimarisi tercih edilmiştir"</i> diyerek kendi tercihinizi teknik bir temele oturtabilirsiniz.</p></li><li><p data-path-to-node="8,1,1,1,1,0,0"><br></p></li></ul></li></ul></li><li><p data-path-to-node="8,2,0"><b data-path-to-node="8,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="8,2,1"><li><p data-path-to-node="8,2,1,0,0"><b data-path-to-node="8,2,1,0,0" data-index-in-node="0">- Aksiyon Sınırlandırma (Action Bounding):</b> Makalede RL''in üretebileceği PID katsayıları belirli bir aralıkta (örn: <span class="math-inline" data-math="K_c \in [0, 50]" data-index-in-node="113"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span style="margin-right: 0.0715em;" class="mord mathnormal">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.0715em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord">50</span><span class="mclose">]</span></span></span></span></span>) sınırlandırılmıştır. Sen de kendi projende RL ajanının üreteceği ek sinyali (<span class="math-inline" data-math="u_{RL}" data-index-in-node="207"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.5806em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal">u</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3283em;"><span class="" style="top: -2.55em; margin-left: 0em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0077em;" class="mord mathnormal mtight">R</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) belirli bir güvenli aralıkta (örn: <span class="math-inline" data-math="\pm \%10" data-index-in-node="250"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.0833em;"></span><span class="mord">±</span><span class="mord">%10</span></span></span></span></span> vana açıklığı) sınırlandırmalısın. Buna <b data-path-to-node="8,2,1,0,0" data-index-in-node="299">"Safety Layer"</b> (Güvenlik Katmanı) denir.</p></li><li><p data-path-to-node="8,2,1,1,0"><b data-path-to-node="8,2,1,1,0" data-index-in-node="0">- Gerçek Dünya Gürültüsü:</b> Makale deneysel olduğu için sensör gürültüsüyle (noise) başa çıkmak zorunda kalmış. Sen de simülasyonunda sıcaklık sensörüne yapay Gaussian Noise ekleyerek ajanının gürültüye dayanıklılığını test etmelisin.</p></li><li><p data-path-to-node="8,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="8,3,0"><b data-path-to-node="8,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="8,3,1"><li><p data-path-to-node="8,3,1,0,0"><b data-path-to-node="8,3,1,0,0" data-index-in-node="0">- Güvenlik:</b> Makalede "Safety" daha çok sistemin kararlılığı olarak ele alınmış, senin projenin odaklandığı "Termal Kaçak" (Runaway) gibi felaket senaryoları işlenmemiş.</p></li></ul><div><br></div></li><div><br></div><div><br></div>', '<li><p data-path-to-node="5,0,0"><b data-path-to-node="5,0,0" data-index-in-node="0">Amaç:</b> Derin Pekiştirmeli Öğrenme (DRL) algoritmalarının endüstriyel süreçlere uygulanmasındaki "yorumlanabilirlik" ve "güvenlik" sorunlarını çözmek. RL ajanını doğrudan vanayı kontrol eden bir mekanizma yerine, mevcut bir PID kontrolcünün parametrelerini (<span class="math-inline" data-math="K_c, \tau_I, \tau_D" data-index-in-node="256"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8778em; vertical-align: -0.1944em;"></span><span class="mord"><span style="margin-right: 0.0715em;" class="mord mathnormal">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.0715em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span style="margin-right: 0.1132em;" class="mord mathnormal">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3283em;"><span class="" style="top: -2.55em; margin-left: -0.1132em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span style="margin-right: 0.0785em;" class="mord mathnormal mtight">I</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span style="margin-right: 0.1132em;" class="mord mathnormal">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3283em;"><span class="" style="top: -2.55em; margin-left: -0.1132em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span style="margin-right: 0.0278em;" class="mord mathnormal mtight">D</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) anlık olarak optimize eden bir "üst akıl" olarak kullanmak.</p></li><div><br></div><li><p data-path-to-node="5,1,0"><b data-path-to-node="5,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="5,1,1"><li><p data-path-to-node="5,1,1,0,0"><b data-path-to-node="5,1,1,0,0" data-index-in-node="0">- Sistem:</b> Deneysel (gerçek fiziksel) bir Çift Tanklı Su Seviye Sistemi (Coupled Water Tank System).</p></li><li><p data-path-to-node="5,1,1,1,0"><b data-path-to-node="5,1,1,1,0" data-index-in-node="0">- Algoritma:</b> <b data-path-to-node="5,1,1,1,0" data-index-in-node="11">DDPG</b> (Deep Deterministic Policy Gradient).</p></li><li><p data-path-to-node="5,1,1,2,0"><b data-path-to-node="5,1,1,2,0" data-index-in-node="0">- Kontrol Yapısı:</b> "Shallow Controller" (Sığ Kontrolcü) dedikleri yapı, klasik PID''dir. Derin Sinir Ağı (Deep RL), sistemin durumuna göre PID katsayılarını günceller.</p></li><li><p data-path-to-node="5,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="5,2,0"><b data-path-to-node="5,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="5,2,1"><li><p data-path-to-node="5,2,1,0,0">- RL tabanlı PID ayarlama yöntemi, sabit parametreli klasik PID''ye göre referans takibi (setpoint tracking) ve bozucu etki bastırma (disturbance rejection) konularında üstün performans göstermiştir.</p></li><li><p data-path-to-node="5,2,1,1,0">- Yöntemin, sadece simülasyonda değil, gürültülü sensörlere ve gecikmelere sahip gerçek bir fiziksel düzenekte de kararlı çalıştığı kanıtlanmıştır.</p></li></ul></li>', 8, 'papers/2/564/Deep_reinforcement_learning_with_shallow_controllers_An_experimental_application_to_PID_tuning.pdf', 2183538, NULL, '2025-12-02T17:48:42.416Z', '2026-01-22T00:51:41.045Z', 'client_1763443786605_6w2tm45ddct', 3, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (565, 2, 'Exploring reinforcement learning in process control: a comprehensive survey', '["N. Rajasekhar","T.K. Radhakrishnan","N. Samsudeen"]', 2025, 'International Journal of Systems Science', '10.1080/00207721.2025.2469821', 'http://dx.doi.org/10.1080/00207721.2025.2469821', NULL, '["Review Paper","Process Control","Deep Reinforcement Learning","Industry 4.0","Actor-Critic Methods","Continuous Control","Safety Challenges","Sample Efficiency","Ana Literatür Dayanağı","State-of-the-Art"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="7,1,0" data-index-in-node="29">Tam Destekleyici ve Meşrulaştırıcı</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b data-path-to-node="7,1,1,0,0" data-index-in-node="0">- Algoritma Seçimi:</b> Makale, süreç kontrolünde neden Q-Learning gibi ayrık yöntemler yerine DDPG veya <b data-path-to-node="7,1,1,0,0" data-index-in-node="99">SAC</b> gibi sürekli yöntemlerin tercih edildiğini açıklar. Sizin projenizde SAC kullanmanızın "keyfi bir tercih" değil, "literatürün işaret ettiği en güçlü yöntem" olduğunu savunmanızı sağlar.</p></li><li><p data-path-to-node="7,1,1,1,0"><b data-path-to-node="7,1,1,1,0" data-index-in-node="0">- Güvenlik Vurgusu:</b> Makale, "Safe RL" (Güvenli RL) konusunu en önemli araştırma boşluklarından biri olarak tanımlıyor. Sizin projenizdeki "Fizik Tabanlı Ödül" ve "Hibrit Yapı", tam olarak bu boşluğu doldurmaya yönelik olduğu için projenizin akademik değerini artırır.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b data-path-to-node="7,2,1,0,0" data-index-in-node="0">- Literatürdeki Boşluk (Research Gap):</b> Raporunuzun girişinde şu cümleyi kurabilirsiniz: <i data-path-to-node="7,2,1,0,0" data-index-in-node="86">"Rajasekhar ve ark. (2025) tarafından yapılan kapsamlı taramada belirtildiği üzere, RL''in kimyasal süreçlerdeki başarısı kanıtlanmış olsa da, ''güvenlik kısıtlarının entegrasyonu'' halen açık bir araştırma alanıdır. Bu proje, fizik tabanlı ödül mekanizmasıyla bu soruna özgün bir çözüm getirmektedir."</i></p></li><li><p data-path-to-node="7,2,1,1,0"><b data-path-to-node="7,2,1,1,0" data-index-in-node="0">- Hibrit Kontrol:</b> Makale, saf RL yerine klasik kontrolcülerle birleştirilmiş hibrit yapıların (sizin PID+RL yapınız gibi) geçiş süreci için daha güvenli olduğunu savunuyor olabilir (içeriği detaylı okuyunca muhtemelen göreceksiniz). Bu, projenizin "Hibrit (Artık) RL" ayağını destekler.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0">- Bu bir derleme makalesidir, yani doğrudan kodlanacak bir denklem veya simülasyon parametresi içermez. Ancak "hangi yöntemin neden seçildiği" konusundaki teorik argümanları sağlar.</p></li></ul><div><br></div></li><div><br></div><div><br></div>', '<li><p data-path-to-node="4,0,0"><b data-path-to-node="4,0,0" data-index-in-node="0">Amaç:</b> Proses kontrolünde Pekiştirmeli Öğrenme (RL) uygulamalarının mevcut durumunu, zorluklarını ve gelecekteki yönelimlerini kapsamlı bir şekilde haritalandırmak. Özellikle kimya endüstrisindeki doğrusal olmayan (non-linear) ve karmaşık sistemlerin kontrolünde geleneksel yöntemlerin (PID, MPC) sınırlarını ve RL''in vaatlerini analiz etmek.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b data-path-to-node="4,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b data-path-to-node="4,1,1,0,0" data-index-in-node="0">- Kapsam:</b> Son 5-10 yılın en etkili çalışmaları taranmış.</p></li><li><p data-path-to-node="4,1,1,1,0"><b data-path-to-node="4,1,1,1,0" data-index-in-node="0">- Sınıflandırma:</b> Çalışmalar algoritmaya göre (DDPG, SAC, TD3 vb.) ve uygulama alanına göre (CSTR, pH kontrolü, ısı değiştiriciler vb.) kategorize edilmiş.</p></li><li><p data-path-to-node="4,1,1,2,0"><b data-path-to-node="4,1,1,2,0" data-index-in-node="0">- Analiz:</b> RL''in süreç kontrolündeki temel darboğazları olan "Örneklem Verimliliği" (Sample Efficiency), "Güvenlik" (Safety) ve "Kararlılık" (Stability) konuları derinlemesine irdelenmiş.</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b data-path-to-node="4,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Geleneksel PID kontrolcülerin, karmaşık ve değişken dinamiklere sahip süreçlerde (CSTR gibi) yetersiz kaldığı net bir şekilde ortaya konmuş.</p></li><li><p data-path-to-node="4,2,1,1,0">- Sürekli eylem uzaylarında (continuous action spaces) çalışan <b data-path-to-node="4,2,1,1,0" data-index-in-node="61">Actor-Critic</b> algoritmalarının (DDPG ve sizin kullandığınız <b data-path-to-node="4,2,1,1,0" data-index-in-node="120">SAC</b>), süreç kontrolü için "standart" haline gelmeye başladığı belirtilmiş.</p></li><li><p data-path-to-node="4,2,1,2,0">- Endüstriyel adaptasyonun önündeki en büyük engelin "Güvenlik Garantisi" eksikliği olduğu vurgulanmış.</p></li></ul></li>', 10, 'papers/2/565/Exploring_reinforcement_learning_in_process_control__a_comprehensive_survey.pdf', 4898113, NULL, '2025-12-02T17:48:54.327Z', '2026-01-22T00:51:33.955Z', 'client_1763443786605_6w2tm45ddct', 3, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (566, 2, 'Using process data to generate an optimal control policy via apprenticeship and reinforcement learning', '["Max Mowbray","Robin Smith","Ehecatl A. Del Rio‐Chanona","Dongda Zhang"]', 2021, 'AIChE Journal', '10.1002/aic.17306', 'http://dx.doi.org/10.1002/aic.17306', NULL, '["Apprenticeship Learning","Inverse Reinforcement Learning (IRL)","Process Control","Data-Driven Optimization","Warm-Start Strategies","Policy Initialization","Behavior Cloning vs RL","Eğitim Stratejisi Alternatifi","Savunma Referansı"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="7,1,0" data-index-in-node="29">Alternatif ve Tamamlayıcı Yöntem</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b data-path-to-node="7,1,1,0,0" data-index-in-node="0">- Alternatif Yaklaşım:</b> Projenizi savunurken jüri size <i data-path-to-node="7,1,1,0,0" data-index-in-node="52">"Ödül fonksiyonundaki katsayıları (<span class="math-inline" data-math="w_{verim}, w_{guvenlik}" data-index-in-node="87"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.7167em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3117em;"><span class="" style="top: -2.55em; margin-left: -0.0269em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">v</span><span style="margin-right: 0.0278em;" class="mord mathnormal mtight">er</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right: 0.1667em;"></span><span class="mord"><span style="margin-right: 0.0269em;" class="mord mathnormal">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3361em;"><span class="" style="top: -2.55em; margin-left: -0.0269em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span style="margin-right: 0.0359em;" class="mord mathnormal mtight">guv</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span style="margin-right: 0.0197em;" class="mord mathnormal mtight">l</span><span style="margin-right: 0.0315em;" class="mord mathnormal mtight">ik</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span></span></span></span></span>) neye göre belirledin?"</i> diye sorabilir. Bu makaleyi referans göstererek şöyle diyebilirsiniz: <i data-path-to-node="7,1,1,0,0" data-index-in-node="205">"Literatürde Mowbray ve ark. (2021) gibi araştırmacılar bu katsayıları geçmiş veriden öğrenen (Inverse RL) yöntemler kullanmıştır. Ancak biz, CSTR''in termodinamik sınırlarını garanti altına almak için <b data-path-to-node="7,1,1,0,0" data-index-in-node="406">Fizik-Tabanlı (Physics-Informed)</b> manuel tasarımı tercih ettik."</i> Bu, literatüre hakimiyetinizi gösterir.</p></li><li><p data-path-to-node="7,1,1,1,0"><b data-path-to-node="7,1,1,1,0" data-index-in-node="0">- Tamamlayıcı (Warm-Start):</b> Makaledeki "Apprenticeship Learning" fikrini projenize kısmen uyarlayabilirsiniz. RL ajanınızı eğitmeden önce, simülasyonda PID kontrolcüden topladığınız verilerle ajanı "ön eğitime" (Pre-training / Behavioral Cloning) tabi tutarak, eğitimin başında saçmalamasını engelleyebilirsiniz.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b data-path-to-node="7,2,1,0,0" data-index-in-node="0">- "Sıcak Başlangıç" (Warm-Start) Stratejisi:</b> Makale, RL ajanını tamamen rastgele başlatmak yerine, eldeki "iyi-kötü" verilerle başlatmanın önemini vurguluyor. Projenizde "Hibrit RL" kullanıyorsunuz; ajanı eğitirken ilk 1000 adımı PID verisini taklit ederek (Imitation Learning) geçirmesini sağlayabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><b data-path-to-node="7,2,1,1,0" data-index-in-node="0">- Veri Kullanımı:</b> Simülasyon ortamınızda PID kontrolcüyü çalıştırıp veri toplayın. Bu veriyi, RL ajanınızın "başarılı bir operasyon nasıl olur?" sorusunu öğrenmesi için bir referans (baseline) olarak kullanabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b data-path-to-node="7,3,1,0,0" data-index-in-node="0">- Ödül Kaynağı:</b> Onlar veriden öğreniyor, siz fizikten türetiyorsunuz. Sizin yönteminiz güvenlik açısından daha garantici (deterministik), onların yöntemi ise daha esnektir.</p></li></ul></li><div><br></div><div><br></div><div><br></div>', '<li><p data-path-to-node="4,0,0"><b data-path-to-node="4,0,0" data-index-in-node="0">Amaç:</b> Pekiştirmeli Öğrenme (RL) algoritmalarının çok fazla veriye ihtiyaç duyması (data-hungry) ve eğitimin başında tehlikeli/rastgele hareketler yapması sorununu çözmek. Bunun için "Çıraklık Öğrenimi" (Apprenticeship Learning) yöntemini kullanarak, geçmiş süreç verilerinden veya insan operatörlerden öğrenen bir çerçeve geliştirmek.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b data-path-to-node="4,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b data-path-to-node="4,1,1,0,0" data-index-in-node="0">- Yöntem:</b> İki aşamalı bir yapı önerilmiş:</p><ol start="1" data-path-to-node="4,1,1,0,1"><li><p data-path-to-node="4,1,1,0,1,0,0"><b data-path-to-node="4,1,1,0,1,0,0" data-index-in-node="0">&nbsp; &nbsp; 1. Inverse Reinforcement Learning (IRL):</b> Mevcut süreç verilerini (uzman/operatör verisi) analiz ederek, bu veriyi üreten gizli "Ödül Fonksiyonu"nu ve başlangıç politikasını öğrenmek.</p></li><li><p data-path-to-node="4,1,1,0,1,1,0"><b data-path-to-node="4,1,1,0,1,1,0" data-index-in-node="0">&nbsp; &nbsp; 2. Reinforcement Learning (RL):</b> Öğrenilen bu başlangıç politikası ve ödül fonksiyonu ile ajanı "Sıcak Başlatmak" (Warm-start) ve performansı daha da iyileştirmek.</p></li></ol></li><li><p data-path-to-node="4,1,1,1,0"><b data-path-to-node="4,1,1,1,0" data-index-in-node="0">- Uygulama:</b> Yöntem, kimyasal süreç kontrolü senaryolarında test edilmiş ve "sıfırdan öğrenen" (tabula rasa) ajanlara kıyasla performansı ölçülmüş.</p></li><li><p data-path-to-node="4,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b data-path-to-node="4,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- Çıraklık öğrenimi ile başlatılan ajanlar, sıfırdan başlayanlara göre çok daha hızlı öğrenmiş ve kararlı duruma (convergence) ulaşmıştır.</p></li><li><p data-path-to-node="4,2,1,1,0">- Geçmiş veriden çıkarılan ödül fonksiyonu, sürecin gerçek hedeflerini (verim, güvenlik vb.) başarıyla temsil edebilmiştir.</p></li></ul></li>', 7, 'papers/2/566/Using_process_data_to_generate_an_optimal_control_policy_via_apprenticeshio_and_reinforcement_learning.pdf', 3736126, NULL, '2025-12-02T17:50:55.127Z', '2026-01-22T00:51:23.792Z', 'client_1763443786605_6w2tm45ddct', 3, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (567, 2, 'Reinforcement learning based optimal control of batch processes using Monte-Carlo deep deterministic policy gradient with phase segmentation', '["Haeun Yoo","Boeun Kim","Jong Woo Kim","Jay H. Lee"]', 2021, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2020.107133', 'http://dx.doi.org/10.1016/j.compchemeng.2020.107133', NULL, '["Batch Process Control","Deep Reinforcement Learning","Robust Control","Actor-Critic Methods","DDPG","Monte-Carlo Sampling","Phase Segmentation","Uncertainty Management","Polymerization","Metodolojik Dayanak","Belirsizlik Yönetimi"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="7,1,0" data-index-in-node="29">Metodolojik Destekleyici ve Tamamlayıcı</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b data-path-to-node="7,1,1,0,0" data-index-in-node="0">- RL vs NMPC:</b> Makale, RL''in (özellikle eğitildikten sonraki hız avantajıyla) NMPC''ye güçlü bir alternatif olduğunu kanıtlıyor. Bu, sizin projenizdeki "Neden klasik kontrol değil de RL?" sorusuna verilecek en güçlü teknik cevabı (online computational efficiency) destekler.</p></li><li><p data-path-to-node="7,1,1,1,0"><b data-path-to-node="7,1,1,1,0" data-index-in-node="0">- Deterministik vs Stokastik:</b> Sizin projenizdeki <b data-path-to-node="7,1,1,1,0" data-index-in-node="47">SAC (Soft Actor-Critic)</b> stokastik (olasılıksal) bir politika izlerken, bu makaledeki <b data-path-to-node="7,1,1,1,0" data-index-in-node="132">DDPG</b> deterministik bir politika izler. Makale, deterministik yapının belirsizlikleri yönetmek için Monte-Carlo (MC) simülasyonlarıyla desteklenmesi gerektiğini savunur. Bu, SAC kullanmanızın (doğası gereği entropi maksimizasyonu yaptığı için) neden daha avantajlı olabileceğini tartışmanız için bir zemin yaratır.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b data-path-to-node="7,2,1,0,0" data-index-in-node="0">- Monte-Carlo (MC) ile Gürültü Ekleme:</b> RL ajanınızı eğitirken, simülasyon ortamınızdaki parametreleri (örn: ısı transfer katsayısı <span class="math-inline" data-math="U" data-index-in-node="129"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span style="margin-right: 0.109em;" class="mord mathnormal">U</span></span></span></span></span>, aktivasyon enerjisi <span class="math-inline" data-math="E/R" data-index-in-node="152"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 1em; vertical-align: -0.25em;"></span><span style="margin-right: 0.0576em;" class="mord mathnormal">E</span><span class="mord">/</span><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span></span></span></span></span>) sabit tutmak yerine, bu makaledeki gibi her "episode" başında belirli bir aralıkta rastgele değiştirerek (MC sampling) eğitirseniz, ajanınız gerçek dünyadaki sensör hatalarına ve model uyuşmazlıklarına karşı çok daha dayanıklı olur.</p></li><li><p data-path-to-node="7,2,1,1,0"><b data-path-to-node="7,2,1,1,0" data-index-in-node="0">- Faz Bölümleme (Phase Segmentation) Fikri:</b> CSTR sürekli bir süreç olsa da, "Başlatma" (Startup) ve "Dengeye Gelme" (Steady-state) aşamaları farklı dinamikler gösterir. Eğer projenizde "reaktörü sıfırdan başlatma" senaryosu varsa, bu makaledeki gibi iki farklı ajan (Biri startup için, biri steady-state için) kullanma fikrini adapte edebilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0"><b data-path-to-node="7,3,1,0,0" data-index-in-node="0">- Süreç Tipi:</b> Onlar "son ürün kalitesine" (batch sonu) odaklanırken, siz "anlık kararlılık ve güvenliğe" (runaway prevention) odaklanıyorsunuz.</p></li><li><p data-path-to-node="7,3,1,1,0"><b data-path-to-node="7,3,1,1,0" data-index-in-node="0">- Güvenlik:</b> Makale optimizasyon odaklıdır, "Hard Safety Constraints" (Kesin Güvenlik Kısıtları) konusu bu makalede sizin projenizdeki kadar baskın değildir.</p></li></ul><div><br></div></li><div><br></div><div><br></div>', '<ul data-path-to-node="4"><li><p data-path-to-node="4,0,0"><b data-path-to-node="4,0,0" data-index-in-node="0">Amaç:</b> Kesikli (Batch) ve Yarı-Kesikli (Fed-Batch) kimyasal süreçlerin kontrolünde, model belirsizliklerine karşı dirençli (robust) ve hesaplama yükü düşük bir optimal kontrol stratejisi geliştirmek. Geleneksel Doğrusal Olmayan Model Öngörülü Kontrol (NMPC) yöntemlerinin model hatalarına karşı hassasiyetini ve online hesaplama yükünü aşmak.</p></li><li><p data-path-to-node="4,0,0"><br></p></li><li><p data-path-to-node="4,1,0"><b data-path-to-node="4,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b data-path-to-node="4,1,1,0,0" data-index-in-node="0">- Sistem:</b> İki farklı vaka çalışması: 1) Fed-batch Penisilin üretimi, 2) Polimerizasyon reaktörü. (Her ikisi de zamanla değişen dinamiklere sahip kesikli süreçlerdir).</p></li><li><p data-path-to-node="4,1,1,1,0"><b data-path-to-node="4,1,1,1,0" data-index-in-node="0">- Algoritma:</b> <b data-path-to-node="4,1,1,1,0" data-index-in-node="11">MC-DDPG</b> (Monte-Carlo Deep Deterministic Policy Gradient). Standart DDPG algoritması, model belirsizliklerini kapsamak için Monte-Carlo örneklemesi ile güçlendirilmiştir.</p></li><li><p data-path-to-node="4,1,1,2,0"><b data-path-to-node="4,1,1,2,0" data-index-in-node="0">- Yenilik:</b> <b data-path-to-node="4,1,1,2,0" data-index-in-node="9">Phase Segmentation (Faz Bölümleme):</b> Uzun süren kesikli süreçleri tek bir sinir ağı ile kontrol etmek yerine, süreci belirli zaman dilimlerine (fazlara) bölüp, her faz için özelleşmiş alt-ajanlar eğitme stratejisi uygulanmıştır.</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b data-path-to-node="4,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- MC-DDPG algoritması, parametrik belirsizlikler altında Robust NMPC (RNMPC) ile yarışabilir, hatta onu geçen bir performans sergilemiştir.</p></li><li><p data-path-to-node="4,2,1,1,0">- Online uygulama sırasında (ajan eğitildikten sonra), NMPC''nin optimizasyon çözmesi saniyeler/dakikalar sürerken, RL ajanı milisaniyeler içinde aksiyon üretebilmiştir.</p></li><li><p data-path-to-node="4,2,1,2,0">- Faz bölümleme tekniği, ajanın öğrenme hızını ve kararlılığını artırmıştır.</p></li></ul></li><li><br></li></ul>', 6, 'papers/2/567/Reinforcement_learning_based_optimal_control_of_batch_processes_using_Monte-Carlo_deep_deterministic_policy_gradient_with_phase_segmentation.pdf', 1917667, NULL, '2025-12-02T17:51:42.352Z', '2026-01-22T00:51:16.559Z', 'client_1763443786605_6w2tm45ddct', 4, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (568, 2, 'Recent Advances in Reinforcement Learning for Chemical Process Control', '["Venkata Srikar Devarakonda","Wei Sun","Xun Tang","Yuhe Tian"]', 2025, 'Processes', '10.3390/pr13061791', 'http://dx.doi.org/10.3390/pr13061791', NULL, '["Review Paper","Chemical Process Control","Safe RL","Artificial Intelligence in ChE","Controller Tuning vs Direct Control","Constrained MDP","Actor-Critic Methods","Hybrid Control Architectures","Ana Literatür Dayanağı","Literatür Haritası"]', 'To Read', '[]', '<li><p data-path-to-node="7,1,0"><b data-path-to-node="7,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="7,1,0" data-index-in-node="29">Teorik Temel Oluşturucu ve Doğrulayıcı</b></p><ul data-path-to-node="7,1,1"><li><p data-path-to-node="7,1,1,0,0"><b data-path-to-node="7,1,1,0,0" data-index-in-node="0">- Projenin Meşruiyeti:</b> Makale, "Neden PID yerine RL?" sorusuna akademik yanıtlar verirken, aynı zamanda "Neden saf RL değil de Güvenli/Hibrit RL?" sorusunu da soruyor. Sizin projeniz tam olarak bu boşluğu (Güvenlik + Hibrit Yapı) doldurmayı hedeflediği için, bu derleme makalesi sizin projenizin <b data-path-to-node="7,1,1,0,0" data-index-in-node="294">"güncel ve gerekli"</b> olduğunu kanıtlar.</p></li><li><p data-path-to-node="7,1,1,1,0"><b data-path-to-node="7,1,1,1,0" data-index-in-node="0">- Hibrit Yaklaşım Desteği:</b> Makale, RL''in klasik kontrolcülerle (PID/MPC) birlikte çalıştığı hiyerarşik veya hibrit yapıların, saf RL''den daha güvenli olduğunu belirtmektedir. Bu, sizin <b data-path-to-node="7,1,1,1,0" data-index-in-node="183">"Hibrit (Residual) RL"</b> stratejinizi doğrudan destekler.</p></li><li><p data-path-to-node="7,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="7,2,0"><b data-path-to-node="7,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="7,2,1"><li><p data-path-to-node="7,2,1,0,0"><b data-path-to-node="7,2,1,0,0" data-index-in-node="0">- Terminoloji Birliği:</b> Raporunuzu yazarken bu makaledeki sınıflandırmaları kullanın. Örneğin, kendi yönteminizi <b data-path-to-node="7,2,1,0,0" data-index-in-node="110">"Direct Control Policy Learning with Safety Constraints"</b> olarak tanımlayabilirsiniz.</p></li><li><p data-path-to-node="7,2,1,1,0"><b data-path-to-node="7,2,1,1,0" data-index-in-node="0">- Güvenlik Yöntemleri Tartışması:</b> Makale, güvenliği sağlamak için "Ceza Fonksiyonları" (sizin yaptığınız reward shaping), "Kısıtlı MDP''ler" ve "Kontrol Bariyer Fonksiyonları"ndan bahseder. Siz raporunuzda, <i data-path-to-node="7,2,1,1,0" data-index-in-node="204">"Devarakonda ve ark. (2024) tarafından belirtilen güvenlik yöntemlerinden, süreç dinamiğine en uygun olan Fizik Tabanlı Ödül Şekillendirme (Physics-Informed Reward Shaping) tercih edilmiştir"</i> diyerek literatüre hakimiyetinizi gösterebilirsiniz.</p></li><li><p data-path-to-node="7,2,1,2,0"><b data-path-to-node="7,2,1,2,0" data-index-in-node="0">- Gelecek Vizyonu:</b> Makalenin "Challenges" (Zorluklar) kısmında bahsedilen "Sample Efficiency" (Örneklem Verimliliği) sorununu, simülasyon ortamı kullanarak aştığınızı belirtebilirsiniz.</p></li><li><p data-path-to-node="7,2,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="7,3,0"><b data-path-to-node="7,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="7,3,1"><li><p data-path-to-node="7,3,1,0,0">Bu makale yeni bir yöntem önermez, var olanları özetler. Dolayısıyla sayısal bir "kıyaslama verisi" (benchmark score) sunmaz.</p></li></ul></li><div><br></div><div><br></div>', '<li><p data-path-to-node="4,0,0"><b data-path-to-node="4,0,0" data-index-in-node="0">Amaç:</b> Kimyasal süreç kontrolünde Pekiştirmeli Öğrenme (RL) kullanımına dair son gelişmeleri, özellikle <b data-path-to-node="4,0,0" data-index-in-node="103">güvenlik (safe RL)</b>, <b data-path-to-node="4,0,0" data-index-in-node="123">örneklem verimliliği</b> ve <b data-path-to-node="4,0,0" data-index-in-node="147">kontrol mimarileri</b> açısından sistematik olarak incelemek ve sınıflandırmak.</p></li><div><br></div><li><p data-path-to-node="4,1,0"><b data-path-to-node="4,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="4,1,1"><li><p data-path-to-node="4,1,1,0,0"><b data-path-to-node="4,1,1,0,0" data-index-in-node="0">- Kapsam:</b> Son yıllarda yayınlanan yüzlerce makale taranmış.</p></li><li><p data-path-to-node="4,1,1,1,0"><b data-path-to-node="4,1,1,1,0" data-index-in-node="0">- Sınıflandırma:</b> Çalışmalar iki ana başlıkta incelenmiş:</p><ol start="1" data-path-to-node="4,1,1,1,1"><li><p data-path-to-node="4,1,1,1,1,0,0"><b data-path-to-node="4,1,1,1,1,0,0" data-index-in-node="0">&nbsp; &nbsp; 1. Kontrolcü Ayarlama (Controller Tuning):</b> RL''in mevcut PID veya MPC parametrelerini optimize etmesi.</p></li><li><p data-path-to-node="4,1,1,1,1,1,0"><b data-path-to-node="4,1,1,1,1,1,0" data-index-in-node="0">&nbsp; &nbsp; 2. Doğrudan Kontrol (Direct Control Policy Learning):</b> RL''in doğrudan vanaları/aktüatörleri kontrol etmesi (Senin projenin odaklandığı alan).</p></li></ol></li><li><p data-path-to-node="4,1,1,2,0"><b data-path-to-node="4,1,1,2,0" data-index-in-node="0">-Kritik Odak:</b> Endüstriyel uygulama önündeki en büyük engel olan "Güvenlik" konusuna özel bir parantez açılmış (Constrained MDPs, Control Barrier Functions vb.).</p></li><li><p data-path-to-node="4,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="4,2,0"><b data-path-to-node="4,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="4,2,1"><li><p data-path-to-node="4,2,1,0,0">- RL, doğrusal olmayan (nonlinear) ve belirsiz süreçlerde (CSTR gibi) klasik yöntemlere göre üstün performans gösterme potansiyeline sahiptir.</p></li><li><p data-path-to-node="4,2,1,1,0">- Ancak, "keşif" (exploration) sırasında sistemin tehlikeli bölgelere girme riski, endüstriyel kabulü engellemektedir.</p></li><li><p data-path-to-node="4,2,1,2,0">- Hibrit yapılar ve fiziği sürece dahil eden (physics-informed) yaklaşımlar, geleceğin en parlak araştırma alanları olarak işaret edilmiştir.</p></li></ul></li>', 10, 'papers/2/568/Recent_Advances_in_Reinforcement_Learning_for_Chemical_Process_Control.pdf', 6272374, NULL, '2025-12-02T17:53:47.671Z', '2026-01-22T00:50:49.417Z', 'client_1763443786605_6w2tm45ddct', 4, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (569, 44, 'Reinforcement Learning Approach to Autonomous PID Tuning', '["Oguzhan Dogru","Kirubakaran Velswamy","Fadi Ibrahim","Yuqi Wu","Arun Senthil Sundaramoorthy","Biao Huang","Shu Xu","Mark Nixon","Noel Bell"]', 2022, '2022 American Control Conference (ACC)', '10.23919/acc53348.2022.9867687', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:12:47.888Z', '2025-12-03T09:12:47.888Z', NULL, 1, NULL);
