INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (597, 44, 'Soft Actor-Critic: Off-Policy Maximum Entropy Deep Reinforcement Learning with a Stochastic Actor', '["Haarnoja, Tuomas","Zhou, Aurick","Abbeel, Pieter","Levine, Sergey"]', 2018, 'arXiv', '10.48550/ARXIV.1801.01290', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:18:58.341Z', '2025-12-03T09:18:58.341Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (598, 44, 'TASAC: a twin-actor reinforcement learning framework with stochastic policy for batch process control', '["Joshi, Tanuja","Kodamana, H.","Kandath, Harikumar","Kaisare, N."]', 2022, 'ArXiv', '10.48550/arXiv.2204.10685', NULL, NULL, '[]', 'To Read', '[]', 'Due to their complex nonlinear dynamics and batch-to-batch variability, batch processes pose a challenge for process control. Due to the absence of accurate models and resulting plant-model mismatch, these problems become harder to address for advanced model-based control strategies. Reinforcement Learning (RL), wherein an agent learns the policy by directly interacting with the environment, offers a potential alternative in this context. RL frameworks with actor-critic architecture have recently become popular for controlling systems where state and action spaces are continuous. It has been shown that an ensemble of actor and critic networks further helps the agent learn better policies due to the enhanced exploration due to simultaneous policy learning. To this end, the current study proposes a stochastic actor-critic RL algorithm, termed Twin Actor Soft Actor-Critic (TASAC), by incorporating an ensemble of actors for learning, in a maximum entropy framework, for batch process control.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:42.602Z', '2025-12-03T09:22:42.602Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (599, 44, 'Reinforcement Learning-based Control via Y-wise Affine Neural Networks (YANNs)', '["Braniff, Austin","Tian, Yuhe"]', 2025, 'ArXiv', '10.48550/arXiv.2508.16474', NULL, NULL, '[]', 'To Read', '[]', 'This work presents a novel reinforcement learning (RL) algorithm based on Y-wise Affine Neural Networks (YANNs). YANNs provide an interpretable neural network which can exactly represent known piecewise affine functions of arbitrary input and output dimensions defined on any amount of polytopic subdomains. One representative application of YANNs is to reformulate explicit solutions of multi-parametric linear model predictive control. Built on this, we propose the use of YANNs to initialize RL actor and critic networks, which enables the resulting YANN-RL control algorithm to start with the confidence of linear optimal control. The YANN-actor is initialized by representing the multi-parametric control solutions obtained via offline computation using an approximated linear system model. The YANN-critic represents the explicit form of the state-action value function for the linear system and the reward function as the objective in an optimal control problem (OCP). Additional network layers are injected to extend YANNs for nonlinear expressions, which can be trained online by directly interacting with the true complex nonlinear system. In this way, both the policy and state-value functions exactly represent a linear OCP initially and are able to eventually learn the solution of a general nonlinear OCP. Continuous policy improvement is also implemented to provide heuristic confidence that the linear OCP solution serves as an effective lower bound to the performance of RL policy. The YANN-RL algorithm is demonstrated on a clipped pendulum and a safety-critical chemical-reactive system. Our results show that YANN-RL significantly outperforms the modern RL algorithm using deep deterministic policy gradient, especially when considering safety constraints.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:43.189Z', '2025-12-03T09:22:43.189Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (600, 44, 'One-Layer Real-Time Optimization Using Reinforcement Learning: A Review with Guidelines', '["Faria, R. R.","Capron, B.","Jr, M. B. de Souza","Secchi, A."]', 2023, 'Processes', '10.3390/pr11010123', NULL, NULL, '[]', 'To Read', '[]', 'This paper reviews real-time optimization from a reinforcement learning point of view. The typical control and optimization system hierarchy depend on the layers of real-time optimization, supervisory control, and regulatory control. The literature about each mentioned layer is reviewed, supporting the proposal of a benchmark study of reinforcement learning using a one-layer approach. The multi-agent deep deterministic policy gradient algorithm was applied for economic optimization and control of the isothermal Van de Vusse reactor. The cooperative control agents allowed obtaining sufficiently robust control policies for the case study against the hybrid real-time optimization approach.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:43.484Z', '2025-12-03T09:22:43.484Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (601, 44, 'Enhanced Reinforcement Learning-driven Process Design via Quantum Machine Learning', '["Braniff, Austin","You, Fengqi","Tian, Yuhe"]', 2025, 'Systems and Control Transactions', '10.69997/sct.149501', NULL, NULL, '[]', 'To Read', '[]', 'In this work, we introduce a quantum-enhanced reinforcement learning (RL) framework for process design synthesis. RL-driven methods for generating process designs have gained momentum due to their ability to intelligently identify optimal configurations without requiring pre-defined superstructures or flowsheet configurations. This eliminates reliance on prior expert knowledge, offering a comprehensive and robust design strategy. However, navigating the vast combinatorial design space poses computational challenges. To address this, a novel approach integrating RL with quantum machine learning (QML) is proposed. QML leverages theoretical advantages over classical methods to accelerate searches in large spaces. Built upon our prior work, the approach begins with a maximum set of available unit operations, represented in a flowsheet structure using an input-output stream matrix as RL observations. A Deep Q-Network (DQN) algorithm trains a parameterized quantum circuit (PQC) in place of a classical neural network (NN). The design structures generated by the RL agent are optimized using the IDAES Process Systems Engineering Framework, with the optimization objectives used as rewards to RL (e.g., cost, productivity). This quantum-enhanced algorithm is performed on a hydrodealkylation process case study, showcasing its efficiency and improved performance in navigating complex design spaces.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:43.777Z', '2025-12-03T09:22:43.777Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (602, 44, 'YANNs: Y-wise Affine Neural Networks for Exact and Efficient Representations of Piecewise Linear Functions', '["Braniff, Austin","Tian, Yuhe"]', 2025, 'ArXiv', '10.48550/arXiv.2505.07054', NULL, NULL, '[]', 'To Read', '[]', 'This work formally introduces Y-wise Affine Neural Networks (YANNs), a fully-explainable network architecture that continuously and efficiently represent piecewise affine functions with polytopic subdomains. Following from the proofs, it is shown that the development of YANNs requires no training to achieve the functionally equivalent representation. YANNs thus maintain all mathematical properties of the original formulations. Multi-parametric model predictive control is utilized as an application showcase of YANNs, which theoretically computes optimal control laws as a piecewise affine function of states, outputs, setpoints, and disturbances. With the exact representation of multi-parametric control laws, YANNs retain essential control-theoretic guarantees such as recursive feasibility and stability. This sets YANNs apart from the existing works which apply neural networks for approximating optimal control laws instead of exactly representing them. By optimizing the inference speed of the networks, YANNs can evaluate substantially faster in real-time compared to traditional piecewise affine function calculations. Numerical case studies are presented to demonstrate the algorithmic scalability with respect to the input/output dimensions and the number of subdomains. YANNs represent a significant advancement in control as the first neural network-based controller that inherently ensures both feasibility and stability. Future applications can leverage them as an efficient and interpretable starting point for data-driven modeling/control.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:44.070Z', '2025-12-03T09:22:44.070Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (603, 44, 'Machine learning for industrial sensing and control: A survey and practical perspective', '["Lawrence, Nathan P.","Damarla, S.","Kim, Jong Woo","Tulsyan, Aditya","Amjad, Faraz","Wang, Kai","Chachuat, Benoît","Lee, Jong Min","Huang, B.","Gopaluni, R. Bhushan"]', 2024, 'ArXiv', '10.1016/j.conengprac.2024.105841', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:44.364Z', '2025-12-03T09:22:44.364Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (604, 44, 'Development of algorithms for augmenting and replacing conventional process control using reinforcement learning', '["Beahr, Daniel","Bhattacharyya, D.","Allan, Douglas A.","Zitney, S."]', 2024, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2024.108826', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:44.659Z', '2025-12-03T09:22:44.659Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (605, 44, 'Facilitating Reinforcement Learning for Process Control Using Transfer Learning: Overview and Perspectives', '["Lin, Runze","Chen, Junghui","Xie, Lei","Su, Hongye"]', 2024, '2025 37th Chinese Control and Decision Conference (CCDC)', '10.1109/CCDC65474.2025.11090213', NULL, NULL, '[]', 'To Read', '[]', 'In the context of Industry 4.0 and smart manufacturing, the field of process industry optimization and control is also undergoing a digital transformation. With the rise of Deep Reinforcement Learning (DRL), its application in process control has attracted widespread attention. However, the extremely low sample efficiency and the safety concerns caused by exploration in DRL hinder its practical implementation in industrial settings. Transfer learning offers an effective solution for DRL, enhancing its generalization and adaptability in multi-mode control scenarios. This paper provides insights into the use of DRL for process control from the perspective of transfer learning. We analyze the challenges of applying DRL in the process industry and the necessity of introducing transfer learning. Furthermore, recommendations and prospects are provided for future research directions on how transfer learning can be integrated with DRL to enhance process control. This paper aims to offer a set of promising, user-friendly, easy-to-implement, and scalable approaches to artificial intelligence-facilitated industrial control for scholars and engineers in the process industry.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:44.953Z', '2025-12-03T09:22:44.953Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (606, 44, 'Supply responsive scheduling for ethylene cracking furnace systems based on deep reinforcement learning', '["Li, Haoran","Qiu, Tong"]', 2024, 'AIChE Journal', '10.1002/aic.18563', NULL, NULL, '[]', 'To Read', '[]', 'Ethylene is one of the most important chemicals, and scheduling optimization is crucial for the profitability of ethylene cracking furnace systems. With the diversification of feedstocks and the high variability in prices, supply chain fluctuations pose significant challenges to the scheduling decisions. Dynamically responding to these fluctuations has become crucial. Traditional mixed integer nonlinear programming (MINLP) models lack the capability of supply chain response, while receding horizon optimization (RHO) models require parameter prediction and repeated optimization solving. To address this challenge, we propose a deep reinforcement learning‐based framework that includes an ethylene dynamic scheduling environment and a decision agent based on deep Q‐network. Across three test cases, compared to the MINLP and RHO models, this framework significantly minimizes losses caused by supply chain fluctuations, thereby increasing daily average net profits by 9%–27%, demonstrating its significant potential for application in responsive scheduling in the presence of supply chain fluctuations.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:45.396Z', '2025-12-03T09:22:45.396Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (607, 44, 'A practically implementable reinforcement learning‐based process controller design', '["Hassanpour, H.","Wang, Xiaonian","Corbett, Brandon","Mhaskar, P."]', 2023, 'AIChE Journal', '10.1002/aic.18245', NULL, NULL, '[]', 'To Read', '[]', 'The present article enables reinforcement learning (RL)‐based controllers for process control applications. Existing instances of RL‐based solutions have significant challenges for online implementation since the training process of an RL agent (controller) presently requires practically impossible number of online interactions between the agent and the environment (process). To address this challenge, we propose an implementable model‐free RL method developed by leveraging industrially implemented model predictive control (MPC) calculations (often designed using a simple linear model identified via step tests). In the first step, MPC calculations are used to pretrain an RL agent that can mimic the MPC performance. Specifically, the MPC calculations are used to pretrain the actor, and the objective function is used to pretrain the critic(s). The pretrained RL agent is then employed within a model‐free RL framework to control the process in a way that initially imitates MPC behavior (thus not compromising process performance and safety), but also continuously learns and improve its performance over the nominal linear MPC. The effectiveness of the proposed approach is illustrated through simulations on a chemical reactor example.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:45.690Z', '2025-12-03T09:22:45.690Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (608, 44, 'A practically implementable reinforcement learning control approach by leveraging offset-free model predictive control', '["Hassanpour, H.","Mhaskar, P.","Corbett, Brandon"]', 2024, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2023.108511', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:45.985Z', '2025-12-03T09:22:45.985Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (609, 44, 'Model-based safe reinforcement learning for nonlinear systems under uncertainty with constraints tightening approach', '["Kim, Yeonsoo","Oh, Tae Hoon"]', 2024, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2024.108601', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:46.278Z', '2025-12-03T09:22:46.278Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (610, 44, 'A tutorial review of policy iteration methods in reinforcement learning for nonlinear optimal control', '["Wang, Yujia","Zhu, Xinji","Wu, Zhe"]', 2025, 'Digital Chemical Engineering', '10.1016/j.dche.2025.100231', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:46.574Z', '2025-12-03T09:22:46.574Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (611, 44, 'Application of unsupervised machine learning methods to actor-critic structures in reinforcement learning for training and online implementation', '["Beahr, Daniel","Bhattacharyya, Debangsu"]', 2025, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2025.109392', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:46.868Z', '2025-12-03T09:22:46.868Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (612, 44, 'A Practical Reinforcement Learning (RL) Controller Design for Nonlinear Systems', '["Hassanpour, H.","Mhaskar, P.","Corbett, Brandon"]', 2024, '2024 American Control Conference (ACC)', '10.23919/ACC60939.2024.10644360', NULL, NULL, '[]', 'To Read', '[]', 'This paper presents a practically implementable reinforcement learning (RL) approach for process control applications. Standard model-free RL approaches are not applicable in practice because the learning process of an RL agent requires random exploration of state and action spaces, which can compromise process safety and economic objectives. To tackle this issue, an offline training strategy is proposed by leveraging existing model predictive control (MPC) to pre-train the RL agent. MPC actions, calculated offline by solving the MPC optimization problem based on a wide range of initial conditions, along with its objective function are utilized to pretrain the actor and critics of the RL agent. The pre-trained RL controller, with similar performance to the MPC performance, is then utilized for online control for further training. The efficacy of the proposed RL controller to improve the tracking performance is demonstrated using a simulation example for a pH neutralization process.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:47.162Z', '2025-12-03T09:22:47.162Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (613, 44, 'Twin actor twin delayed deep deterministic policy gradient (TATD3) learning for batch process control', '["Joshi, Tanuja","Makker, S.","Kodamana, H.","Kandath, Harikumar"]', 2021, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2021.107527', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This study proposes an actor-critic RL algorithm, namely, twin actor twin delayed deep deterministic policy gradient (TATD3), by incorporating twin actor networks in the existing twin-delayed deep Deterministic Policy gradient (TD3) algorithm for the continuous control of batch processes.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:47.603Z', '2025-12-03T09:22:47.603Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (614, 44, 'Q-MPC: stable and efficient reinforcement learning using model predictive control', '["Oh, Tae Hoon"]', 2023, 'IFAC-PapersOnLine', '10.1016/j.ifacol.2023.10.1369', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:48.047Z', '2025-12-03T09:22:48.047Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (615, 44, 'Alleviating parameter-tuning burden in reinforcement learning for large-scale process control', '["Zhu, Lingwei","Takami, G.","Kawahara, Mizuo","Kanokogi, H.","Matsubara, Takamitsu"]', 2022, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2022.107658', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:48.489Z', '2025-12-03T09:22:48.489Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (616, 44, 'Reinforcement Learning for Process Control: Review and Benchmark Problems', '["Park, Joon-Sang","Jung, Hyein","Kim, Jong Woo","Lee, Jong Min"]', 2025, 'International Journal of Control, Automation and Systems', '10.1007/s12555-024-0990-1', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This paper aims to bridge the gap between RL and process control, providing potential applications and insights for process control engineers by implementing fourteen RL algorithms and applying them to six relevant benchmark environments.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:48.785Z', '2025-12-03T09:22:48.785Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (617, 44, 'Meta-reinforcement learning for the tuning of PI controllers: An offline approach', '["McClement, Daniel G.","Lawrence, Nathan P.","Backström, J.","Loewen, Philip D.","Forbes, M.","Gopaluni, R. B."]', 2022, 'Journal of Process Control', '10.1016/j.jprocont.2022.08.002', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This work forms a meta reinforcement learning ( meta-RL) control strategy that can be used to tune proportional–integral controllers and has a recurrent structure that accumulates context to learn a system''s dynamics through a hidden state variable in closed-loop.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:49.083Z', '2025-12-03T09:22:49.083Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (618, 44, 'TASAC: A twin-actor reinforcement learning framework with a stochastic policy with an application to batch process control', '["Joshi, Tanuja","Kodamana, H.","Kandath, Harikumar","Kaisare, N."]', 2023, 'Control Engineering Practice', '10.1016/j.conengprac.2023.105462', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:49.380Z', '2025-12-03T09:22:49.380Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (619, 44, 'Meta Reinforcement Learning for Adaptive Control: An Offline Approach', '["McClement, Daniel G.","Lawrence, Nathan P.","Backstrom, Johan U.","Loewen, Philip D.","Forbes, M.","Gopaluni, R. B."]', 2022, 'ArXiv', '10.48550/arXiv.2203.09661', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This work forms a meta reinforcement learning ( meta-RL) control strategy that takes advantage of known information for training, such as the system gain or time constant, yet controls novel systems in a completely model-free fashion, resulting in a generalized, adaptive, closed-loop tuning strategy.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:49.973Z', '2025-12-03T09:22:49.973Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (620, 44, 'Safe, visualizable reinforcement learning for process control with a warm-started actor network based on PI-control', '["Bras, E. H.","Louw, Tobias M.","Bradshaw, S. M."]', 2024, 'Journal of Process Control', '10.1016/j.jprocont.2024.103340', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:50.270Z', '2025-12-03T09:22:50.270Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (621, 44, 'Lyapunov-based Safe Policy Optimization for Continuous Control', '["Chow, Yinlam","Nachum, Ofir","Faust, Aleksandra","Ghavamzadeh, M.","Duéñez-Guzmán, Edgar A."]', 2019, 'ArXiv', 'https://www.semanticscholar.org/paper/3fa50569925cfecc66fed5ec616682ecf3794ad7', NULL, NULL, '[]', 'To Read', '[]', 'We study continuous action reinforcement learning problems in which it is crucial that the agent interacts with the environment only through safe policies, i.e., policies that do not take the agent to undesirable situations. We formulate these problems as constrained Markov decision processes (CMDPs) and present safe policy optimization algorithms that are based on a Lyapunov approach to solve them. Our algorithms can use any standard policy gradient (PG) method, such as deep deterministic policy gradient (DDPG) or proximal policy optimization (PPO), to train a neural network policy, while guaranteeing near-constraint satisfaction for every policy update by projecting either the policy parameter or the action onto the set of feasible solutions induced by the state-dependent linearized Lyapunov constraints. Compared to the existing constrained PG algorithms, ours are more data efficient as they are able to utilize both on-policy and off-policy data. Moreover, our action-projection algorithm often leads to less conservative policy updates and allows for natural integration into an end-to-end PG training pipeline. We evaluate our algorithms and compare them with the state-of-the-art baselines on several simulated (MuJoCo) tasks, as well as a real-world indoor robot navigation problem, demonstrating their effectiveness in terms of balancing performance and constraint satisfaction. Videos of the experiments can be found in the following link: this https URL.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:50.871Z', '2025-12-03T09:22:50.871Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (622, 44, 'Benchmarking Safe Exploration in Deep Reinforcement Learning', '["Achiam, Josh","Amodei, Dario"]', 2019, '', 'https://www.semanticscholar.org/paper/4d0f6a6ffcd6ab04732ff76420fd9f8a7bb649c3', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This work proposes to standardize constrained RL as the main formalism for safe exploration, and presents the Safety Gym benchmark suite, a new slate of high-dimensional continuous control environments for measuring research progress on constrained RL.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:51.168Z', '2025-12-03T09:22:51.168Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (623, 44, 'Lyapunov-based Safe Policy Optimization', '["Chow, Yinlam","Nachum, Ofir","Ghavamzadeh, M.","Guzman-Duenez, Edgar"]', 2018, '', 'https://www.semanticscholar.org/paper/8c73790d9dd5f17f34635b0265986bd03756bf7f', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: This paper proposes safe policy optimization algorithms that are based on the Lyapunov approach to CMDPs, an approach that has well-established theoretical guarantees in control engineering and is more data efficient as they are able to utilize both on-policy and off-policy data.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:51.465Z', '2025-12-03T09:22:51.465Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (624, 44, 'Safe Policy Learning for Continuous Control', '["Chow, Yinlam","Nachum, Ofir","Faust, Aleksandra","Duéñez-Guzmán, Edgar A.","Ghavamzadeh, M."]', 2019, '', 'https://www.semanticscholar.org/paper/cb9c98819ed1580b2511bd07eb67f5e46ca6ef4d', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: Safe policy optimization algorithms based on a Lyapunov approach to solve continuous action reinforcement learning problems in which it is crucial that the agent interacts with the environment only through near-safe policies, i.e., policies that keep the agent in desirable situations, both during training and at convergence.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:51.761Z', '2025-12-03T09:22:51.761Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (625, 44, 'A Comparative Analysis of PID, Linear MPC and Non Linear MPC in a 2-DOF Helicopter System', '["Benotsmane, Rabab","Ahmad, Salmiah","Ahmad, Mariam","Ali, Rania"]', 2025, '2025 26th International Carpathian Control Conference (ICCC)', '10.1109/ICCC65605.2025.11022788', NULL, NULL, '[]', 'To Read', '[]', 'This paper investigates and compares three control methodologies: Proportional-Integral-Derivative (PID), Linear Model Predictive Control (Linear MPC), and Nonlinear Model Predictive Control (Nonlinear MPC) for pitch and yaw regulation in a 2 Degrees of Freedom (DOF) helicopter system. The 2-DOF helicopter platform, known for its inherent instability and nonlinear dynamics, serves as a challenging testbed for advanced control strategies. PID is implemented as a baseline for its simplicity and widespread use, while Linear and Nonlinear MPC are explored for their ability to handle constraints, optimize performance, and address system dynamics. The study includes the mathematical modeling of the system, the design and tuning of each controller, and performance validation through simulations and real-world experiments. Key performance metrics, including tracking accuracy, stability, computational requirements, and robustness under disturbances, are analyzed. The results provide insights into the trade-offs between classical and optimization-based control strategies, highlighting the practical applicability of MPC in dynamic and constrained environments.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:52.058Z', '2025-12-03T09:22:52.058Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (626, 44, 'Sensor Fusion and Computer Vision Integrated System for Primary Separation Vessel Interface Level Estimation', '["Wang, Jingyi","Alipouri, Y.","Huang, Biao"]', 2021, 'IFAC-PapersOnLine', '10.1016/j.ifacol.2021.08.237', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: The sensor fusion algorithm is further integrated with computer vision system to improve frothmiddlings interface level estimation accuracy and robustness and industrial environment simulations and factory accepted test (FAT) demonstrate the advantages and effectiveness of the sensor fusion and computer vision integrated system.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:52.355Z', '2025-12-03T09:22:52.355Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (627, 44, 'Control Strategies for the Quadruple Tank System: A Comparative Study of PID and MPC', '["Rosman, Ernadia","Azam, S. N. M.","Razali, M. C."]', 2024, '2024 20th IEEE International Colloquium on Signal Processing & Its Applications (CSPA)', '10.1109/CSPA60979.2024.10525469', NULL, NULL, '[]', 'To Read', '[]', 'Control engineering faces unique challenges when dealing with interconnected tank systems, particularly those with multiple tanks. Precise and robust control is challenging due to the interdependence of water levels between tanks, leading to potential inefficiencies within the system. To address this issue, Quadruple Tank Systems (QTS) is used to study interconnected tank systems and develop effective control approaches. The QTS, comprised of four interconnected tanks, necessitates precise control of water levels in its lower tanks. To assess controller efficacy within the QTS, two case studies were tested under three control scenarios: Open Loop system, Proportional-Integral-Derivate (PID) Controller, and Model Predictive Controller (MPC). The tuning parameters for PID and MPC is determined heuristically, and the study found that MPC outperformed PID with a significant settling time of 169.38s during case 1 and 165.11s during case 2. The steady-state error has been eliminated completely, ensuring that the water level can be accurately regulated and sustained at the intended setpoint of 8cm.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:52.653Z', '2025-12-03T09:22:52.653Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (628, 44, 'A reinforcement learning-based transformed inverse model strategy for nonlinear process control', '["Dutta, Debaprasad","Upreti, S."]', 2023, 'Comput. Chem. Eng.', '10.1016/j.compchemeng.2023.108386', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:52.949Z', '2025-12-03T09:22:52.949Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (629, 44, 'Batch process control based on reinforcement learning with segmented prioritized experience replay', '["Xu, Chen","Ma, Junwei","Tao, Hongfeng"]', 2024, 'Measurement Science and Technology', '10.1088/1361-6501/ad21cf', NULL, NULL, '[]', 'To Read', '[]', 'Batch process is difficult to control accurately due to their complex nonlinear dynamics and unstable operating conditions. The traditional methods such as model predictive control, will seriously affect control performance when process model is inaccurate. In contrast, reinforcement learning (RL) provides an viable alternative by interacting directly with the environment to learn optimal strategy. This paper proposes a batch process controller based on the segmented prioritized experience replay (SPER) soft actor-critic (SAC). SAC combines off-policy updates and maximum entropy RL with an actor-critic formulation, which can obtain a more robust control strategy than other RL methods. To improve the efficiency of the experience replay mechanism in tasks with long episodes and multiple phases, a new method of sampling experience called SPER is designed in SAC. In addition, a novel reward function is set for the SPER-SAC based controller to deal with the sparse reward. Finally, the effectiveness of the SPER-SAC based controller for batch process examples is demonstrated by comparing with the conventional RL-based control methods.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:53.249Z', '2025-12-03T09:22:53.249Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (630, 44, 'Steady-state real-time optimization using transient measurements and approximated Hammerstein dynamic model: A proof of concept in an experimental rig', '["Delou, Pedro de Azevedo","Matias, José","Jäschke, Johannes","Souza, M. B. de","Secchi, A."]', 2023, 'Journal of Process Control', '10.1016/j.jprocont.2023.103111', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:53.546Z', '2025-12-03T09:22:53.546Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
