INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (632, 44, 'Supervised integrated deep deterministic policy gradient model for enhanced control of chemical processes', '["Zhang, Jiaxin","Fan, Song","Feng, Zemin","Dong, Lichun","Dai, Yiyang"]', 2024, 'Chemical Engineering Science', '10.1016/j.ces.2024.120762', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:54.315Z', '2025-12-03T09:22:54.315Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (633, 44, 'Simultaneous Process Design and Control Optimization using Reinforcement Learning', '["Sachio, Steven","Chanona, Antonio E. del-Rio","Petsagkourakis, Panagiotis"]', 2021, 'IFAC-PapersOnLine', '10.1016/j.ifacol.2021.08.293', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: An approach that uses a policy gradient method to compute the optimal policy, which is then embedded into the mathematical program is proposed and it is shown that the proposed approach outperforms current state-of-the-art control strategies.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:54.613Z', '2025-12-03T09:22:54.613Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (634, 44, 'Gas-Lift Optimization Using Physics-Informed Deep Reinforcement Learning', '["Faria, Ruan de Rezende","Capron, B.","Secchi, A.","Souza, M. B. de"]', 2024, 'Industrial &amp; Engineering Chemistry Research', '10.1021/acs.iecr.3c04615', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:54.913Z', '2025-12-03T09:22:54.913Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (635, 44, 'A data-driven tracking control framework using physics-informed neural networks and deep reinforcement learning for dynamical systems', '["Faria, R. R.","Capron, B.","Secchi, A.","Souza, Maurício B. de"]', 2024, 'Eng. Appl. Artif. Intell.', '10.1016/j.engappai.2023.107256', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:55.210Z', '2025-12-03T09:22:55.210Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (636, 44, 'Optimization of Model Predictive Control Weights for Control of Permanent Magnet Synchronous Motor by Using the Multi Objective Bees Algorithm', '["Sahin, M."]', 2021, 'Model Predictive Control - Recent Design and Implementations for Varied Applications [Working Title]', '10.5772/intechopen.98810', NULL, NULL, '[]', 'To Read', '[]', 'In this study, the model predictive control (MPC) method was used within the scope of the control of the permanent magnet synchronous motor (PMSM). The strongest aspect of the MPC, the ability to control multiple components with a single function, is also one of the most difficult parts of its design. The fact that each component of the function has different effects requires assigning different weight coefficients to these components. In this study, the Bees Algorithm (BA) is used to determine the weights. Using the multi-objective function in BA, it has been tried to determine the weights that reduce the current values together with the speed error. Three different PI controllers have been designed to compare the MPC method. The coefficients of one of these are tuned with BA. Good Gain Method and Tyreus-Luyben Method were used in the other two. As a result of experimental studies, it has been observed that MPC can control PMSM more smoothly and accurately than PI controllers, with weights optimized with BA. With MPC, PMSM has been controlled with 15% settling time than other controllers and also with no overshoot.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:55.507Z', '2025-12-03T09:22:55.507Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (637, 44, 'Constrained Model-Free Reinforcement Learning for Process Optimization', '["Pan, Elton","Petsagkourakis, Panagiotis","Mowbray, M.","Zhang, Dongda","Rio-Chanona, Antonio del"]', 2020, 'ArXiv', '10.1016/j.compchemeng.2021.107462', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: An ''oracle''-assisted constrained constrained Q-learning algorithm that guarantees the satisfaction of joint chance constraints with a high probability, which is crucial for safety critical tasks.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:55.806Z', '2025-12-03T09:22:55.806Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (638, 44, 'Direct and indirect reinforcement learning', '["Guan, Yang","Li, S.","Duan, Jingliang","Li, Jie","Ren, Yangang","Cheng, B."]', 2019, 'International Journal of Intelligent Systems', '10.1002/int.22466', NULL, NULL, '[]', 'To Read', '[]', 'Reinforcement learning (RL) algorithms have been successfully applied to a range of challenging sequential decision‐making and control tasks. In this paper, we classify RL into direct and indirect RL according to how they seek the optimal policy of the Markov decision process problem. The former solves the optimal policy by directly maximizing an objective function using gradient descent methods, in which the objective function is usually the expectation of accumulative future rewards. The latter indirectly finds the optimal policy by solving the Bellman equation, which is the sufficient and necessary condition from Bellman''s principle of optimality. We study policy gradient (PG) forms of direct and indirect RL and show that both of them can derive the actor–critic architecture and can be unified into a PG with the approximate value function and the stationary state distribution, revealing the equivalence of direct and indirect RL. We employ a Gridworld task to verify the influence of different forms of PG, suggesting their differences and relationships experimentally. Finally, we classify current mainstream RL algorithms using the direct and indirect taxonomy, together with other ones, including value‐based and policy‐based, model‐based and model‐free.', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:22:56.103Z', '2025-12-03T09:22:56.103Z', 'client_1763851738809_l3ypq2q60he', 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (639, 44, 'Towards a machine learning operations (MLOps) soft sensor for real-time predictions in industrial-scale fed-batch fermentation', '["Brett Metcalfe","Juan Camilo Acosta-Pavas","Carlos Eduardo Robles-Rodriguez","George K. Georgakilas","Theodore Dalamagas","Cesar Arturo Aceves-Lara","Fayza Daboussi","Jasper J Koehorst","David Camilo Corrales"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2024.108991', 'http://dx.doi.org/10.1016/j.compchemeng.2024.108991', NULL, '[]', 'To Read', '[]', '', NULL, NULL, NULL, NULL, NULL, '2025-12-03T09:27:36.053Z', '2025-12-03T09:27:36.053Z', 'extension', 1, NULL);
