INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (653, 44, 'PC-Gym: Benchmark environments for process control problems', '["Bloor, Maximilian","Torraca, José","Sandoval, Ilya Orson","Ahmed, Akhil","White, Martha","Mercangöz, Mehmet","Tsay, Calvin","Del Rio Chanona, Ehecatl Antonio","Mowbray, Max"]', 2026, 'Computers & Chemical Engineering', '10.1016/j.compchemeng.2025.109363', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:39.670Z', '2025-12-04T18:09:39.670Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (654, 44, 'Recent Advances in Reinforcement Learning for Chemical Process Control', '["Devarakonda, Venkata Srikar","Sun, Wei","Tang, Xun","Tian, Yuhe"]', 2025, 'Processes', '10.3390/pr13061791', NULL, NULL, '[]', 'To Read', '[]', 'This paper reviews the recent advancements of reinforcement learning (RL) for chemical process control. RL presents a systematic strategy in which the machine learning agent learns a policy of actions based on interactions with the environment. We first provide a brief overview of RL theoretic basis built on Markov decision processes (MDPs) and then move onto its application to process control. With particular interest in chemical processes, we review state-of-the-art research developments on RL for controller tuning and direct control policy learning. This work highlights the importance of safe RL control to incorporate deterministic or probabilistic safety constraints such as constrained MDPs, control barrier functions, etc. We conclude the review with a discussion on some of the outstanding challenges such as sampling efficiency, generalizability, uncertainty, and observability, as well as the emergent and future directions to address these limitations.', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:40.319Z', '2025-12-04T18:09:40.319Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (655, 44, 'Where Reinforcement Learning Meets Process Control: Review and Guidelines', '["Faria, R. R.","Capron, B.","Secchi, A.","Souza, M. B. de"]', 2022, 'Processes', '10.3390/pr10112311', NULL, NULL, '[]', 'To Read', '[]', 'This paper presents a literature review of reinforcement learning (RL) and its applications to process control and optimization. These applications were evaluated from a new perspective on simulation-based offline training and process demonstrations, policy deployment with transfer learning (TL) and the challenges of integrating it by proposing a feasible approach to online process control. The study elucidates how learning from demonstrations can be accomplished through imitation learning (IL) and reinforcement learning, and presents a hyperparameter-optimization framework to obtain a feasible algorithm and deep neural network (DNN). The study details a batch process control experiment using the deep-deterministic-policy-gradient (DDPG) algorithm modified with adversarial imitation learning.', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:41.176Z', '2025-12-04T18:09:41.176Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (656, 44, 'Deep Reinforcement Learning with Shallow Controllers: An Experimental Application to PID Tuning', '["Lawrence, Nathan P.","Forbes, M.","Loewen, Philip D.","McClement, Daniel G.","Backstrom, Johan U.","Gopaluni, R. B."]', 2021, 'ArXiv', '10.1016/j.conengprac.2021.105046', NULL, NULL, '[]', 'To Read', '[]', 'S2 TL;DR: The challenges in implementing a state of the art deep RL algorithm on a real physical system are demonstrated and the use of a PID controller as the trainable RL policy is demonstrated.', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:41.831Z', '2025-12-04T18:09:41.831Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (657, 44, 'How to support decision making with reinforcement learning in hierarchical chemical process control?', '["Szatmári, Kinga","Chován, T.","Németh, Sándor","Kummer, Alex"]', 2025, 'Chemical Engineering Journal Advances', '10.1016/j.ceja.2025.100753', NULL, NULL, '[]', 'To Read', '[]', 'null', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:42.983Z', '2025-12-04T18:09:42.983Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (658, 44, 'Reinforcement learning for optimal control of stochastic nonlinear systems', '["Zhu, Xinji","Wang, Yujia","Wu, Zhe"]', 2025, 'AIChE Journal', '10.1002/aic.18840', NULL, NULL, '[]', 'To Read', '[]', 'A reinforcement learning (RL) approach is developed in this work for nonlinear systems under stochastic uncertainty. A stochastic control Lyapunov function (SCLF) candidate is first constructed using neural networks (NNs) as an approximator to the value function, and then a control policy designed using this SCLF is developed to ensure the stability in probability of the stochastic nonlinear system. An RL algorithm is proposed for stochastic nonlinear systems to iteratively update the value function and control policy, driving them toward optimal values. We further extend its feasibility under the sample‐and‐hold implementation of control actions, and demonstrate its application to two chemical reactor examples to show its practical advantages and efficiency.', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:43.691Z', '2025-12-04T18:09:43.691Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (659, 44, 'Survey and Tutorial of Reinforcement Learning Methods in Process Systems Engineering', '["Bloor, Maximilian","Mowbray, Max","Chanona, E. A. D.","Tsay, Calvin"]', 2025, NULL, 'https://www.semanticscholar.org/paper/3958a2293542969e1f7f4d17791a2793f4dd5110', NULL, NULL, '[]', 'To Read', '[]', 'Sequential decision making under uncertainty is central to many Process Systems Engineering (PSE) challenges, where traditional methods often face limitations related to controlling and optimizing complex and stochastic systems. Reinforcement Learning (RL) offers a data-driven approach to derive control policies for such challenges. This paper presents a survey and tutorial on RL methods, tailored for the PSE community. We deliver a tutorial on RL, covering fundamental concepts and key algorithmic families including value-based, policy-based and actor-critic methods. Subsequently, we survey existing applications of these RL techniques across various PSE domains, such as in fed-batch and continuous process control, process optimization, and supply chains. We conclude with PSE focused discussion of specialized techniques and emerging directions. By synthesizing the current state of RL algorithm development and implications for PSE this work identifies successes, challenges, trends, and outlines avenues for future research at the interface of these fields.', NULL, NULL, NULL, NULL, NULL, '2025-12-04T18:09:46.065Z', '2025-12-04T18:09:46.065Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (660, 3, 'PC-Gym: Benchmark environments for process control problems', '["Maximilian Bloor","José Torraca","Ilya Orson Sandoval","Akhil Ahmed","Martha White","Mehmet Mercangöz","Calvin Tsay","Ehecatl Antonio Del Rio Chanona","Max Mowbray"]', 2026, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109363', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:23:14.744Z', '2025-12-06T13:23:14.744Z', NULL, 1, NULL);
