INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (664, 45, 'Nanopriming as an approach to induce tolerance against drought stress in wheat cultivars', '["S. M. Megahed","R. F. El-Bakatoushi","A. W. Amin","L. M. El-Sadek","M. M. Migahid"]', 2025, 'Cereal Research Communications', '10.1007/s42976-025-00688-7', NULL, NULL, '[]', 'To Read', '[]', '', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:24:25.008Z', '2025-12-06T13:27:25.944Z', 'client_1765038273493_gs5tfofki', 2, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (665, 45, 'Nanopriming as an approach to induce tolerance against drought stress in wheat cultivars', '["S. M. Megahed","R. F. El-Bakatoushi","A. W. Amin","L. M. El-Sadek","M. M. Migahid"]', 2025, 'Cereal Research Communications', '10.1007/s42976-025-00688-7', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:24:25.303Z', '2025-12-06T13:24:25.303Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (666, 45, 'Nanotechnology Approaches to Enhance Plant Stress Tolerance', '[]', NULL, NULL, NULL, NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:07.980Z', '2025-12-06T13:25:07.980Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (667, 45, 'Establishment of seed biopriming in salt stress mitigation of rice plants by mangrove derived Bacillus sp.', '["Dutta, Bhramar","Datta, Arunava","Dey, Anwesha","Ghosh, Alak K.","Bandopadhyay, Rajib"]', 2023, 'Biocatalysis and Agricultural Biotechnology', '10.1016/j.bcab.2023.102626', NULL, NULL, '[]', 'To Read', '[]', 'Salinity stress is one of the growing challenges for agro-ecosystems. Present study aimed to explore the role of halotolerant bacteria in alleviation of salinity stressed rice plants. Bacillus sp. strain PnD was isolated from Indian Sundarban Mangrove Forest, conferred plant growth promoting (PGP) traits like indole 3-acetic acid (IAA) production, phosphate solubilization, siderophore production but had negative effect of 1-aminoacyclopropane 1-carboxylate (ACC) deaminase activity. Rice seeds (Oryza sativa L.) of Amal-Mana variety were subjected to salinity stress for 24 h by being immersing in 1% NaCl. Another set of seeds were soaked in a broth cultured with Bacillus sp strain PnD, containing 1% NaCl in the media, denoted as bioprimed condition. The seeds that were soaked in distilled water had no salt stress and were not primed, served as control. All the treatments were assigned randomly to the seeds and each treatment was replicated three times resulting in nine experimental units. Completely randomized design was adopted in this experiment. Overall results showed bioprimed seeds soaked in 1% NaCl for 24 h had significantly higher germination percentage, seedling growth, photosynthetic pigments content compared to control and non-primed salinity exposed plants. Scanning electron micrograph revealed root colonization of bacteria in bioprimed seedlings, tissue distortion was also noted during salt stress. The study revealed that Bacillus sp. strain PnD is a potential plant growth promoting bacterium (PGPB), and the seed biopriming technique can efficiently mitigate inhibitory effects of salinity stress in rice plants.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:08.946Z', '2025-12-06T13:25:08.946Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (668, 45, 'Seed nano-priming with Zinc Oxide nanoparticles in rice mitigates drought and enhances agronomic profile', '["Waqas Mazhar, Muhammad","Ishtiaq, Muhammad","Hussain, Iqbal","Parveen, Abida","Hayat Bhatti, Khizar","Azeem, Muhammad","Thind, Sumaira","Ajaib, Muhammad","Maqbool, Mehwish","Sardar, Tauqeer","Muzammil, Khursheed","Nasir, Nazim","Shah, Adnan Noor"]', 2022, 'PLoS ONE', '10.1371/journal.pone.0264967', NULL, NULL, '[]', 'To Read', '[]', 'All cereal crops, particularly rice are perpetually affected due to drastic climatic changes which triggers different stressors resulting in food shortage scenarios across the globe. In modern era, application of nanotechnology holds the pledge in combating the climate change mediated environmental stressors through nanomaterials such as pesticides, nano-biosensors, nano-clays and nano-seed priming technologies. Current study is a part of experiment conducted to comprehend the behaviour of rice plants raised from Zinc Oxide nanoparticles (ZnONPs) primed seeds under the water shortage environment. The seed priming treatment concentrations included 0, 5, 10, 15, 25 and 50 ppm. In the experimental results an increase in plant height, total chlorophyll contents, plant fresh and dry weights was obtained by use of seed priming with ZnONPs. The study results proved that seed priming with 25ppm of ZnONPs increased seed and straw yield with value of 85.333 and 123.333, respectively under water deficit environment. The analysis depicted that 25 ppm has been found more suitable for increasing the 1000 paddy weight of rice plants under both well irrigated and water shortage conditions. Seed priming with ZnONPs results in 53% reduction in MDA contents of water stressed rice plants Drought stress leads to reduction in plant height by 31%, plant fresh weight by 22% and plant dry weight by 28%. Seed priming treatments imparted in current study show significance increase in plant biomass. Priming with ZnONPs further enhances the levels of proline amino acid facilitating the plant to combat water shortage stress. A further elevation in activities of SOD, CAT and POD takes place in rice plants raised from ZnONPs primed seeds by 11%, 13% and 38%, respectively. An elevation in activities of antioxidant enzymes was found and the levels of oxidative stress indicators decreased upon seed priming with ZnONPs. Furthermore the yield characteristics such as panicle length, number of tillers, paddy yield and straw yield of the rice plants raised through ZnONPs primed seeds enhanced. The ZnONPs at concentration of 25 ppm proved optimum in alleviating drought induced damages. It can be inferred that seed pre conditioning with ZnONPs is helpful in increasing yield attributes under the water shortage environment.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:09.621Z', '2025-12-06T13:25:09.621Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (669, 45, 'Zinc oxide nanopriming elevates wheat drought tolerance by inducing stress-responsive genes and physio-biochemical changes', '["Pandya, Priyanka","Kumar, Sushil","Sakure, Amar A.","Rafaliya, Rutul","Patil, Ghanshyam B."]', 2023, 'Current Plant Biology', '10.1016/j.cpb.2023.100292', NULL, NULL, '[]', 'To Read', '[]', 'Zinc oxide nanoparticles (ZnO NPs) are currently being used in a number of applications, including agriculture. In agricultural regions all throughout the world, drought poses a serious danger to crop production and development. The outcome of this experiment showed that the treatment of 250 ppm ZnO NPs provides drought resistance by considerably improving physiological and biochemical traits, viz., shoot and root length, RWC, MSI, Zn content, total chlorophyll and protein content, biomass accumulation, osmolytes content, and antioxidant enzyme activities. Similar results were found by gene expression analysis. The expression of drought-responsive genes (DHN, DREB, P5CS, BADH, SOD, CAT, APX, bZIP and NAC) were highly upregulated in ZnO- treated plants compared with non-ZnO treated root and leaf tissues of plants under stress and non-stress conditions. The osmoregulation-related genes (P5CS and BADH) were highly expressed in ZnO treated plants over non-ZnO treated samples in both conditions (stress and control). However, the relative accumulation of these genes was higher root tissues compared to leaf tissues. According to the results, ZnO NPs caused an instantaneous rise in P5CS and BADH expression, which function as stress signaling molecules and trigger the production of genes that are responsive to drought. This results in the activation of the defense system and a greater ability to withstand stress. ZnO NPs in general may, under drought conditions, influence the expression of genes that are drought-inducible via both ABA-dependent and ABA-independent pathways.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:10.291Z', '2025-12-06T13:25:10.291Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (670, 45, 'Effect of biopriming and nanopriming on physio-biochemical characteristics of Cicer arietinum L. under drought stress', '["Rani, Simran","Kumar, Pradeep","Dahiya, Priyanka","Gupta, Aditi","Arora, Kiran","Dang, Amita Suneja","Suneja, Pooja"]', 2024, 'Plant Stress', '10.1016/j.stress.2024.100466', NULL, NULL, '[]', 'To Read', '[]', 'Drought, a detrimental abiotic stress, disturbs many vital processes critical to plant growth and development resulting in subpar crop yield. Unconventional measures such as biofertilizers and nanofertilizers have been reported as reliable solutions to this, however, outcomes vary greatly depending upon the type of organism/ particle and its mode of delivery. Seed priming involves treating seeds with organic/inorganic chemicals to ameliorate drought stress by boosting pre-germinative metabolism, maintaining water potential, scavenging free radicals, etc. Therefore, this study determined the effect of biopriming and nanopriming on germination percentage (GP), leaf water status (LWS), proline, malondialdehyde (MDA), hydrogen peroxide (H₂O₂), and survial percentage (SP) of BG-4958 (Drought tolerant) and ICC-1882 (Drought sensitive) chickpea varieties exposed to polyethylene glycol (PEG) induced moderate (5 %) and severe drought (10 %) at flowering with no drought acting as a control. Experimental setup had three groups, control (untreated), bioprimed with plant growth promoting endophytic bacteria (PGPEB), and nanoprimed with CuNPs synthesised from PGPEB and their chemical counterparts). Crop analysis after 15 DDS (Days to drought stress) revealed that priming significantly altered the physio-biochemical parameters. Consortium and N2X led highest increment in GP and SP for DT and DS varieties, respectively, whereas N1X showed highest increase in LWS of both. Highest accumulation of proline was observed with consortium and N1 (X & Y) in DS variety while only biological CuNPs accumulated proline for DT variety. MDA and H₂O₂ decreased significantly in treated groups thereby reducing oxidative damage with non-significant variations in DT. Lower concentrations of biological CuNPs were found to be more effective in modulating the physio-biochemical machinery of chickpea under drought than their higher concentration as well as chemical counterparts. This study deepens our understanding of the beneficial role of PGPEB and biosynthesized CuNPs in alleviating the adverse effects of drought in chickpea.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:11.104Z', '2025-12-06T13:25:11.104Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (671, 45, 'Nano-priming: Improving plant nutrition to support the establishment of sustainable agriculture under heavy metal stress', '["Faizan, Mohammad","Sharma, Pooja","Sultan, Haider","Alam, Pravej","Sehar, Shafaque","Rajput, Vishnu D.","Hayat, Shamsul"]', 2024, 'Plant Nano Biology', '10.1016/j.plana.2024.100096', NULL, NULL, '[]', 'To Read', '[]', 'Heavy metals (HMs) have become a severe problem for all living organisms, including plants, because of their unprecedented bioaccumulation and biomagnification in the environment. When exposed to hazardous quantities of HMs, various essential cellular macromolecules, including DNA and nuclear proteins, can interact with HMs, causing an overproduction of reactive oxygen species (ROS). Recently, several techniques have been used to ameliorate HM toxicity, including nano-priming, which effectively modulates plant physiological and biochemical responses under HM stress. This review summarizes the literature on the effectiveness of nanopriming for boosting germination, growth, photosynthetic efficiency, biomass accumulation, and crop yield. Additionally, information regarding the application of nano-priming to reduce HM toxicity in plants is reviewed. Future research prospects are indicated by highlighting the knowledge gaps in the current literature and underlining the need optimize and validate nano-priming techniques and their physiological effects on plants.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:11.915Z', '2025-12-06T13:25:11.915Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (672, 45, 'Nanopriming boost seed vigor: Deeper insights into the effect mechanism', '["Yang, Le","Zhang, Laitong","Zhang, Qi","Wei, Jinpeng","Zhao, Xueming","Zheng, Zian","Chen, Bingxian","Xu, Zhenjiang"]', 2024, 'Plant Physiology and Biochemistry', '10.1016/j.plaphy.2024.108895', NULL, NULL, '[]', 'To Read', '[]', 'Nanopriming, an advanced seed priming technology, is highly praised for its environmental friendliness, safety, and effectiveness in promoting sustainable agriculture. Studies have shown that nanopriming can enhance seed germination by stimulating the expression of aquaporins and increasing amylase production. By applying an appropriate concentration of nanoparticles, seeds can generate reactive oxygen species (ROS), enhance their antioxidant capacity, improve their response to oxidative stress, and enhance their tolerance to both biotic and abiotic stresses. This positive impact extends beyond the seed germination and seedling growth stages, persisting throughout the entire life cycle. This review offers a comprehensive overview of recent research progress in seed priming using various nanoparticles, while also addressing current challenges and future opportunities for sustainable agriculture.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:12.579Z', '2025-12-06T13:25:12.579Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (673, 45, 'Nanopriming technology enhances vigor and mitotic index of aged Vicia faba seeds using chemically synthesized silver nanoparticles', '["Younis, M.E.","Abdel-Aziz, H.M.M.","Heikal, Y.M."]', 2019, 'South African Journal of Botany', '10.1016/j.sajb.2019.08.018', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:13.462Z', '2025-12-06T13:25:13.462Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (674, 45, 'Nanopriming with zero valent iron (nZVI) enhances germination and growth in aromatic rice cultivar (Oryza sativa cv. Gobindabhog L.)', '["Guha, Titir","Ravikumar, K.V.G.","Mukherjee, Amitava","Mukherjee, Anita","Kundu, Rita"]', 2018, 'Plant Physiology and Biochemistry', '10.1016/j.plaphy.2018.04.014', NULL, NULL, '[]', 'To Read', '[]', 'Engineered nanoparticles are utilized in agriculture for various purposes. They can be used as fertilizer, carrier for macro/micro nutrients or priming agents. Various nanoparticles are reported to have toxicity at very high doses, but at optimum concentration, they can be beneﬁcial for plant growth and development. In the present study, low concentrations of nZVI nanoparticles were evaluated for their growth enhancement potential as seed priming agent in an aromatic rice cultivar, Oryza sativa cv. Gobindabhog. Seeds were primed with diﬀerent concentrations (10, 20, 40, 80, 160 mg L−1) of nZVI and allowed to grow for 14 days. Seed germination and seedling growth were studied by assessing physiological, biochemical, and structural parameters at diﬀerent time points. Maximum activities of hydrolytic and antioxidant enzymes, along with root dehydrogenase enzyme were observed in 20 mg L−1 nZVI primed seeds. Priming with low doses of nZVI increased seedling vigour, as expressed by increased root and shoot length, biomass and photosynthetic pigment content. Our study also conﬁrmed that after 14 days growth, the seedling showed absence of membrane damage, reduction in proline level and anti-oxidant enzyme activities. However, seedlings primed with 160 mg L−1 nZVI suﬀered oxidative stress. SEM micrographs also revealed damage in root tissue at that concentration. AAS study conﬁrmed uptake of nZVI by the rice plants as maximum level of iron was found in the plants treated with highest concentration (i.e. 160 mg L−1 nZVI). Thus, nZVI at low concentrations can be considered as priming agent of rice seeds for increasing plant vigour.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:14.126Z', '2025-12-06T13:25:14.126Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (675, 45, 'Nano-Priming Techniques for Plant Physio-Biochemistry and Stress Tolerance', '["Imtiaz, Havza","Shiraz, Mohammad","Mir, Anayat Rasool","Siddiqui, Husna","Hayat, Shamsul"]', 2023, 'J Plant Growth Regul', '10.1007/s00344-023-10981-6', NULL, NULL, '[]', 'To Read', '[]', 'Abiotic and biotic stresses hamper our agricultural productivity by reducing crop growth, leading to food crises all over the globe. At present, the main objective of environmentalists is to ensure food safety by improving crop production in stressful environment. To achieve this goal, nanotechnology is a promising tool to sustainably promote food production. Seed nanopriming has emerged as a successful method to activate not only seed germination and seedling establishment but also the growth of the plant. Here we are focusing on some important benefits of seed nano-priming, like rapid germination, better plant growth, and higher yield. Furthermore, an attempt has been made to explain seed priming technology, mechanism of seed germination along with molecular, biochemical, and physiological changes on nano-priming. The data presented in this review prove that nano-priming can mitigate abiotic and biotic stresses and provide an option to raise a resilient crop. This review has also highlighted the challenges and limitations in using seed nano-priming for sustainable agriculture. We have also discussed here future possibility of usage of endophytes due to their enormous benefits to host and non-host plants, as well in seed germination and in abiotic stress tolerance via seed priming, with different innovative seed coating techniques, which could be used as potential technology in advancing dynamic and sustainable agriculture.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:14.792Z', '2025-12-06T13:25:14.792Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (676, 45, 'Nanotechnology: an Integrated Approach Towards Agriculture Production and Environmental Stress Tolerance in Plants', '["Ullah, Izhar","Toor, Muhammad Danish","Basit, Abdul","Mohamed, Heba I.","Gamal, Mohammed","Tanveer, Nouraiz Ahmed","Shah, Syed Tanveer"]', 2023, 'Water Air Soil Pollut', '10.1007/s11270-023-06675-0', NULL, NULL, '[]', 'To Read', '[]', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:15.465Z', '2025-12-06T13:25:15.465Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (677, 45, 'Nanoceria seed priming enhanced salt tolerance in rapeseed through modulating ROS homeostasis and α-amylase activities', '["Khan, Mohammad Nauman","Li, Yanhui","Khan, Zaid","Chen, Linlin","Liu, Jiahao","Hu, Jin","Wu, Honghong","Li, Zhaohu"]', 2021, 'J Nanobiotechnol', '10.1186/s12951-021-01026-9', NULL, NULL, '[]', 'To Read', '[]', 'Background: Salinity is a big threat to agriculture by limiting crop production. Nanopriming (seed priming with nanomaterials) is an emerged approach to improve plant stress tolerance; however, our knowledge about the underlying mechanisms is limited.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:16.128Z', '2025-12-06T13:25:16.128Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (678, 45, 'Nanotechnology: a novel and sustainable approach towards heavy metal stress alleviation in plants', '["Ahmad, Bilal","Zaid, Abbu","Zulfiqar, Faisal","Bovand, Fatemeh","Dar, Tariq Ahmad"]', 2023, 'Nanotechnol. Environ. Eng.', '10.1007/s41204-022-00230-8', NULL, NULL, '[]', 'To Read', '[]', 'Heavy metals (HMs) constitute one of the most detrimental environmental constraints putting at risk diverse life-forms including plants. HMs profoundly hinder plant metabolism, by disrupting the functioning of imperative cellular biomolecules resulting in severely affected crop yields. Among the diverse strategies adopted to alleviate heavy metal (HM) toxicity, application of nanoparticles (NPs) constitutes a comparatively recent, efficient and promising approach as compared to conventional plant growth regulators. The competence of NPs as stress alleviators is endorsed to their ability to decrease the mobility of HMs in soil thereby reducing their availability, improved ability of apoplastic barrier which hinders their translocation in the plant, fortified plant antioxidant system by boosting the activities of the different enzymatic and non-enzymatic antioxidants, mimetic activities of certain NPs as antioxidants and increased production of secondary metabolites particularly phenols. Plant phenolics, in addition to other chemo-ecological roles, serve as potent stress alleviators. The current article encompasses the role of NPs in remediation of HMs from contaminated agricultural soils and aquatic ecosystems. This article also focuses on the role of different types of NPs in alleviating HM toxicity in plants and the possible underlying mechanism.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:16.791Z', '2025-12-06T13:25:16.791Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (679, 45, 'Impact assessment of engineered nanotitanium dioxide seed priming on oxidoreductase enzyme activities in seedlings of Kidney bean (Phaseolus vulgaris L.)', '["Paul, Alpana","Raha, Priyankar","Prajapati, Brijmohan","Kundu, Arnab"]', 2020, 'J Pharmacogn Phytochem', '10.22271/phyto.2020.v9.i4i.11770', NULL, NULL, '[]', 'To Read', '[]', 'A laboratory experiment was performed to study the effects of nano-TiO2 polymorphs priming on seedling growth and antioxidant enzyme activities of Kidney bean (Phaseolus vulgaris L.). Nano-TiO2 polymorphs i.e. anatase and rutile, were synthesized by the sol-gel method using titanium tetraisopropoxide as Ti-precursor and 2-propanol as solvent. Seeds of Kidney bean were treated with nine different concentrations (in water) of each nano-TiO2 polymorphs (0, 0.10, 0.25, 0.50, 0.75, 1.00, 1.50, 2.00 and 2.50%) by soaking in different concentrations suspension (prepared by ultrasonication method) for 24 hours. The growth of seedlings and activity antioxidant enzymes i.e. catalase and peroxidase were assessed at three weeks following paper towel method of germination. The results showed that increase in concentration of each nano-TiO2 polymorphs caused a significant increase in root and shoot length (79-97%) as well as number of lateral roots of the seedlings of kidney bean. The findings illustrated the beneficial effect of nano-TiO2 polymorphs priming on seedling growth and antioxidant enzyme activities viz. catalase (78-80%) and peroxidase (75-162%) of Kidney bean.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:17.971Z', '2025-12-06T13:25:17.971Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (680, 45, 'Linking metabolite production to taxonomic identity in environmental samples by (MA)LDI-FISH', '["Kaltenpoth, Martin","Strupat, Kerstin","Svatoš, Aleš"]', 2016, 'ISME J', '10.1038/ismej.2015.122', NULL, NULL, '[]', 'To Read', '[]', 'One of the greatest challenges in microbial ecology remains to link the metabolic activity of individual cells to their taxonomic identity and localization within environmental samples. Here we combined mass-spectrometric imaging (MSI) through (matrix-assisted) laser desorption ionization time-of-flight MSI ([MA]LDI-TOF/MSI) with fluorescence in situ hybridization (FISH) to monitor antibiotic production in the defensive symbiosis between beewolf wasps and ‘Streptomyces philanthi'' bacteria. Our results reveal similar distributions of the different symbiont-produced antibiotics across the surface of beewolf cocoons, which colocalize with the producing cell populations. Whereas FISH achieves single-cell resolution, MSI is currently limited to a step size of 20–50 μm in the combined approach because of the destructive effects of high laser intensities that are associated with tighter laser beam focus at higher lateral resolution. However, on the basis of the applicability of (MA)LDI-MSI to a broad range of small molecules, its combination with FISH provides a powerful tool for studying microbial interactions in situ, and further modifications of this technique could allow for linking metabolic profiling to gene expression.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:18.867Z', '2025-12-06T13:25:18.867Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (681, 45, 'The Vacuolar Manganese Transporter MTP8 Determines Tolerance to Iron Deficiency-Induced Chlorosis in Arabidopsis', '["Eroglu, Seckin","Meier, Bastian","von Wirén, Nicolaus","Peiter, Edgar"]', 2016, 'Plant Physiol', '10.1104/pp.15.01194', NULL, NULL, '[]', 'To Read', '[]', 'Iron (Fe) deficiency is a widespread nutritional disorder on calcareous soils. To identify genes involved in the Fe deficiency response, Arabidopsis (Arabidopsis thaliana) transfer DNA insertion lines were screened on a high-pH medium with low Fe availability. This approach identified METAL TOLERANCE PROTEIN8 (MTP8), a member of the Cation Diffusion Facilitator family, as a critical determinant for the tolerance to Fe deficiency-induced chlorosis, also on soil substrate. Subcellular localization to the tonoplast, complementation of a manganese (Mn)-sensitive Saccharomyces cerevisiae yeast strain, and Mn sensitivity of mtp8 knockout mutants characterized the protein as a vacuolar Mn transporter suitable to prevent plant cells from Mn toxicity. MTP8 expression was strongly induced on low-Fe as well as high-Mn medium, which were both strictly dependent on the transcription factor FIT, indicating that high-Mn stress induces Fe deficiency. mtp8 mutants were only hypersensitive to Fe deficiency when Mn was present in the medium, which further suggested an Mn-specific role of MTP8 during Fe limitation. Under those conditions, mtp8 mutants not only translocated more Mn to the shoot than did wild-type plants but suffered in particular from critically low Fe concentrations and, hence, Fe chlorosis, although the transcriptional Fe deficiency response was up-regulated more strongly in mtp8. The diminished uptake of Fe from Mn-containing low-Fe medium by mtp8 mutants was caused by an impaired ability to boost the ferric chelate reductase activity, which is an essential process in Fe acquisition. These findings provide a mechanistic explanation for the long-known interference of Mn in Fe nutrition and define the molecular processes by which plants alleviate this antagonism.', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:19.530Z', '2025-12-06T13:25:19.530Z', NULL, 1, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (682, 45, 'FIGNL1 inhibits homologous recombination in BRCA2 deficient cells by dissociating RAD51 filaments', '["Kuthethur, Raviprasad","Acharya, Ananya","Sengodan, Satheesh Kumar","Fonseca, Carmen","Nagar, Nupur","Nasrin Vz, Safa","Ibini, Oluwakemi","Manolika, Eleni-Maria","De Koning, Kelly","Braunshier, Stefan","Dessapt, Julien","Fradet-Turcotte, Amélie","Lebbink, Joyce H.G.","Kanaar, Roland","Poluri, Krishna Mohan","Sharan, Shyam K.","Cejka, Petr","Chaudhuri, Arnab Ray"]', 2024, NULL, '10.1101/2024.11.03.621741', NULL, NULL, '[]', 'Finished', '[]', 'ABSTRACT', NULL, NULL, NULL, NULL, NULL, '2025-12-06T13:25:20.203Z', '2025-12-06T13:29:04.276Z', 'client_1765038273493_gs5tfofki', 2, NULL);
INSERT OR IGNORE INTO papers (id, user_id, title, authors, year, journal, doi, url, abstract, tags, status, related_paper_ids, notes, summary, rating, pdf_url, pdf_size_bytes, reading_progress, created_at, updated_at, client_id, version, deleted_at) VALUES (683, 2, 'Q-learning agent-based level control of surge tanks for improved continuous manufacturing of monoclonal antibodies', '["Naveen G Jesubalan","Saxena Nikita","Shantanu Banerjee","Navnath Deore","Keshari Gupata","Anurag S Rathore"]', 2025, 'Computers &amp; Chemical Engineering', '10.1016/j.compchemeng.2025.109514', NULL, NULL, '["Process Control","Reinforcement Learning","Bioprocessing","Level Control","Q-Learning","Discrete Action Space","Surge Tank Management","Safety Constraints via Reward","Temel Yöntem Kıyaslaması","Literatür Örneği"]', 'To Read', '[]', '<li><p data-path-to-node="6,1,0"><b data-path-to-node="6,1,0" data-index-in-node="0">Destekleyici/Karşıt Nitelik:</b> <b data-path-to-node="6,1,0" data-index-in-node="29">Metodolojik Kıyaslama ve Üstünlük Kanıtı</b></p><ul data-path-to-node="6,1,1"><li><p data-path-to-node="6,1,1,0,0"><b data-path-to-node="6,1,1,0,0" data-index-in-node="0">- Destekleyici Yön:</b> Makale, klasik mantıksal kontrollerin (ON/OFF veya basit kurallar) dinamik süreçlerde yetersiz kaldığını ve RL''in bu boşluğu doldurduğunu kanıtlayarak projenizin temel motivasyonunu destekler.</p></li><li><p data-path-to-node="6,1,1,0,0"><br></p></li><li><p data-path-to-node="6,1,1,1,0"><b data-path-to-node="6,1,1,1,0" data-index-in-node="0">- Sizin Projenizin Üstünlüğü:</b> Bu makale, durum ve aksiyonları "ayrıklaştırmak" (discrete bins) zorunda kalan <b data-path-to-node="6,1,1,1,0" data-index-in-node="107">Q-Learning</b> kullanmıştır. Sizin projenizdeki <b data-path-to-node="6,1,1,1,0" data-index-in-node="151">Soft Actor-Critic (SAC)</b> ise sürekli (continuous) aksiyon uzayında çalışır. Raporunuzda bu makaleyi alıntılayarak şunu diyebilirsiniz: <i data-path-to-node="6,1,1,1,0" data-index-in-node="285">"Jesubalan ve ark. (2026), tank seviyesi gibi daha basit sistemlerde ayrık Q-Learning kullanmışken, CSTR gibi hassas kontrol gerektiren sistemlerde sürekli kontrol sağlayan SAC algoritması tercih edilmiştir."</i> Bu, projenizin teknik derinliğini vurgular.</p></li><li><p data-path-to-node="6,1,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="6,2,0"><b data-path-to-node="6,2,0" data-index-in-node="0">Proje İçin Kritik Çıkarımlar (Transfer Edilebilir Bilgiler):</b></p><ul data-path-to-node="6,2,1"><li><p data-path-to-node="6,2,1,0,0"><b data-path-to-node="6,2,1,0,0" data-index-in-node="0">- Güvenlik Sınırları (Safety Constraints):</b> Makalede tankın taşması veya tamamen boşalması "istenmeyen durum" olarak tanımlanıp ağır şekilde cezalandırılmıştır (<span class="math-inline" data-math="R_p = -1" data-index-in-node="158"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.9694em; vertical-align: -0.2861em;"></span><span class="mord"><span style="margin-right: 0.0077em;" class="mord mathnormal">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.1514em;"><span class="" style="top: -2.55em; margin-left: -0.0077em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height: 0.2861em;"><span class=""></span></span></span></span></span></span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.7278em; vertical-align: -0.0833em;"></span><span class="mord">−</span><span class="mord">1</span></span></span></span></span>). Sizin projenizde de "Termal Kaçak" (Runaway) durumu benzer bir mantıkla, ajanın asla girmemesi gereken bir "yasak bölge" olarak ödül fonksiyonuna (negatif ödül/ceza) eklenebilir.</p></li><li><p data-path-to-node="6,2,1,1,0"><b data-path-to-node="6,2,1,1,0" data-index-in-node="0">- Simülasyon Ortamı:</b> Makale, gerçek sisteme geçmeden önce Python tabanlı bir "Custom Environment" (Gym kütüphanesi benzeri) tasarlamıştır. Sizin de CSTR simülasyonunuzu Python''da OpenAI Gym (yeni adıyla Gymnasium) formatında standartlaştırmanız, literatürle uyumlu bir pratik olacaktır.</p></li><li><p data-path-to-node="6,2,1,1,0"><br></p></li></ul></li><li><p data-path-to-node="6,3,0"><b data-path-to-node="6,3,0" data-index-in-node="0">Eksik/Farklı Yönler:</b></p><ul data-path-to-node="6,3,1"><li><p data-path-to-node="6,3,1,0,0"><b data-path-to-node="6,3,1,0,0" data-index-in-node="0">- Fiziksel Derinlik:</b> Makaledeki fizik (sıvı kütle denkliği: Giren - Çıkan = Biriken) oldukça basittir. Sizin projenizdeki Arrhenius kinetiği ve enerji denklikleri çok daha karmaşıktır.</p></li><li><p data-path-to-node="6,3,1,1,0"><b data-path-to-node="6,3,1,1,0" data-index-in-node="0">- Algoritma:</b> Onlar Q-Table (Excel tablosu gibi bir hafıza) kullanırken, siz Derin Sinir Ağları (Neural Networks) kullanıyorsunuz.</p></li></ul><div><br></div></li>', '<li><p data-path-to-node="3,0,0"><b data-path-to-node="3,0,0" data-index-in-node="0">Amaç:</b> Monoklonal antikorların (mAb) sürekli üretim hattında kullanılan dengeleme tanklarının (surge tanks) seviye kontrolünü optimize etmek. Geleneksel ve rijit "AÇ/KAPA" (ON/OFF) kontrol stratejileri yerine, süreçteki bozulmaları (disturbances) ve akış değişimlerini daha yumuşak yönetebilen bir Pekiştirmeli Öğrenme (RL) ajanı geliştirmek.</p></li><div><br></div><li><p data-path-to-node="3,1,0"><b data-path-to-node="3,1,0" data-index-in-node="0">Metodoloji:</b></p><ul data-path-to-node="3,1,1"><li><p data-path-to-node="3,1,1,0,0"><b data-path-to-node="3,1,1,0,0" data-index-in-node="0">- Sistem:</b> Biyofarmasötik üretim hattındaki birbirine bağlı 3 adet dengeleme tankı (Surge Tanks).</p></li><li><p data-path-to-node="3,1,1,1,0"><b data-path-to-node="3,1,1,1,0" data-index-in-node="0">- Algoritma:</b> <b data-path-to-node="3,1,1,1,0" data-index-in-node="11">Q-Learning</b> (Tablo tabanlı/Tabular RL). Bu yöntem, durum (seviye) ve aksiyon (pompa hızı) uzayının ayrıklaştırılmasını (discretization) gerektirir.</p></li><li><p data-path-to-node="3,1,1,2,0"><b data-path-to-node="3,1,1,2,0" data-index-in-node="0">- Yöntem:</b> Python ortamında simüle edilen süreçte, ajan tank seviyesini belirli sınırlar (3-15 cm) arasında tutmak için eğitilmiştir. Ödül fonksiyonu, tankın taşmasını veya boşalmasını cezalandıracak şekilde kurgulanmıştır.</p></li><li><p data-path-to-node="3,1,1,2,0"><br></p></li></ul></li><li><p data-path-to-node="3,2,0"><b data-path-to-node="3,2,0" data-index-in-node="0">Temel Bulgular:</b></p><ul data-path-to-node="3,2,1"><li><p data-path-to-node="3,2,1,0,0">- Q-Learning ajanı, geleneksel kontrolcüye kıyasla tank seviyelerini hedef aralıkta tutmada çok daha başarılı olmuştur.</p></li><li><p data-path-to-node="3,2,1,1,0">- Pompa dur-kalk hareketlerini azaltarak akış rejimini yumuşatmış (smoother flow), bu da hattın genel kararlılığını artırmıştır.</p></li><li><p data-path-to-node="3,2,1,2,0">- Beklenmedik bozulmalara karşı sistemin dayanıklılığını (robustness) kanıtlamıştır.</p></li></ul></li>', 5, 'papers/2/683/Q-learning_agent-based_level_control_of_surge_tanks_for_improved.pdf', 5122341, NULL, '2025-12-06T14:07:12.489Z', '2026-01-22T00:50:43.775Z', 'client_1763443786605_6w2tm45ddct', 6, NULL);
